@superset_app.command("import-org")
def superset_import_org_cmd(
    path: Annotated[
        Path, typer.Argument(help="Path to a .org dashboard source file")
    ],
    emit_only: Annotated[
        Optional[Path],
        typer.Option("--emit-only",
                     help="Write the bundle zip to PATH and exit "
                          "(default: ./out.zip if --post not given)")
    ] = None,
    post: Annotated[
        Optional[str],
        typer.Option("--post",
                     help="POST the bundle to Superset at URL "
                          "(e.g. http://localhost:8088)")
    ] = None,
    user: Annotated[
        Optional[str],
        typer.Option("--user", "-u",
                     help="Superset username (defaults to admin)")
    ] = None,
    password: Annotated[
        Optional[str],
        typer.Option("--password", "-p",
                     help="Superset password (defaults to admin)")
    ] = None,
):
    """Import an .org dashboard source into Superset.

    Parses #+TITLE / #+SUPERSET_DASHBOARD / #+SUPERSET_DATABASE
    headers + named #+BEGIN_SRC sql blocks, projects them onto
    Superset's v1 import-bundle shape (metadata.yaml + databases/
    + datasets/ + charts/ + dashboards/), and either writes the
    zip or POSTs it to /api/v1/dashboard/import/.

    Reuses dataset/database UUIDs from the semantic-layer registry
    so a chart imported here and a `metric:llm_avg_ms` query from
    `@analyst` answer with identical numbers.
    """
    from .superset_import import OrgDashboard

    if not path.exists():
        on_screen(f"[red]not found:[/red] {path}")
        raise typer.Exit(1)

    od = OrgDashboard.from_org(path)
    on_screen(
        f"[lcars2]parsed[/lcars2] {path.name} → "
        f"dashboard={od.slug!r}, charts={len(od.charts)}"
    )
    for chart in od.charts:
        on_screen(
            f"  [bold]{chart.name}[/bold]  "
            f"metric={chart.metric_name}  "
            f"viz={chart.viz_type}  "
            f"group_by={chart.group_by or '-'}"
        )

    if post is None and emit_only is None:
        # Default: emit to ./out.zip in the current directory.
        emit_only = Path("./out.zip")

    if emit_only is not None:
        out = od.write_zip(emit_only)
        on_screen(f"[lcars2]wrote bundle[/lcars2] {out}")

    if post is not None:
        auth = (user or "admin", password or "admin")
        try:
            resp = od.post(post, auth=auth)
        except Exception as e:
            on_screen(f"[red]POST failed:[/red] {e}")
            raise typer.Exit(2)
        on_screen(f"[lcars2]posted to[/lcars2] {post}")
        on_screen(f"  response: {resp}")


@superset_app.command("prune")
def superset_prune_cmd(
    older_than: Annotated[
        str,
        typer.Option("--older-than",
                     help="Cutoff age, e.g. 30d / 7d / 24h / 2w "
                          "(default: 30d)")
    ] = "30d",
    dry_run: Annotated[
        bool,
        typer.Option("--dry-run/--apply",
                     help="Default --dry-run lists candidates without "
                          "deleting; --apply performs DELETEs")
    ] = True,
    url: Annotated[
        str,
        typer.Option("--url",
                     help="Superset base URL")
    ] = "http://localhost:8088",
    auth: Annotated[
        Optional[str],
        typer.Option("--auth",
                     help="USER:PASS for the Superset login flow. If "
                          "omitted, falls back to admin:admin (the "
                          "single-user default per superset.org § "
                          "Hosting & install).")
    ] = None,
):
    """Prune old org-llm-created Superset dashboards.

    Recognizes org-llm dashboards by slug convention — anything
    matching `oneoff-…` or `pinned-…` is considered owned by the
    preprocessor / persistent-console templates. User-authored
    dashboards with arbitrary slugs are left alone.

    Cascade order on --apply: charts → dashboards → datasets. The
    shared database link is never deleted — it is reused across all
    org-llm dashboards.
    """
    from .superset_prune import (
        SupersetClient,
        build_candidates,
        execute_prune,
        parse_duration,
        split_auth,
    )

    try:
        cutoff = parse_duration(older_than)
    except ValueError as e:
        on_screen(f"[red]invalid --older-than:[/red] {e}")
        raise typer.Exit(1)

    if auth is None:
        creds = ("admin", "admin")
    else:
        try:
            creds = split_auth(auth)
        except ValueError as e:
            on_screen(f"[red]invalid --auth:[/red] {e}")
            raise typer.Exit(1)

    try:
        client = SupersetClient(url, creds)
    except Exception as e:
        on_screen(f"[red]auth failed against {url}:[/red] {e}")
        raise typer.Exit(2)

    try:
        dashboards = client.list_dashboards()
    except Exception as e:
        on_screen(f"[red]list dashboards failed:[/red] {e}")
        raise typer.Exit(2)

    candidates = build_candidates(
        dashboards,
        cutoff=cutoff,
        fetch_charts=client.get_dashboard_charts,
        fetch_datasets=client.get_dashboard_datasets,
    )

    if not candidates:
        on_screen(
            f"[lcars2]no org-llm dashboards found at[/lcars2] {url} "
            "[dim](slug must start with oneoff- or pinned-)[/dim]"
        )
        return

    tbl = Table(box=None, pad_edge=False, show_header=True)
    tbl.add_column("slug", style="lcars2")
    tbl.add_column("created_at", style="dim")
    tbl.add_column("age", justify="right")
    tbl.add_column("will_delete?", justify="center")
    for c in candidates:
        flag = "[red]yes[/red]" if c.will_delete else "[dim]no[/dim]"
        tbl.add_row(
            c.slug,
            c.created_at.strftime("%Y-%m-%d %H:%M"),
            c.age_human(),
            flag,
        )
    console.print(tbl)

    targets = [c for c in candidates if c.will_delete]
    if not targets:
        on_screen(
            f"[lcars2]nothing older than {older_than}[/lcars2]"
        )
        return

    if dry_run:
        on_screen(
            f"[lcars2]dry-run:[/lcars2] {len(targets)} dashboard(s) "
            f"would be deleted (re-run with --apply to do it)"
        )
        return

    try:
        counts = execute_prune(client, candidates)
    except Exception as e:
        on_screen(f"[red]prune failed mid-run:[/red] {e}")
        raise typer.Exit(2)
    on_screen(
        f"[lcars2]pruned[/lcars2] "
        f"{counts['charts']} charts, "
        f"{counts['dashboards']} dashboards, "
        f"{counts['datasets']} datasets"
    )


@superset_app.command("verify")
def superset_verify_cmd(
    url: Annotated[
        str,
        typer.Option("--url", help="Superset base URL")
    ] = "http://localhost:8088",
    user: Annotated[
        str,
        typer.Option("--user", "-u", help="Superset username")
    ] = "admin",
    password: Annotated[
        str,
        typer.Option("--password", "-p", help="Superset password")
    ] = "admin",
    dashboard: Annotated[
        Optional[str],
        typer.Option("--dashboard",
                     help="Verify only this dashboard's charts (slug). "
                          "Omit to verify every chart in the workspace.")
    ] = None,
    screenshots: Annotated[
        Optional[Path],
        typer.Option("--screenshots",
                     help="Save per-chart PNGs into this directory.")
    ] = None,
    timeout_ms: Annotated[
        int,
        typer.Option("--timeout-ms",
                     help="Per-chart Playwright navigation timeout")
    ] = 30000,
):
    """Headless-render every Superset chart and report any that fail.

    The chart-data API can return HTTP 200 with clean SQL while the
    React/echarts client still fails to render — wrong form_data
    shape (e.g. heatmap_v2 needing singular `metric` instead of
    `metrics: [...]`), missing x_axis on echarts_timeseries_*,
    control-panel required fields. This verb catches that whole
    class of bug by actually rendering each chart in headless
    Chromium and scanning the DOM for known error markers.

    Requires the Superset venv (default
    ~/.local/share/org-llm/superset-venv) to have Playwright +
    Chromium installed. Override via ORG_LLM_SUPERSET_VENV.

    Exit codes: 0 if every chart rendered, 1 if any failed, 2 if
    the runner couldn't reach Superset.
    """
    from .superset_verify import superset_venv_present, verify

    if not superset_venv_present():
        on_screen(
            "[red]Superset venv not found.[/red] Install per "
            "[bold]docs/wiki/superset.org § Hosting & install[/bold] "
            "or set ORG_LLM_SUPERSET_VENV to override the path."
        )
        raise typer.Exit(2)

    try:
        results = verify(
            url=url,
            user=user,
            password=password,
            dashboard_slug=dashboard,
            screenshot_dir=screenshots,
            timeout_ms=timeout_ms,
        )
    except Exception as e:
        on_screen(f"[red]verify runner failed:[/red] {e}")
        raise typer.Exit(2)

    if not results:
        on_screen("[dim](no charts found to verify)[/dim]")
        return

    tbl = Table(box=None, pad_edge=False, show_header=True)
    tbl.add_column("id", justify="right", style="dim")
    tbl.add_column("chart")
    tbl.add_column("status", justify="center")
    tbl.add_column("error", style="red")
    fails = 0
    for r in results:
        status = "[green]✓[/green]" if r.ok else "[red]✗[/red]"
        if not r.ok:
            fails += 1
        tbl.add_row(str(r.chart_id), r.name, status, r.error or "")
    console.print(tbl)

    if fails:
        on_screen(
            f"[red]{fails}/{len(results)} chart(s) failed[/red] — "
            f"see error column above"
        )
        raise typer.Exit(1)
    on_screen(
        f"[lcars2]all {len(results)} chart(s) rendered[/lcars2]"
    )


