        flag = "" if r.enabled else "  [dim](disabled)[/dim]"
        on_screen(f"  [lcars2]{r.birth_name:14s}[/lcars2]  "
                  f"{(r.description or '')[:60]}  "
                  f"[dim]pack={r.pack} origin={r.origin}[/dim]{flag}")


