def _render_agent_block_for_opencode(
    agents_list: list,
    cfg_rows: dict,
    default_model: str,
    provider_id: str,
) -> dict[str, dict]:
    """Render the `agent` map for opencode.json. One entry per
    (birth_name + each alias). The alias entries are full clones
    (same prompt + model) so opencode autocomplete + routing
    works against any of them; the `x_org_llm_birth_name` field
    lets the proxy collapse them back to one canonical agent
    when logging or running role-based checks.
    """
    out: dict[str, dict] = {}
    for a in agents_list:
        if not a.addressable:
            continue
        resolved_model = _resolve_agent_model(
            a.model_role, cfg_rows, default_model, provider_id,
        )
        base: dict = {
            "mode":        "all",
            "description": a.description,
            "prompt":      a.persona,
            "x_org_llm_birth_name": a.birth_name,
            "x_org_llm_aliases":    list(a.aliases),
            "x_org_llm_pack":       a.pack,
        }
        if resolved_model:
            base["model"] = resolved_model
        for n in a.all_names():
            out[n] = dict(base)
    return out


def _benchmark_local_models(
    *, url: str, vram_gb: float | None, ram_gb: float,
    role_filter: str = "",
) -> list[dict]:
    """Run a real tok/s benchmark on every PULLED Ollama model that
    fits this hardware, optionally scoped to one role.

    Returns a list of result dicts (keys: tag, stem, params, vram,
    roles, time, tok_s, qual, score, ok | err) — same shape used by
    `--benchmark` and `--upgrade`. Prints inline per-model progress
    so the user sees live feedback.

    Suppresses the inline lag-detector while the benchmark itself
    runs — otherwise every slow model trips the warning ("X ran 12s,
    Y is faster, Tune: org-llm models --upgrade") DURING the very
    upgrade run we're inside. Self-referential noise; the per-model
    table at the end is the authoritative ranking.
    """
    from .models import _quality, CATALOG, fitting_hardware
    from .llm import chat as _chat, list_models as _list_models
    import time as _t
    import os as _os
    _prev_lag = _os.environ.get("ORG_LLM_LAG_DETECTOR", None)
    _os.environ["ORG_LLM_LAG_DETECTOR"] = "off"
    try:
        return _benchmark_local_models_impl(
            _chat=_chat, _list_models=_list_models, _t=_t,
            _quality=_quality, CATALOG=CATALOG,
            url=url, vram_gb=vram_gb, ram_gb=ram_gb,
            role_filter=role_filter,
        )
    finally:
        if _prev_lag is None:
            _os.environ.pop("ORG_LLM_LAG_DETECTOR", None)
        else:
            _os.environ["ORG_LLM_LAG_DETECTOR"] = _prev_lag


def _benchmark_local_models_impl(
    *, _chat, _list_models, _t, _quality, CATALOG,
    url: str, vram_gb: float | None, ram_gb: float,
    role_filter: str = "",
) -> list[dict]:
    """Body of _benchmark_local_models, separated so the wrapper can
    own the lag-detector suppression with a clean try/finally."""

    pulled_raw = sorted(set(_list_models(url)))
    embed_stems = {"nomic-embed-text", "mxbai-embed-large",
                    "bge-m3", "snowflake-arctic-embed2"}

    def _meta(tag: str):
        stem = _normalize_tag(tag).split(":")[0]
        for m in CATALOG:
            if m.tag.split(":")[0] == stem:
                return m
        return None

    candidates: list[dict] = []
    budget_g = vram_gb if vram_gb is not None else ram_gb * 0.55
    for raw_tag in pulled_raw:
        stem = _normalize_tag(raw_tag).split(":")[0]
        if stem in embed_stems:
            continue
        m = _meta(raw_tag)
        roles  = m.roles if m else ("chat",)
        params = m.params if m else "?"
        vram   = m.vram_gb if m else 0.0
        if vram > 0 and vram > budget_g:
            continue
        if role_filter and role_filter not in roles:
            continue
        candidates.append({"tag": raw_tag, "stem": stem,
                            "params": params, "vram": vram,
                            "roles": roles})

    prompt = ("Write a 2-line haiku about an org-roam knowledge "
               "vault. Nothing else.")
    results: list[dict] = []
    n = len(candidates)
    if n == 0:
        return results

    # Live progress region. Rendered by Rich's auto-refresh thread so
    # the spinner ticks even while the main thread is blocked inside
    # a 30s _chat() call. Three details that matter for the spinner
    # to actually animate:
    #   1. refresh_per_second=12 (default 10 — bumped slightly so the
    #      spinner feels responsive on slow CPUs)
    #   2. auto_refresh=True (default; making it explicit)
    #   3. per-model `console.print()` calls go through `prog.console`
    #      so the live region pauses + repaints cleanly. Calling the
    #      module-level `console` while the Progress is active can
    #      stall the auto-refresh thread.
    from rich.progress import (Progress, SpinnerColumn, TextColumn,
                                 BarColumn, TimeElapsedColumn,
                                 MofNCompleteColumn)
    from .ui import _pick_thinking_spinner
    spin_name, spin_style = _pick_thinking_spinner()

    def _eta_str(completed_times: list[float], remaining: int) -> str:
        if not completed_times or remaining <= 0:
            return ""
        avg = sum(completed_times) / len(completed_times)
        eta_s = avg * remaining
        if eta_s < 60:
            return f" · ETA ~{eta_s:.0f}s"
        return f" · ETA ~{eta_s/60:.1f}min"

    completed_times: list[float] = []
    with Progress(
        SpinnerColumn(spinner_name=spin_name, style=spin_style,
                       finished_text="[green]✓[/green]"),
        TextColumn("[lcars2]{task.description}[/lcars2]"),
        BarColumn(bar_width=None),
        MofNCompleteColumn(),
        TextColumn("[dim]·[/dim]"),
        TimeElapsedColumn(),
        TextColumn("{task.fields[eta]}"),
        console=console,
        transient=False,
        auto_refresh=True,
        refresh_per_second=12,
    ) as prog:
        task = prog.add_task("benchmarking", total=n, eta="")
        for i, c in enumerate(candidates, 1):
            prog.update(task,
                         description=f"[{i}/{n}] {c['tag']}",
                         eta=_eta_str(completed_times, n - i + 1))
            try:
                t0 = _t.monotonic()
                resp = _chat(prompt, model=c["tag"], base_url=url, timeout=120)
                dt = _t.monotonic() - t0
                completed_times.append(dt)
                tok_est = max(1, len(resp) // 4)
                tok_per_s = tok_est / dt if dt > 0 else 0.0
                qual = _quality(c["tag"]) or _quality(c["stem"])
                score = qual * tok_per_s
                results.append({
                    **c, "time": dt, "tok_s": tok_per_s,
                    "qual": qual, "score": score, "ok": True,
                })
                # Route through the Progress's own console — pauses the
                # live region, prints, resumes. Safer than the global
                # `console` while a Live is active.
                prog.console.print(
                    f"  [green]✓[/green] {c['tag']:<28}  "
                    f"[lcars3]{tok_per_s:5.1f} tok/s[/lcars3]  "
                    f"[dim]({dt:.1f}s, q={qual})[/dim]"
                )
            except Exception as e:
                results.append({**c, "ok": False, "err": str(e)[:120]})
                prog.console.print(
                    f"  [red]×[/red] {c['tag']:<28}  "
                    f"[red]{str(e)[:120]}[/red]"
                )
            prog.update(task, advance=1,
                         eta=_eta_str(completed_times, n - i))
    return results


@app.command(rich_help_panel="Models & Cloud")
def models(
    discover: Annotated[bool, typer.Option("--discover", "-d",
              help="Show FOSS catalog filtered by hardware")] = False,
    tune:     Annotated[bool, typer.Option("--tune",     "-t",
              help="Analyze current config and recommend upgrades (read-only)")] = False,
    benchmark: Annotated[bool, typer.Option("--benchmark", "-B",
              help="Time real tok/s on each pulled model that fits, rank "
                   "by speed × quality. With --apply, set each role to "
                   "its top scorer.")] = False,
    upgrade:  Annotated[bool, typer.Option("--upgrade", "-u",
              help="One-shot: benchmark local + tune cloud, render unified "
                   "per-role recommendations. With --apply, write both "
                   "sides to config.")] = False,
    role:     Annotated[str,  typer.Option("--role",
              help="Scope --benchmark to one role (chat / fast / code / "
                   "reason / instruct / text). Default: all roles.")] = "",
    budget:   Annotated[float, typer.Option("--budget",
              help="With --upgrade: USD/Mtok cap for cloud picks (0 = "
                   "free-tier only, 1.0 = cheap paid). Default: no cap.")] = -1.0,
    apply:    Annotated[bool, typer.Option("--apply", "-A",
              help="With --tune / --benchmark / --upgrade: write the picks "
                   "to config (default: read-only)")] = False,
    pull:     Annotated[str,  typer.Option("--pull",     "-p",
              help="Pull a model via Ollama")] = "",
    assign:   Annotated[bool, typer.Option("--assign",   "-a",
              help="Interactively assign models to roles")] = False,
    set_:     Annotated[str,  typer.Option("--set",      "-s",
              help="One-shot assignment, format role=tag (e.g. chat=gemma3)")] = "",
    reclaim:  Annotated[bool, typer.Option("--reclaim",  "-R",
              help="Stop loaded Ollama models not assigned to a role. "
                   "Frees RAM that's stuck holding leftover models from "
                   "previous chats / doctor probes / model swaps.")] = False,
    reclaim_dry: Annotated[bool, typer.Option("--reclaim-dry-run",
              help="With --reclaim: show what would be stopped without "
                   "actually stopping anything.")] = False,
):
    """Show, discover, tune, and manage FOSS LLM assignments.

    Default view is the dashboard: every role with its current model,
    fit status, and any auto-detected upgrade/downgrade suggestion.
    No flags needed to see what's where.
    """
    from rich.panel import Panel
    from .models import (
        CATALOG, ROLE_KEYS, fitting_hardware, recommendations,
    )
    from .cloud import local_vram_gb, local_ram_gb

    engine = _engine()
    with get_session(engine) as session:
        url = _ollama_url(session)
        current = {role: _cfg(session, key) for role, key, _ in _TASK_MODEL_KEYS}

    pulled = _pulled_normalized(url)

    vram_gb = local_vram_gb()
    ram_gb  = local_ram_gb()

    # ── one-shot --set role=tag ───────────────────────────────────────────────
    if set_:
        if "=" not in set_:
            red_alert("--set expects role=tag (e.g. --set chat=gemma3)")
            raise typer.Exit(1)
        role, _, new_tag = set_.partition("=")
        role, new_tag = role.strip(), new_tag.strip()
        role_to_key = {r: k for r, k, _ in _TASK_MODEL_KEYS}
        if role not in role_to_key:
            red_alert(f"Unknown role {role!r}. "
                      f"Pick one of: {', '.join(role_to_key)}")
            raise typer.Exit(1)
        if not new_tag:
            red_alert("Empty model tag.")
            raise typer.Exit(1)
        from .db import Config as Cfg
        with get_session(engine) as session:
            row = session.get(Cfg, role_to_key[role])
            old = row.value if row else "(unset)"
            if row: row.value = new_tag
            else:   session.add(Cfg(key=role_to_key[role], value=new_tag))
            session.commit()
        hail(f"{role}_model: {old!r} → {new_tag!r}")
        if not _is_pulled(new_tag, pulled):
            on_screen(f"[yellow]Heads up:[/yellow] {new_tag} isn't pulled yet. "
                      f"Run [bold]org-llm models --pull {new_tag}[/bold] first.")
        return

    # ── reclaim loaded Ollama models ─────────────────────────────────────────
    if reclaim or reclaim_dry:
        from rich.panel import Panel as _Panel
        stopped, kept, freed_gb = _reclaim_ollama_models(apply=not reclaim_dry)
        verb = "Would stop" if reclaim_dry else "Stopped"
        body_lines: list[str] = []
        if stopped:
            body_lines.append(f"[lcars1]{verb}:[/lcars1]")
            for n in stopped:
                body_lines.append(f"  ◀ {n}")
            body_lines.append("")
            body_lines.append(f"[lcars3]Freed:[/lcars3] ~{freed_gb:.1f} GB")
        else:
            body_lines.append("Nothing to reclaim — all loaded models are "
                              "assigned to roles, or no models loaded.")
        if kept:
            body_lines.append("")
            body_lines.append(f"[lcars2]Kept ({len(kept)}):[/lcars2]")
            for n in kept:
                body_lines.append(f"  ▶ {n}")
        console.print()
        console.print(_Panel("\n".join(body_lines),
                              title=f"[lcars1]ollama-reclaim{' (dry-run)' if reclaim_dry else ''}[/lcars1]",
                              border_style="lcars2", padding=(1, 2)))
        return

    # ── pull a model ─────────────────────────────────────────────────────────
    if pull:
        import subprocess, shutil
        ollama_exe = shutil.which("ollama") or str(Path("~/.local/bin/ollama").expanduser())
        hail(f"Pulling {pull}…")
        result = subprocess.run([ollama_exe, "pull", pull])
        if result.returncode == 0:
            hail(f"Pulled: {pull}")
            make_it_so()
        else:
            red_alert(f"Pull failed for {pull}")
        return

    # ── discover FOSS catalog ─────────────────────────────────────────────────
    if discover:
        console.rule("[lcars1]FOSS LLM Catalog[/lcars1]")
        hw_info = (f"{vram_gb:.0f}GB VRAM" if vram_gb else f"{ram_gb:.0f}GB RAM (CPU)")
        hail(f"Hardware: {hw_info}  |  showing models that fit + all others")
        console.print()

        fits = {m.tag for m in fitting_hardware(vram_gb, ram_gb)}
        # Drop License + Description columns on narrow terminals so the
        # critical Model / Params / VRAM / Roles columns render cleanly.
        narrow = console.width < 110
        tbl = Table(box=None, pad_edge=False, show_header=True)
        tbl.add_column("Fits",   width=4,  no_wrap=True)
        tbl.add_column("Pulled", width=6,  no_wrap=True)
        tbl.add_column("Model",  style="lcars2", no_wrap=True, max_width=22, overflow="ellipsis")
        tbl.add_column("Params", width=6, style="dim",   no_wrap=True)
        tbl.add_column("VRAM",   width=6, style="lcars3",no_wrap=True)
        if not narrow:
            tbl.add_column("License", style="dim",   no_wrap=True, max_width=18, overflow="ellipsis")
        tbl.add_column("Roles",  style="lcars1", no_wrap=True, max_width=22, overflow="ellipsis")
        if not narrow:
            tbl.add_column("Description", style="dim", overflow="fold", min_width=20)

        prev_role_group = ""
        for m in CATALOG:
            role_group = m.roles[0]
            if role_group != prev_role_group:
                blanks = (8 if not narrow else 6)
                tbl.add_row(*([""] * blanks), style="dim")
                prev_role_group = role_group
            fit_sym  = "[bold green]✓[/]" if m.tag in fits else "[dim]→cloud[/]"
            pull_sym = "[bold cyan]✓[/]"  if _is_pulled(m.tag, pulled) else ""
            row = [fit_sym, pull_sym, m.tag, m.params, f"{m.vram_gb:.1f}G"]
            if not narrow:
                row.append(m.license)
            row.append(" ".join(m.roles))
            if not narrow:
                row.append(m.description)
            tbl.add_row(*row)
        console.print(tbl)
        if narrow:
            on_screen("[dim]Narrow terminal — License + Description columns hidden. "
                      "Widen >= 110 cols to see them.[/dim]")
        console.print()
        on_screen(f"Pull any model: [bold]org-llm models --pull <tag>[/bold]")
        on_screen(f"Tune assignments: [bold]org-llm models --tune[/bold]")
        return

    # ── tune recommendations ──────────────────────────────────────────────────
    if tune:
        console.rule("[lcars1]LLM Tuning Advisor[/lcars1]")
        hw_info = (f"{vram_gb:.0f}GB VRAM" if vram_gb else f"{ram_gb:.0f}GB RAM (CPU)")
        hail(f"Hardware: {hw_info}")

        recs = recommendations(current, pulled, vram_gb, ram_gb)

        if not recs:
            console.print("\n[bold green]✓  All model assignments are optimal for your hardware.[/bold green]\n")
            make_it_so()
            return

        console.print()
        tbl = Table(box=None, pad_edge=False)
        tbl.add_column("Role",      style="lcars1",  no_wrap=True)
        tbl.add_column("Current",   style="dim",     no_wrap=True)
        tbl.add_column("→",         width=2)
        tbl.add_column("Suggested", style="lcars2",  no_wrap=True)
        tbl.add_column("License",   style="dim",     no_wrap=True)
        tbl.add_column("VRAM",      style="lcars3",  width=6)
        tbl.add_column("Why",       style="dim")

        for rec in recs:
            arrow = "[bold yellow]↑[/]" if rec["upgrade"] else "[bold green]+[/]"
            tbl.add_row(
                rec["role"], rec["current"], arrow,
                rec["suggested"], rec["license"], f"{rec['vram']:.1f}G", rec["reason"],
            )
        console.print(tbl)
        console.print()

        if not apply:
            on_screen("Read-only — re-run with [bold]--apply[/bold] to write these changes.")
            return
        if typer.confirm("Apply all recommendations?", default=False):
            from .db import Config as Cfg
            role_to_key = {role: key for role, key, _ in _TASK_MODEL_KEYS}
            with get_session(engine) as session:
                for rec in recs:
                    key = role_to_key.get(rec["role"])
                    if not key:
                        continue
                    row = session.get(Cfg, key)
                    if row:
                        row.value = rec["suggested"]
                    else:
                        session.add(Cfg(key=key, value=rec["suggested"]))
                session.commit()
            hail("Config updated. Pull new models with: org-llm models --pull <tag>")
            make_it_so()
        return

    # ── benchmark (real tok/s on this hardware) ───────────────────────────────
    if benchmark:
        if role:
            valid_roles = {r for m in CATALOG for r in m.roles}
            if role not in valid_roles:
                red_alert(f"Unknown role {role!r}. Valid: "
                           f"{', '.join(sorted(valid_roles))}.")
                raise typer.Exit(1)

        console.rule("[lcars1]Model benchmark[/lcars1]")
        hw_info = (f"{vram_gb:.0f}GB VRAM" if vram_gb else f"{ram_gb:.0f}GB RAM (CPU)")
        scope_label = f" (role={role})" if role else ""
        hail(f"Hardware: {hw_info}{scope_label}")

        # Single benchmark implementation lives in the helper — both
        # `--benchmark` and `--upgrade` use it so the live-progress UX
        # (themed spinner / ETA / aligned per-model lines) is identical
        # in both paths. Earlier this block had a divergent inline
        # copy of the loop with no progress UI; that's why the new
        # spinner code didn't fire when running `--benchmark`.
        results = _benchmark_local_models(
            url=url, vram_gb=vram_gb, ram_gb=ram_gb, role_filter=role,
        )
        if not results:
            scope = f" with role={role!r}" if role else ""
            red_alert(f"No pulled models fit this hardware{scope}.")
            on_screen("[dim]Pull a candidate first:[/dim] "
                       "[bold]org-llm models --discover[/bold]")
            raise typer.Exit(1)

        # Render ranked table
        ok = [r for r in results if r["ok"]]
        ok.sort(key=lambda r: r["score"], reverse=True)
        if not ok:
            red_alert("No model completed the benchmark.")
            raise typer.Exit(1)

        console.print()
        tbl = Table(box=None, pad_edge=False, show_header=True)
        tbl.add_column("Rank",   width=5,  style="lcars1", no_wrap=True)
        tbl.add_column("Model",  style="lcars2", no_wrap=True)
        tbl.add_column("Params", width=6, style="dim",   no_wrap=True)
        tbl.add_column("tok/s",  style="lcars3", justify="right")
        tbl.add_column("Quality", style="dim", justify="right")
        tbl.add_column("Score",  style="lcars1", justify="right")
        tbl.add_column("Roles",  style="dim", overflow="fold")
        for i, r in enumerate(ok, 1):
            tbl.add_row(
                f"#{i}", r["tag"], r["params"],
                f"{r['tok_s']:.1f}", str(r["qual"]),
                f"{r['score']:.0f}", " ".join(r["roles"]),
            )
        console.print(tbl)
        console.print()

        # Per-role winners — pick the highest-score model that supports
        # each role.
        role_winners: dict[str, dict] = {}
        for r in ok:
            for rl in r["roles"]:
                if rl not in role_winners or r["score"] > role_winners[rl]["score"]:
                    role_winners[rl] = r

        # Compare to currently-configured model per role
        on_screen("[lcars1]Per-role recommendations:[/lcars1]")
        rec_tbl = Table(box=None, pad_edge=False, show_header=True)
        rec_tbl.add_column("Role",    style="lcars1", no_wrap=True)
        rec_tbl.add_column("Current", style="dim",    no_wrap=True)
        rec_tbl.add_column("→",       width=2)
        rec_tbl.add_column("Top scorer", style="lcars2", no_wrap=True)
        rec_tbl.add_column("Δ tok/s",    style="lcars3", justify="right")
        picks_to_apply: list[tuple[str, str]] = []  # (role_key, new_tag)
        for role_name, role_key, _ in _TASK_MODEL_KEYS:
            if role and role_name != role:
                continue
            cur = current.get(role_name) or "(unset)"
            winner = role_winners.get(role_name)
            if not winner:
                rec_tbl.add_row(role_name, cur, "·",
                                "[dim]no candidate fits[/dim]", "—")
                continue
            # Match by stem too — user's config row says "phi3.5" but
            # the benchmarked tag was "phi3.5:latest".
            cur_stem = _normalize_tag(cur).split(":")[0] if cur else ""
            cur_speed = next((r["tok_s"] for r in ok
                              if r["tag"] == cur or r["stem"] == cur_stem),
                              None)
            if cur_speed is None:
                delta = "[dim]n/a[/dim]"
            else:
                d = winner["tok_s"] - cur_speed
                delta = f"[green]+{d:.1f}[/green]" if d > 0 else (
                        f"[red]{d:.1f}[/red]" if d < 0 else "·")
            # Stem-match for the arrow: "qwen2.5-coder" + "qwen2.5-coder:latest"
            # are the same Ollama model, so don't flag them as an upgrade. The
            # apply step further down already uses the same stem-match
            # heuristic; this just keeps the visual in sync with the
            # behaviour the user gets when they run --apply.
            same_model = (winner["tag"] == cur or winner["stem"] == cur_stem)
            arrow = "·" if same_model else "[bold yellow]↑[/]"
            rec_tbl.add_row(role_name, cur, arrow, winner["tag"], delta)
            if not same_model:
                picks_to_apply.append((role_key, winner["tag"]))
        console.print(rec_tbl)
        console.print()

        if not apply:
            on_screen("Read-only — re-run with [bold]--apply[/bold] to "
                       "write these picks to config.")
            return
        if not picks_to_apply:
            on_screen("[dim]Nothing to apply — current config is already "
                       "the top scorer in every role.[/dim]")
            return
        if typer.confirm(f"Apply {len(picks_to_apply)} change(s)?",
                          default=False):
            from .db import Config as Cfg
            with get_session(engine) as session:
                for key, tag in picks_to_apply:
                    row = session.get(Cfg, key)
                    if row:
                        row.value = tag
                    else:
                        session.add(Cfg(key=key, value=tag))
                session.commit()
            hail(f"Applied {len(picks_to_apply)} change(s).")
            make_it_so()
        return

    # ── one-shot upgrade: benchmark local + tune cloud, render unified ────────
    if upgrade:
        from .cloud import (
            recommend_cloud_models, cloud_models_for_provider,
        )
        console.rule("[lcars1]Model upgrade  ·  local + cloud[/lcars1]")
        hw_info = (f"{vram_gb:.0f}GB VRAM" if vram_gb else f"{ram_gb:.0f}GB RAM (CPU)")
        on_screen(f"[lcars1]Local hardware:[/lcars1] {hw_info}")

        # ── local side: real tok/s benchmark ───────────────────────────────
        results = _benchmark_local_models(
            url=url, vram_gb=vram_gb, ram_gb=ram_gb,
            role_filter=role,
        )
        ok = [r for r in results if r["ok"]]
        if not ok:
            red_alert("No local model completed the benchmark.")
            on_screen("[dim]Continuing with cloud-only recommendations.[/dim]")
        ok.sort(key=lambda r: r["score"], reverse=True)
        local_winners: dict[str, dict] = {}
        for r in ok:
            for rl in r["roles"]:
                if rl not in local_winners or r["score"] > local_winners[rl]["score"]:
                    local_winners[rl] = r

        # ── cloud side: catalog-driven recommendations ────────────────────
        with get_session(engine) as session:
            cur_provider = _cfg(session, "cloud_provider")
            cur_cloud_model = _cfg(session, "cloud_model")
        cap = budget if budget >= 0 else None
        cloud_recs: list[dict] = []
        if cur_provider and cloud_models_for_provider(cur_provider):
            cloud_recs = recommend_cloud_models(
                provider_slug=cur_provider,
                current_model=cur_cloud_model,
                budget_per_mtok_out=cap,
                role_filter=role,
            )
            on_screen(f"[lcars1]Cloud:[/lcars1] {cur_provider}  ·  "
                       f"current model: {cur_cloud_model or '(unset)'}  ·  "
                       f"budget: "
                       f"{('≤ $' + format(cap, '.2f') + '/Mtok out') if cap is not None else 'no cap'}")
        else:
            on_screen("[dim]No cloud provider configured — local picks only.[/dim]")
            on_screen("[dim]Run[/dim] [bold]org-llm cloud --quick-start "
                       "openrouter[/bold] [dim]to enable cloud picks too.[/dim]")

        cloud_by_role = {rec["role"]: rec for rec in cloud_recs}

        # ── unified per-role table ────────────────────────────────────────
        narrow = console.width < 110
        tbl = Table(box=None, pad_edge=False)
        tbl.add_column("Role",        style="lcars1", no_wrap=True, width=8)
        tbl.add_column("Local pick",  style="lcars2", no_wrap=True,
                       max_width=24, overflow="ellipsis")
        tbl.add_column("tok/s",       style="lcars3", justify="right", width=6)
        tbl.add_column("Cloud pick",  style="lcars2", no_wrap=True,
                       max_width=28, overflow="ellipsis")
        tbl.add_column("$/Mtok",      style="lcars3", justify="right", width=8)
        if not narrow:
            tbl.add_column("Quality (L / C)", style="dim", justify="right")

        local_picks_to_apply: list[tuple[str, str]] = []
        for role_name, role_key, _ in _TASK_MODEL_KEYS:
            if role and role_name != role:
                continue
            cur = current.get(role_name) or "(unset)"
            lwin = local_winners.get(role_name)
            cwin = cloud_by_role.get(role_name)

            local_label = (lwin["tag"] if lwin else "[dim]—[/dim]")
            local_speed = (f"{lwin['tok_s']:.1f}" if lwin else "—")
            cloud_label = (cwin["suggested"] if cwin else "[dim]—[/dim]")
            cloud_cost = (
                "[green]free[/green]" if (cwin and cwin["cost_out"] == 0)
                else (f"${cwin['cost_out']:.2f}" if cwin else "—"))
            qual_label = ""
            if lwin and cwin:
                qual_label = f"{lwin['qual']} / {cwin['quality']}"
            elif lwin:
                qual_label = f"{lwin['qual']} / —"
            elif cwin:
                qual_label = f"— / {cwin['quality']}"
            row = [role_name, local_label, local_speed,
                    cloud_label, cloud_cost]
            if not narrow:
                row.append(qual_label)
            tbl.add_row(*row)

            # Track local change for --apply
            if lwin and lwin["tag"] != cur:
                cur_stem = _normalize_tag(cur).split(":")[0] if cur != "(unset)" else ""
                if cur_stem != lwin["stem"]:
                    local_picks_to_apply.append((role_key, lwin["tag"]))

        console.print()
        console.print(tbl)
        console.print()

        # Cloud chat-model winner — the canonical cloud_model pick
        cloud_chat_pick = next((r for r in cloud_recs if r["role"] == "chat"), None)
        cloud_apply_pending = (cloud_chat_pick
                                and cloud_chat_pick["upgrade"])

        # Summary block
        if local_picks_to_apply:
            on_screen(f"[lcars1]Local changes ready:[/lcars1] "
                       f"{len(local_picks_to_apply)} role(s)")
            for k, v in local_picks_to_apply:
                on_screen(f"  [dim]·[/dim] {k} = {v}")
        else:
            on_screen("[dim]Local config is already top-scorer for every role.[/dim]")
        if cloud_apply_pending:
            on_screen(f"[lcars1]Cloud change ready:[/lcars1]  cloud_model = "
                       f"{cloud_chat_pick['suggested']}")
        elif cur_provider:
            on_screen("[dim]Cloud config is already the top scorer for chat.[/dim]")

        if not apply:
            on_screen("\nRead-only — re-run with [bold]--apply[/bold] to "
                       "write all picks (local + cloud) to config.")
            return

        if not local_picks_to_apply and not cloud_apply_pending:
            on_screen("[dim]Nothing to apply.[/dim]")
            return

        if typer.confirm(
                f"Apply {len(local_picks_to_apply)} local + "
                f"{1 if cloud_apply_pending else 0} cloud change(s)?",
                default=False):
            from .db import Config as Cfg
            with get_session(engine) as session:
                for key, tag in local_picks_to_apply:
                    row_ = session.get(Cfg, key)
                    if row_:
                        row_.value = tag
                    else:
                        session.add(Cfg(key=key, value=tag))
                if cloud_apply_pending:
                    row_ = session.get(Cfg, "cloud_model")
                    if row_:
                        row_.value = cloud_chat_pick["suggested"]
                    else:
                        session.add(Cfg(key="cloud_model",
                                         value=cloud_chat_pick["suggested"]))
                session.commit()
            hail("Config updated. Pull any new local models with: "
                  "org-llm models --pull <tag>")
            make_it_so()
        return

    # ── interactive assign ────────────────────────────────────────────────────
    if assign:
        console.rule("[lcars1]Model Assignment Wizard[/lcars1]")
        fits = [m.tag for m in fitting_hardware(vram_gb, ram_gb)]
        from .db import Config as Cfg
        with get_session(engine) as session:
            for role, key, purpose in _TASK_MODEL_KEYS:
                cur = _cfg(session, key) or "—"
                options = [m for m in fits
                           if role in next((c.roles for c in CATALOG if c.tag == m), ())]
                if not options:
                    options = fits[:10]
                console.print(f"\n[lcars1]{role}[/lcars1] ({purpose})  current: [lcars2]{cur}[/lcars2]")
                for i, opt in enumerate(options[:8], 1):
                    pulled_mark = " [cyan]✓ pulled[/cyan]" if _is_pulled(opt, pulled) else ""
                    console.print(f"  {i}. {opt}{pulled_mark}")
                choice = typer.prompt(
                    f"Enter number or model tag (blank = keep {cur})", default=""
                )
                if not choice:
                    continue
                new_val = (
                    options[int(choice) - 1]
                    if choice.isdigit() and 1 <= int(choice) <= len(options)
                    else choice
                )
                row = session.get(Cfg, key)
                if row:
                    row.value = new_val
                else:
                    session.add(Cfg(key=key, value=new_val))
            session.commit()
        hail("Model assignments saved.")
        make_it_so()
        return

    # ── default: dashboard view ───────────────────────────────────────────────
    # Single screen: every role with model + purpose + pulled/fits status,
    # then an auto-detected SUGGESTIONS section so the user sees upgrade
    # opportunities without having to know about --tune.
    console.rule("[lcars1]Model Assignments[/lcars1]  "
                  f"[dim](hardware: "
                  f"{f'{vram_gb:.0f}GB VRAM' if vram_gb else f'{ram_gb:.0f}GB RAM (CPU)'}"
                  f")[/dim]")
    # Build a tag → fits-locally lookup. Stem-fuzzy lookup so a
    # configured model like `llama3.2` resolves to catalog entry
    # `llama3.2:3b` (different version tag, same model family). Fixes
    # "VRAM ?" + the wrongly-✓ Fits cell that appeared whenever the
    # bare stem didn't exactly match a tagged catalog entry.
    from .models import _norm
    catalog_by_tag = {m.tag: m for m in CATALOG}
    catalog_by_stem: dict[str, list] = {}
    for m in CATALOG:
        catalog_by_stem.setdefault(_norm(m.tag).split(":")[0], []).append(m)

    def _lookup_catalog(tag: str):
        if not tag or tag == "—":
            return None
        if tag in catalog_by_tag:
            return catalog_by_tag[tag]
        stem = _norm(tag).split(":")[0]
        # Pick the smallest-VRAM variant of that stem as a sensible
        # default — captures the bare-stem-implies-:latest convention
        # without claiming the largest variant fits.
        candidates = catalog_by_stem.get(stem, [])
        return min(candidates, key=lambda m: m.vram_gb) if candidates else None

    fitting_tags = {m.tag for m in fitting_hardware(vram_gb, ram_gb)}

    # Track which pulled models are referenced by an assigned role so
    # the Pulled table can label them ("Used by: chat" / unused).
    used_by_role: dict[str, list[str]] = {}
    for role, _key, _purpose in _TASK_MODEL_KEYS:
        m = current.get(role) or "—"
        if m and m != "—":
            used_by_role.setdefault(_norm(m).split(":")[0], []).append(role)

    assign_tbl = Table(box=None, pad_edge=False)
    assign_tbl.add_column("Role",    style="lcars1",  no_wrap=True)
    assign_tbl.add_column("Model",   style="lcars2",  no_wrap=True)
    assign_tbl.add_column("Purpose", style="dim")
    assign_tbl.add_column("VRAM",    style="lcars3", width=6, no_wrap=True)
    assign_tbl.add_column("Pulled",  width=8, no_wrap=True)
    assign_tbl.add_column("Fits",    width=6, no_wrap=True)
    for role, key, purpose in _TASK_MODEL_KEYS:
        m = current.get(role) or "—"
        cat = _lookup_catalog(m)
        vram = f"{cat.vram_gb:.1f}G" if cat else "[dim]?[/dim]"
        pulled_cell = (
            "[green]✓[/green]" if _is_pulled(m, pulled)
            else ("[dim]—[/dim]" if m == "—" else "[yellow]✗[/yellow]")
        )
        if m == "—":
            fits_cell = "[dim]—[/dim]"
        elif cat is None:
            # Honest about not knowing: don't claim ✓ when we have no
            # size data for this tag.
            fits_cell = "[dim]?[/dim]"
        elif m in fitting_tags or _norm(m).split(":")[0] in {
            _norm(t).split(":")[0] for t in fitting_tags}:
            fits_cell = "[green]✓[/green]"
        else:
            fits_cell = "[red]✗[/red]"
        assign_tbl.add_row(role, m, purpose, vram, pulled_cell, fits_cell)
    console.print(assign_tbl)

    console.print()
    if pulled:
        pull_tbl = Table(title="Pulled in Ollama", box=None, pad_edge=False,
                          show_header=True, title_justify="left")
        pull_tbl.add_column("Model",    style="lcars3", no_wrap=True)
        pull_tbl.add_column("VRAM",     style="dim",    width=8, no_wrap=True)
        pull_tbl.add_column("Used by",  style="lcars1", no_wrap=True)
        for name in sorted(pulled):
            cat   = _lookup_catalog(name)
            vram  = f"{cat.vram_gb:.1f}G" if cat else "?"
            stem  = _norm(name).split(":")[0]
            roles = used_by_role.get(stem, [])
            roles_str = ", ".join(roles) if roles else "[dim](unused)[/dim]"
            pull_tbl.add_row(name, vram, roles_str)
        console.print(pull_tbl)
    else:
        console.print("[dim]Ollama not reachable or no models pulled.[/dim]")

    # Auto-suggestion section — runs the same recommendations() as --tune
    # but renders inline so the user sees opportunities without a flag.
    console.print()
    try:
        recs = recommendations(current, pulled, vram_gb, ram_gb)
    except Exception:
        recs = []
    if recs:
        sug_tbl = Table(box=None, pad_edge=False)
        sug_tbl.add_column("Role",      style="lcars1",  no_wrap=True)
        sug_tbl.add_column("Current",   style="dim",     no_wrap=True)
        sug_tbl.add_column("→",         width=2)
        sug_tbl.add_column("Suggested", style="lcars2",  no_wrap=True)
        sug_tbl.add_column("VRAM",      style="lcars3",  width=6)
        sug_tbl.add_column("Why",       style="dim")
        for rec in recs:
            arrow = "[bold yellow]↑[/]" if rec.get("upgrade") else "[bold green]+[/]"
            sug_tbl.add_row(rec["role"], rec["current"], arrow,
                              rec["suggested"], f"{rec['vram']:.1f}G",
                              rec["reason"])
        from rich.panel import Panel
        console.print(Panel(sug_tbl,
                              title="[lcars1]Suggestions[/lcars1]",
                              border_style="lcars2", padding=(1, 1)))
        console.print()
        on_screen("Apply one:   "
                  "[bold]org-llm models --set <role>=<tag>[/bold]")
        on_screen("Apply all:   "
                  "[bold]org-llm models --tune --apply[/bold]")
        on_screen("Pull a tag:  "
                  "[bold]org-llm models --pull <tag>[/bold]")
    else:
        on_screen("[lcars3]✓ All current assignments look optimal for your hardware.[/lcars3]")
        on_screen("[dim]Tweak anyway: [bold]org-llm models --set <role>=<tag>[/bold] "
                  "or [bold]org-llm models --discover[/bold] for the catalog.[/dim]")

    console.print()
    # LLM-driven recommendation: feed the model state to fast_model and ask
    # for one concrete next step. Falls back to deterministic template if
    # the LLM is unavailable.
    unassigned = [role for role, _, _ in _TASK_MODEL_KEYS
                  if not (current.get(role) or "").strip() or current.get(role) == "—"]
    not_pulled = [(role, current[role]) for role, _, _ in _TASK_MODEL_KEYS
                  if current.get(role) and current[role] != "—"
                  and not _is_pulled(current[role], pulled)]
    state_lines = []
    for role, _, purpose in _TASK_MODEL_KEYS:
        m = current.get(role) or "—"
        status = ("✓ pulled" if _is_pulled(m, pulled) else
                  "—" if m == "—" else "not pulled")
        state_lines.append(f"  {role}={m}  [{status}]  ({purpose})")
    state = "\n".join(state_lines)
    sys_msg = (
        "You recommend ONE concrete next command for an org-llm user "
        "given their FOSS model assignment state. Output the command "
        "wrapped in [bold]…[/bold] markup with one short reason "
        "before it. Format: 'Next: <reason> — [bold]org-llm <cmd>[/bold]'. "
        "≤ 22 words. Pick from: models --tune --apply, models --pull "
        "<tag>, performance --apply, performance --benchmark, install. "
        "Choose the most pressing single gap."
    )
    user_msg = (
        f"Model role assignments:\n{state}\n\n"
        f"Pulled in Ollama: {sorted(pulled) if pulled else '(none)'}\n\n"
        "What's the single most useful next command?"
    )
    # Deterministic short-circuit: when there's a concrete gap in the
    # model state, the deterministic fallback IS the right answer and
    # the LLM just adds noise (real failure: a small model, asked to
    # recommend on a fully-assigned/-pulled state, emitted
    # "Next: due to performance issues with fast=llama3.2:1b — install [✓]"
    # — half-formed, raw markup leaking, no actual command). Pattern
    # we keep landing on across this session: small models confabulate
    # on sparse / well-known input; deterministic wins.
    if unassigned:
        role = unassigned[0]
        on_screen(f"[dim]Next:[/dim] {role} is unassigned — "
                  f"[bold]org-llm models --tune --apply[/bold] picks one for your hardware")
        return
    if not_pulled:
        role, model = not_pulled[0]
        on_screen(f"[dim]Next:[/dim] {role}={model} is configured but not pulled — "
                  f"[bold]org-llm models --pull {model}[/bold]")
        return
    if not pulled:
        on_screen("[dim]Next:[/dim] no Ollama models pulled — "
                  "[bold]org-llm install-tools --skip-fonts --skip-opencode --skip-gh --skip-claude[/bold]")
        return

    # Only call the LLM when state is fully OK and there's room for a
    # subtle "you might want to consider X" suggestion. Validate the
    # output shape — if it doesn't match the prompted
    # "Next: <reason> — [bold]org-llm <cmd>[/bold]" template, fall
    # through to the deterministic catch-all.
    llm_rec = _llm_one_liner(user_msg, system=sys_msg, fallback="")
    import re as _re
    _VALID_REC = _re.compile(
        r"Next:.*org-llm\s+(models|performance|install-tools|"
        r"models\s+--\w+|performance\s+--\w+)",
        _re.IGNORECASE,
    )
    if llm_rec and _VALID_REC.search(llm_rec):
        on_screen(llm_rec)
        return
    on_screen("[dim]All roles assigned and pulled.[/dim] "
              "[bold]org-llm performance --benchmark[/bold] "
              "measures real tok/s if you want tuning data.")


_CONFIG_VALIDATORS = {
    "ollama_url":         "url",
    "cloud_endpoint_url": "url",
    "embed_dim":          "int",
    "theme":              ("dark", "light"),
    "db_version":         "int",
    # Theme intensity dials — accept 0..3 only
    "trek_level":         ("0", "1", "2", "3"),
    "commie_level":       ("0", "1", "2", "3"),
    "queer_level":        ("0", "1", "2", "3"),
}


def _validate_config(key: str, value: str) -> str | None:
    """Return None if value is acceptable for key, else a human-readable error."""
    rule = _CONFIG_VALIDATORS.get(key)
    if rule is None:
        return None  # unknown keys are accepted (custom user keys are fine)
    if rule == "url":
        if not (value.startswith("http://") or value.startswith("https://")):
            return f"{key!r} must be an http(s) URL (got {value!r})"
    elif rule == "int":
        if not value.lstrip("-").isdigit():
            return f"{key!r} must be an integer (got {value!r})"
    elif isinstance(rule, tuple):
        if value not in rule:
            return f"{key!r} must be one of {rule} (got {value!r})"
    return None


@app.command(rich_help_panel="Models & Cloud")
def performance(
    apply:     Annotated[bool, typer.Option("--apply", "-a",
               help="Write recommended role assignments to config (default: read-only report)")] = False,
    benchmark: Annotated[bool, typer.Option("--benchmark", "-b",
               help="Run per-model timing tests (slow — ~1-3 min depending on pulled models)")] = False,
    quick:     Annotated[bool, typer.Option("--quick", "-q",
               help="Hardware probe only; skip Ollama probe and model recommendations")] = False,
):
    """Tune org-llm to your real hardware.

    Probes free RAM/VRAM (not total — you have other apps open), pings Ollama,
    optionally benchmarks each pulled chat/embed model for tokens-per-second,
    then recommends role assignments that:
      • fit your *available* memory
      • prefer already-pulled models (no download required)
      • flag oversize current assignments as DOWNGRADE NEEDED
      • route to the configured cloud backend when nothing fits locally

    With --apply, recommendations are written to the config DB.
    """
    from rich.panel import Panel
    from rich.table import Table as _T
    from . import performance as perf

    console.rule(f"[lcars1]Performance probe  ·  stardate {__import__('org_llm.ui', fromlist=['stardate']).stardate()}[/lcars1]")
    console.print()

    # ── Hardware ──────────────────────────────────────────────────────────────
    with warp("Probing hardware"):
        hw = perf.probe_hardware()

    hw_tbl = _T(box=None, pad_edge=False, show_header=False)
    hw_tbl.add_column("Key",   style="lcars1", width=18, no_wrap=True)
    hw_tbl.add_column("Value", style="lcars2", overflow="fold")
    # Trim the obvious noise from CPU model strings so the panel stays tight
    cpu_clean = (hw.cpu_model.replace("(R)", "").replace("(TM)", "")
                            .replace("11th Gen ", "11th-Gen ").strip())
    hw_tbl.add_row("CPU",        f"{cpu_clean}  ({hw.cpu_count} cores)")
    hw_tbl.add_row("RAM total",  f"{hw.ram_total_gb:.1f} GB")
    hw_tbl.add_row("RAM free",   f"[bold]{hw.ram_free_gb:.1f} GB[/bold]"
                                  + ("  [yellow](used as budget)[/yellow]"
                                     if hw.vram_total_gb is None else ""))
    if hw.vram_total_gb is not None:
        hw_tbl.add_row("VRAM total", f"{hw.vram_total_gb:.1f} GB")
        hw_tbl.add_row("VRAM free",  f"[bold]{hw.vram_free_gb:.1f} GB[/bold]  [yellow](used as budget)[/yellow]")
    else:
        hw_tbl.add_row("GPU",        "[dim]none detected (CPU inference only)[/dim]")
    hw_tbl.add_row("Disk free",  f"{hw.disk_free_gb:.0f} GB (in $HOME)")
    console.print(lcars_panel("Hardware", hw_tbl,
                                 border_style="lcars2", title_style="lcars1"))

    if quick:
        return

    # ── Ollama state + cloud check ────────────────────────────────────────────
    engine = _engine()
    try:
        with get_session(engine) as session:
            url      = _ollama_url(session)
            current  = {role: _cfg(session, key) for role, key, _ in _TASK_MODEL_KEYS}
            cloud_endpoint = _cfg(session, "cloud_endpoint_url")
    except Exception as exc:
        if "no such table" in str(exc):
            red_alert("Database not initialised. Run: [bold]org-llm init[/bold] first.")
        else:
            red_alert(f"Config read failed: {exc}")
        raise typer.Exit(1)

    pulled_norm = _pulled_normalized(url)
    if not pulled_norm:
        red_alert(f"Ollama not reachable at {url}. Start it (or run: org-llm doctor --fix).")
        on_screen("Cloud-only recommendations still possible if you have --cloud configured.")
        if not cloud_endpoint:
            raise typer.Exit(1)

    console.print()
    pulled_tbl = _T(box=None, pad_edge=False)
    pulled_tbl.add_column("Pulled tag", style="lcars3")
    if pulled_norm:
        for p in sorted(pulled_norm):
            pulled_tbl.add_row(p)
        console.print(lcars_panel(f"Local models  ({len(pulled_norm)} pulled)",
                                     pulled_tbl, border_style="lcars3",
                                     title_style="lcars1"))

    # ── Optional benchmarks ───────────────────────────────────────────────────
    benchmarks: dict[str, perf.BenchmarkResult] = {}
    if benchmark and pulled_norm:
        on_screen("Benchmarking each pulled chat-capable model (1 short prompt each)…")
        for tag in sorted(pulled_norm):
            full_tag = tag + (":latest" if ":" not in tag else "")
            if _is_embed_model(full_tag):
                bench = perf.benchmark_embed_model(full_tag, url)
            else:
                bench = perf.benchmark_chat_model(full_tag, url)
            benchmarks[tag] = bench

        bench_tbl = _T(box=None, pad_edge=False)
        bench_tbl.add_column("Model",        style="lcars2")
        bench_tbl.add_column("Role",         style="dim", width=7)
        bench_tbl.add_column("Latency",      style="lcars3", justify="right", width=10)
        bench_tbl.add_column("Tokens/s",     style="lcars1", justify="right", width=10)
        bench_tbl.add_column("Notes",        style="dim")
        for tag, b in benchmarks.items():
            if b.error:
                bench_tbl.add_row(tag, b.role, "—", "—", f"[red]{b.error}[/red]")
            else:
                bench_tbl.add_row(tag, b.role,
                                   f"{b.latency_ms:.0f} ms",
                                   f"{b.tokens_per_sec:.1f}", "")
        console.print()
        console.print(lcars_panel("Measured throughput", bench_tbl,
                                     border_style="lcars2", title_style="lcars1"))

    # ── Recommendations ───────────────────────────────────────────────────────
    recs = perf.recommend(
        hw, current, benchmarks, pulled_norm,
        cloud_configured=bool(cloud_endpoint),
    )
    rec_tbl = _T(box=None, pad_edge=False)
    rec_tbl.add_column("Role",      style="lcars1", width=10,   no_wrap=True)
    rec_tbl.add_column("Current",   style="dim",                no_wrap=True, max_width=20, overflow="ellipsis")
    rec_tbl.add_column("→",         width=2)
    rec_tbl.add_column("Suggested", style="lcars2",             no_wrap=True, max_width=24, overflow="ellipsis")
    rec_tbl.add_column("Why",       style="dim",                overflow="fold", min_width=24)
    rec_tbl.add_column("tok/s",     style="lcars3", justify="right", width=7)

    severity_arrow = {
        "downgrade": "[bold red]↓[/]",
        "upgrade":   "[bold yellow]↑[/]",
        "missing":   "[bold cyan]+[/]",
        "fit":       "[bold green]=[/]",
    }

    has_changes = False
    for r in recs:
        arrow = severity_arrow.get(r.severity, "·")
        tps   = f"{r.measured_tps:.1f}" if r.measured_tps is not None else "—"
        rec_tbl.add_row(r.role, r.current, arrow, r.suggested, r.reason, tps)
        if r.severity in ("upgrade", "downgrade", "missing"):
            has_changes = True

    console.print()
    console.print(lcars_panel("Recommendations", rec_tbl,
                                 border_style="lcars2", title_style="lcars1"))
    console.print()

    if not has_changes:
        on_screen("[bold green]✓  Your role assignments already fit this hardware.[/bold green]")
        make_it_so()
        return

    if not apply:
        on_screen("Read-only report. Re-run with [bold]--apply[/bold] to write these changes.")
        on_screen("Or override individual roles: [bold]org-llm config <role>_model <tag>[/bold]")
        return

    # ── Apply ────────────────────────────────────────────────────────────────
    from .db import Config as Cfg
    role_to_key = {role: key for role, key, _ in _TASK_MODEL_KEYS}
    with get_session(engine) as session:
        for r in recs:
            if r.severity not in ("upgrade", "downgrade", "missing"):
                continue
            key = role_to_key.get(r.role)
            if not key:
                continue
            row = session.get(Cfg, key)
            if row:
                row.value = r.suggested
            else:
                session.add(Cfg(key=key, value=r.suggested))
        session.commit()
    hail("Config updated.")
    on_screen("Pull any newly-suggested models with: [bold]org-llm doctor --fix[/bold]")
    make_it_so()


# ── Screenshot tooling ──────────────────────────────────────────────
#
# `org-llm screenshot` captures the current screen / window / Emacs
# frame via a configurable backend so the user can grab opencode TUI
# screenshots for docs/img/ without leaving Doom (or wherever they
# work). Read-only on the proxy/plugin side; this is a pure CLI
# helper that shells out to the chosen tool.
#
# Config knobs (db.MODEL_DEFAULTS):
#   screenshot_tool   — emacs | grim | maim | scrot | flameshot | custom
#   screenshot_cmd    — command template when tool=custom; {path} is
#                       substituted with the output file path
#   screenshot_dir    — destination directory; defaults to docs/img/
#                       under the org-llm repo root, falling back to
#                       ~/org/.opencode/ if not in a checkout
#
# Defaults to `emacs` because the dev environment is Doom + vterm —
# emacsclient -e is the only path that can see what's inside an
# Emacs vterm buffer (other tools capture the host terminal which
# may be a Doom frame or a separate terminal entirely).

_SCREENSHOT_BACKENDS = {
    # Built-in Emacs: x-export-frames, captures the current frame
    # (or specific window if the doom helper is selected).
    "emacs":     'emacsclient -e "(org-llm-opencode-screenshot)"',
    # Wayland region grab; user clicks-and-drags.
    "grim":      'grim -g "$(slurp)" {path}',
    # X11 region grab.
    "maim":      'maim -s {path}',
    # X11 full-screen.
    "scrot":     'scrot {path}',
    # Cross-platform GUI tool with annotation.
    "flameshot": 'flameshot gui --raw > {path}',
}


def _resolve_screenshot_dir(session) -> Path:
    """Pick the screenshot destination directory. Prefers the user-
    configured `screenshot_dir`, falls back to `<repo>/docs/img/`
    when running from a checkout, then to `~/org/.opencode/`."""
    explicit = (_cfg(session, "screenshot_dir") or "").strip()
    if explicit:
        return Path(explicit).expanduser()
    repo_root = Path(__file__).resolve().parent.parent
    docs_img = repo_root / "docs" / "img"
    if docs_img.is_dir():
        return docs_img
    return Path("~/org/.opencode").expanduser()


@app.command(rich_help_panel="Querying")
def route(
    prompt: Annotated[str, typer.Argument(help="The user prompt to route")],
    quiet:  Annotated[bool, typer.Option("--quiet", "-q",
            help="Print only the agent name (machine-readable)")] = False,
    json_:  Annotated[bool, typer.Option("--json",
            help="Print {agent, score, triggers} as JSON")] = False,
):
    """Route a prompt to the best preconfigured agent (no LLM).

    Lightning-fast keyword scoring against each agent's trigger
    phrase list. Microsecond latency, zero ollama wake-up.
    Useful as a building block:
      • Eyeball: `org-llm route "find phase 18 notes"` → researcher
      • Pipe: `pick=$(org-llm route "..." -q) && @$pick ...`
      • From the MCP `route_agent` tool — the LLM can self-route
        between turns when the user's intent shifts.

    Returns ('chat', 0) when no trigger matches — caller should
    fall back to the session default.
    """
    agent, score, hits = route_prompt(prompt)
    if json_:
        import json as _j
        print(_j.dumps({"agent": agent, "score": score, "triggers": hits}))
        return
    if quiet:
        print(agent)
        return
    on_screen(f"[lcars1]{agent}[/lcars1]  "
              f"[dim]score={score}[/dim]")
    if hits:
        on_screen(f"[dim]matched:[/dim] {', '.join(hits)}")
    else:
        on_screen("[dim](no triggers matched — falling back to "
                  "session default)[/dim]")


@app.command(rich_help_panel="Querying")
def telemetry(
    pretty: Annotated[bool, typer.Option("--pretty", "-P",
            help="Pretty-print the JSON (indent=2). Default off — "
                 "tools that consume this expect minified.")] = False,
    proxy_state: Annotated[bool, typer.Option("--proxy-state/--no-proxy-state",
            help="Include proxy state (active model + route) by querying "
                 "the running proxy via its port file. Adds a small "
                 "lookup; default on.")] = True,
):
    """Emit fresh live telemetry as JSON — vault counts, vitals
    (battery / memory / thermal), MCP info, recent activity, sensor
    alerts, and the actual proxy routing decision.

    Single source of truth for chat-surface grounding and any future
    consumer that needs current state. Always probes live; never reads
    stale snapshots like .opencode/sidebar-status.json (which is
    launch-time-only by design).

    Read-only: this verb does not consume pending-prompt.txt or
    rewrite any sidebar files — safe to call from a hot loop.

    Output goes to stdout. On any internal error, emits an empty
    object `{}` and exits 0 — callers degrade gracefully rather than
    seeing a Python traceback in the middle of their chat buffer.
    """
    import json as _json
    import os as _os
    from pathlib import Path as _Path
    payload: dict = {}
    try:
        from .db import Node as _N, File as _F
        engine = _engine()
        with get_session(engine) as session:
            # Pre-compute vault stats — _opencode_sidebar_status reads
            # these from ctx (the launcher pre-populates; we mirror).
            n_files = session.query(_F).count() or 0
            n_nodes = session.query(_N).count() or 0
            try:
                n_embed = session.query(_N).filter(
                    _N.embedding.isnot(None)).count() or 0
            except Exception:
                n_embed = 0
            pct = round((100.0 * n_embed / n_nodes), 1) if n_nodes else 0
            org_dir = _os.environ.get("ORG_LLM_ORG_DIR") or str(
                _Path.home() / "org")
            ctx = {
                "n_files":    n_files,
                "n_nodes":    n_nodes,
                "n_embedded": n_embed,
                "pct_e":      pct,
                "org_dir":    org_dir,
            }
            payload = _opencode_sidebar_status(
                session, ctx=ctx, workspace="all",
                read_only=True,
            )
        # Augment with the actual proxy routing decision (the sidebar
        # `model` block reflects launch-time config, but the proxy may
        # be cloud-routing at runtime). Best-effort — never fail the
        # whole verb if the proxy is down.
        if proxy_state:
            try:
                from . import llm_proxy as _proxy
                cf  = _proxy._cloud_first_enabled()
                tgt = _proxy._resolve_cloud_failover_target() if cf else None
                if tgt:
                    payload["model"] = {
                        "active":   tgt["model"],
                        "provider": "openrouter",
                        "route":    "cloud",
                        "endpoint": tgt["endpoint"],
                    }
                payload["proxy"] = {
                    "cloud_first_enabled": cf,
                    "cloud_target_resolved": bool(tgt),
                }
            except Exception:
                pass
    except Exception:
        payload = {}
    indent = 2 if pretty else None
    typer.echo(_json.dumps(payload, indent=indent))


@app.command(rich_help_panel="Maintenance")
def agents(
    tangle: Annotated[bool, typer.Option("--tangle", "-T",
            help="Write ~/org/org-llm-agents.org from the current "
                 "agent set (defaults + any existing user overrides "
                 "merged). Edit there to customise — the next launch "
                 "picks up your changes.")] = False,
    apply_from_org: Annotated[bool, typer.Option("--apply", "--apply-from-org", "-A",
            help="Read ~/org/org-llm-agents.org and upsert every "
                 ":agent:-tagged heading into the `agent` DB table. "
                 "Use this after editing the file (or after "
                 "@agentsmith ships an agent) to land changes "
                 "immediately. Otherwise the next `org-llm launch` "
                 "auto-applies if the file's mtime is newer than "
                 "the DB.")] = False,
    list_:  Annotated[bool, typer.Option("--list", "-l",
            help="Show the resolved agent set (defaults + any "
                 "active user overrides) — same as what the next "
                 "launch will write to opencode.json")] = False,
    seed:   Annotated[bool, typer.Option("--seed",
            help="Populate the `agent` DB table from the current "
                 "Python built-ins. Idempotent — only inserts rows "
                 "whose birth_name isn't already in the table. Use "
                 "this once to make the bundled agents editable via "
                 "`org-llm agent set …`.")] = False,
):
    """Show / round-trip the preconfigured agents.

    Source-of-truth precedence (each layer wins where it sets a field):
      1. Python built-ins from `org_llm/agents/_builtins.py`
      2. `agent` DB table rows (per-installation customisation)
      3. ~/org/org-llm-agents.org (literate-config edits)

    Workflow:
      org-llm agents --tangle    # writes the org file
      $EDITOR ~/org/org-llm-agents.org
      org-llm launch              # picks up your edits

    Or, for DB-driven edits:
      org-llm agents --seed       # populate DB from built-ins
      org-llm agent set <name> persona "..."   # edit one field
      org-llm agent reset <name>  # drop the DB row, fall back to built-in
    """
    flags = sum(1 for f in (tangle, apply_from_org, list_, seed) if f)
    if flags > 1:
        red_alert("--tangle / --apply / --list / --seed are mutually exclusive.")
        raise typer.Exit(1)
    if seed:
        n_added = _seed_agents_table()
        if n_added == 0:
            on_screen("[dim]agent table already seeded — no rows added.[/dim]")
        else:
            on_screen(f"[green]✓[/green] seeded [bold]{n_added}[/bold] "
                      "agent row(s) into the DB.")
            on_screen("[dim]Edit any field with[/dim] "
                      "[bold]org-llm agent set <name> <field> <value>[/bold]")
        return
    engine = _engine()
    with get_session(engine) as session:
        org_dir = _org_dir(session)
    org_dir = Path(org_dir).expanduser()
    user_path = org_dir / "org-llm-agents.org"

    if list_ or flags == 0:
        resolved = _resolve_preconfigured_agents(org_dir)
        user_present = user_path.exists()
        on_screen(f"[lcars1]Resolved agents[/lcars1]  "
                  f"({len(resolved)})  "
                  f"[dim]source: "
                  f"{'~/org/org-llm-agents.org' if user_present else 'bundled defaults'}"
                  f"[/dim]")
        for name, definition in resolved.items():
            desc = (definition.get("description") or "").strip()[:80]
            prompt_words = len((definition.get("prompt") or "").split())
            on_screen(f"  [lcars2]{name:14s}[/lcars2]  "
                      f"{desc}  "
                      f"[dim]({prompt_words}-word prompt)[/dim]")
        if not user_present:
            on_screen("")
            on_screen("[dim]Tangle to org for editing:[/dim]  "
                      "[bold]org-llm agents --tangle[/bold]")
        return

    if tangle:
        # Tangle from the resolved Agent objects so every
        # editable field round-trips. Reads from
        # _resolve_active_agents (Python builtins → DB after
        # Phase 23.5; org file no longer a runtime layer, only
        # a tangle/apply target).
        active = _resolve_active_agents(org_dir)
        lines = [
            "#+TITLE: org-llm preconfigured agents",
            "#+FILETAGS: :org-llm:agents:literate-config:",
            "#+OPTIONS: toc:nil num:nil",
            "",
            "Generated by [[shell:org-llm agents --tangle][org-llm agents --tangle]].",
            "Edit the headings below — on the next [[shell:org-llm launch][org-llm launch]] (or",
            "[[shell:org-llm agents --apply][org-llm agents --apply]]) the file is",
            "auto-applied into the =agent= DB table when its mtime is newer than the",
            "newest DB row's =updated_at=. The DB is the live config; this file is",
            "a tangled mirror for human editing + version control.",
            "",
            "Each =:agent:=-tagged heading is one agent. Heading TEXT is the canonical",
            "birth-name. Properties round-trip every editable Agent field; body is",
            "the system prompt.",
            "",
        ]
        for a in active:
            lines.append(f"* {a.birth_name}                                                  :agent:")
            lines.append(":PROPERTIES:")
            lines.append(f":DESCRIPTION:  {a.description}")
            if a.aliases:
                lines.append(f":ALIASES:      {', '.join(a.aliases)}")
            if a.model_role:
                lines.append(f":MODEL_ROLE:   {a.model_role}")
            if a.triggers:
                lines.append(f":TRIGGERS:     {', '.join(a.triggers)}")
            if a.capabilities:
                lines.append(f":CAPABILITIES: {', '.join(a.capabilities)}")
            if a.recipes:
                lines.append(f":RECIPES:      {', '.join(a.recipes)}")
            if a.pack:
                lines.append(f":PACK:         {a.pack}")
            if a.origin and a.origin != "builtin":
                lines.append(f":ORIGIN:       {a.origin}")
            if not a.addressable:
                lines.append(f":ADDRESSABLE:  nil")
            lines.append(":END:")
            lines.append("")
            lines.append(a.persona.rstrip())
            lines.append("")
        org_dir.mkdir(parents=True, exist_ok=True)
        user_path.write_text("\n".join(lines))
        on_screen(f"[green]✓[/green] wrote [bold]{user_path}[/bold]  "
                  f"({len(active)} agent(s))")
        on_screen("[dim]Edit, then[/dim] [bold]org-llm launch[/bold]"
                  " [dim]— auto-apply lands the changes.[/dim]")
        return

    if apply_from_org:
        if not user_path.exists():
            red_alert(f"{user_path} doesn't exist. "
                      f"Run [bold]org-llm agents --tangle[/bold] first.")
            raise typer.Exit(1)
        n = _apply_org_file_to_db(user_path)
        if n == 0:
            on_screen(f"[yellow]⚠[/yellow] {user_path} parsed but "
                      f"contains no :agent:-tagged headings.")
        else:
            on_screen(f"[green]✓[/green] applied [bold]{n}[/bold] "
                      "agent row(s) from "
                      f"[bold]{user_path}[/bold] into the DB.")
        return

    # Unreachable; the flag-set check above handles all cases.
    return


@app.command(rich_help_panel="Maintenance")
def screenshot(
    tool:   Annotated[str,  typer.Option("--tool", "-t",
            help=f"Override screenshot_tool: one of "
                 f"{', '.join(sorted(_SCREENSHOT_BACKENDS))}, or 'custom'")] = "",
    cmd:    Annotated[str,  typer.Option("--cmd",
            help="Override screenshot_cmd template (used when --tool=custom). "
                 "Use '{path}' as the output-file placeholder")] = "",
    label:  Annotated[str,  typer.Option("--label", "-l",
            help="Filename hint, kebab-cased (e.g. 'opencode-active-card')")] = "screenshot",
    out:    Annotated[str,  typer.Option("--out", "-o",
            help="Override output path entirely. Skips screenshot_dir/label.")] = "",
    list_:  Annotated[bool, typer.Option("--list",
            help="Show available backends + which are installed")] = False,
):
    """Capture a screenshot via the configured backend.

    Default tool is `emacs` (uses `emacsclient -e
    (org-llm-opencode-screenshot)` — see `doom/org-llm.el`). Other
    backends shell out to `grim`/`maim`/`scrot`/`flameshot`. Set
    `--tool custom --cmd '<your-tool> {path}'` for anything else.

    Output goes to `screenshot_dir` (default: docs/img/ in the
    repo, or ~/org/.opencode/) unless `--out PATH` overrides it.
    The Emacs backend is special: it picks its own filename inside
    the configured directory so multiple captures don't collide.
    """
    import shutil as _sh
    if list_:
        on_screen("[lcars1]Screenshot backends[/lcars1]")
        for name, template in sorted(_SCREENSHOT_BACKENDS.items()):
            head = template.split()[0]
            installed = (name == "emacs"
                         and _sh.which("emacsclient")) or _sh.which(head)
            mark = "[green]✓[/green]" if installed else "[dim]✗[/dim]"
            on_screen(f"  {mark}  {name:12s}  {template}")
        on_screen("")
        on_screen("[dim]Pick one:[/dim] "
                  "[bold]org-llm config screenshot_tool <name>[/bold]")
        on_screen("[dim]Custom:[/dim]   "
                  "[bold]org-llm config screenshot_tool custom[/bold] "
                  "+ [bold]screenshot_cmd '<cmd> {path}'[/bold]")
        return

    engine = _engine()
    with get_session(engine) as session:
        chosen = (tool or _cfg(session, "screenshot_tool") or "emacs").strip()
        if chosen == "custom":
            template = (cmd or _cfg(session, "screenshot_cmd") or "").strip()
            if not template:
                red_alert("--tool custom needs --cmd or "
                          "screenshot_cmd config; e.g. "
                          "'flameshot gui --raw > {path}'")
                raise typer.Exit(1)
        else:
            template = _SCREENSHOT_BACKENDS.get(chosen)
            if template is None:
                red_alert(f"Unknown screenshot tool {chosen!r}. "
                          f"Run [bold]org-llm screenshot --list[/bold] "
                          f"to see options.")
                raise typer.Exit(1)
        ss_dir = _resolve_screenshot_dir(session)

    # Path resolution. The Emacs backend writes its OWN file (the
    # elisp picks a timestamped name in the buffer's directory or
    # docs/img/) so we don't pre-compute a path for it — we just
    # parse the path the elisp echoes back.
    ts = time.strftime("%Y%m%dT%H%M%S")
    safe_label = "-".join(label.lower().split()) or "screenshot"
    target_path = (Path(out).expanduser() if out else
                    ss_dir / f"{safe_label}-{ts}.svg"
                    if chosen == "emacs"
                    else ss_dir / f"{safe_label}-{ts}.png")
    ss_dir.mkdir(parents=True, exist_ok=True)

    # Emacs backend uses the doom helper, which itself writes the
    # SVG and prints the path. We just spawn emacsclient and surface
    # the message.
    if chosen == "emacs":
        if not _sh.which("emacsclient"):
            red_alert("emacsclient not on PATH. Either start "
                      "an Emacs server (M-x server-start in Doom) "
                      "or pick a different tool: "
                      "[bold]org-llm screenshot --list[/bold]")
            raise typer.Exit(1)
        # Pass directory + label hint so the elisp can name the
        # file consistently. The doom helper supports an optional
        # &rest path-hint; if the running version doesn't, the
        # fallback name still lands inside docs/img/.
        elisp = (f'(org-llm-opencode-screenshot nil '
                 f'"{ss_dir}" "{safe_label}-{ts}")')
        try:
            import subprocess
            r = subprocess.run(
                ["emacsclient", "-e", elisp],
                capture_output=True, text=True, timeout=10,
            )
            out_text = (r.stdout or "").strip()
            if r.returncode != 0:
                red_alert(f"emacsclient returned {r.returncode}: "
                          f"{(r.stderr or out_text).strip()}")
                raise typer.Exit(1)
            on_screen(f"[green]✓[/green] screenshot via emacs: "
                      f"[bold]{out_text}[/bold]")
            return
        except subprocess.TimeoutExpired:
            red_alert("emacsclient timed out. Is Emacs running with "
                      "(server-start)?")
            raise typer.Exit(1)

    # Non-Emacs backends: substitute {path} and exec.
    if "{path}" not in template:
        red_alert(f"screenshot_cmd template missing '{{path}}': {template!r}")
        raise typer.Exit(1)
    head = template.split()[0]
    if not _sh.which(head):
        red_alert(f"Backend {chosen!r} needs '{head}' on PATH "
                  f"(install via your distro / Guix). "
                  f"Or pick another: [bold]org-llm screenshot --list[/bold]")
        raise typer.Exit(1)
    expanded = template.replace("{path}", str(target_path))
    try:
        import subprocess
        r = subprocess.run(expanded, shell=True, timeout=120)
    except subprocess.TimeoutExpired:
        red_alert(f"{chosen} timed out after 120s.")
        raise typer.Exit(1)
    if r.returncode != 0:
        red_alert(f"{chosen} returned {r.returncode}.")
        raise typer.Exit(1)
    if target_path.exists() and target_path.stat().st_size > 0:
        on_screen(f"[green]✓[/green] screenshot via {chosen}: "
                  f"[bold]{target_path}[/bold]")
    else:
        on_screen(f"[yellow]⚠[/yellow] {chosen} returned 0 but "
                  f"{target_path} is missing — backend may have "
                  f"been cancelled.")


def _config_check_run() -> None:
    """Run a general configuration sanity check.

    Prints findings as a status table — one row per check, marked
    [✓] / [⚠] / [✗] / [-] (skipped). Exits 0 if no errors, 1 if any
    [✗] hits. Warnings don't fail the exit code (they're advisory).

    Categories:
      • models  — every role model is pulled in ollama (or cloud-prefixed)
      • ollama  — daemon reachable on configured URL
      • cloud   — provider/endpoint/key present if cloud_provider is set
      • org_dir — exists, is a directory
      • opencode — .opencode/ structure intact (config + theme + commands)
      • doom    — doom/org-llm.el slash references match plugin slashes
      • env     — knobs referenced via ORG_LLM_* env vars are documented
    """
    from rich.table import Table as _Tbl
    from rich.panel import Panel as _Pn
    from .db import Config as _Cfg
    rows: list[tuple[str, str, str]] = []   # (check, status, detail)

    def _add(name: str, status: str, detail: str) -> None:
        rows.append((name, status, detail))

    engine = _engine()
    with get_session(engine) as session:
        cfg_rows = {r.key: r.value for r in session.query(_Cfg).all()}
        org_dir = _org_dir(session)
        ollama_url = _ollama_url(session)

    # ── ollama reachability ────────────────────────────────────
    try:
        import urllib.request as _ur
        with _ur.urlopen(f"{ollama_url.rstrip('/')}/api/tags", timeout=2) as r:
            data = _json_load_safe(r.read())
        n_pulled = len(data.get("models", []) if isinstance(data, dict) else [])
        _add("ollama", "[green]✓[/green]",
              f"reachable @ {ollama_url}  ({n_pulled} pulled)")
        try:
            pulled = {_normalize_tag(m.get("name", ""))
                      for m in data.get("models", [])}
        except Exception:
            pulled = set()
    except Exception as e:
        _add("ollama", "[red]✗[/red]",
              f"unreachable @ {ollama_url}: {e}")
        pulled = set()

    # ── role-model pull check ──────────────────────────────────
    role_misses: list[str] = []
    for role, key, _label in _TASK_MODEL_KEYS:
        m = (cfg_rows.get(key) or "").strip()
        if not m:
            continue
        if "/" in m:
            # cloud-prefixed; verified separately under cloud check
            continue
        if not _is_pulled(m, pulled):
            role_misses.append(f"{role}={m}")
    if role_misses:
        _add("models", "[yellow]⚠[/yellow]",
              f"unpulled role models: {', '.join(role_misses)}  "
              f"(fix: org-llm launch will auto-pull)")
    else:
        _add("models", "[green]✓[/green]", "all role models pulled")

    # ── org_dir ────────────────────────────────────────────────
    if org_dir.exists() and org_dir.is_dir():
        n_org = sum(1 for _ in org_dir.rglob("*.org"))
        _add("org_dir", "[green]✓[/green]",
              f"{org_dir} ({n_org} .org files)")
    else:
        _add("org_dir", "[red]✗[/red]",
              f"{org_dir} missing or not a directory")

    # ── ssl ca bundle ─────────────────────────────────────────
    # HTTPS to cloud providers fails on Guix and minimal containers
    # without a discoverable CA bundle. We probe known paths and fall
    # back to certifi; this surfaces the result so users see a hint
    # before the first SSL error.
    try:
        from .cloud import _SSL_CONTEXT as _ssl_ctx
        if _ssl_ctx is not None:
            _add("ssl", "[green]✓[/green]", "CA bundle resolved")
        else:
            _add("ssl", "[red]✗[/red]",
                  "no CA bundle found — `pip install certifi` "
                  "(or distro `ca-certificates`/`nss-certs`)")
    except Exception as e:
        _add("ssl", "[dim]-[/dim]", f"probe skipped: {e}")

    # ── cloud config sanity ───────────────────────────────────
    cloud_prov = cfg_rows.get("cloud_provider", "")
    cloud_endpoint = cfg_rows.get("cloud_endpoint_url", "")
    cloud_model = cfg_rows.get("cloud_model", "")
    if cloud_prov:
        problems = []
        if not cloud_endpoint:
            problems.append("missing cloud_endpoint_url")
        if not cloud_model:
            problems.append("missing cloud_model")
        api_key = ""
        try:
            from . import creds as _creds
            api_key = _creds.read_secret(_creds.cloud_slug(cloud_prov)) or ""
        except Exception:
            pass
        if not api_key:
            problems.append(f"no API key in pass for slug {cloud_prov!r}")
        if problems:
            _add("cloud", "[red]✗[/red]",
                  f"cloud_provider={cloud_prov} but: {'; '.join(problems)}")
        else:
            _add("cloud", "[green]✓[/green]",
                  f"{cloud_prov}: {cloud_model} @ {cloud_endpoint[:40]}…")
    else:
        cf = (cfg_rows.get("proxy_cloud_first", "") or "false").lower() == "true"
        if cf:
            _add("cloud", "[red]✗[/red]",
                  "proxy_cloud_first=true but cloud_provider is empty")
        else:
            _add("cloud", "[dim]-[/dim]",
                  "cloud not configured (local-only)")

    # ── .opencode/ structure ──────────────────────────────────
    oc = org_dir / ".opencode"
    expected = ["opencode.json", "tui.json", "AGENTS.md",
                "themes/org-llm-lcars.json"]
    missing = [p for p in expected if not (oc / p).exists()]
    if not oc.exists():
        _add("opencode", "[dim]-[/dim]",
              f"{oc} missing (run: org-llm launch)")
    elif missing:
        _add("opencode", "[yellow]⚠[/yellow]",
              f"{oc.name}/ exists but missing: "
              f"{', '.join(missing)}  (re-run: org-llm launch)")
    else:
        _add("opencode", "[green]✓[/green]",
              f"{oc} fully wired ({len(expected)} files OK)")

    # ── doom keybinds ↔ plugin slash registry ────────────────
    repo_root = Path(__file__).resolve().parent.parent
    doom_path = repo_root / "doom" / "org-llm.el"
    plugin_path = (repo_root / "extensions" / "opencode" / "src"
                              / "sys-commands.tsx")
    try:
        plugin_src = plugin_path.read_text()
        # `slash: { name: "X" }` → set of registered slash names
        import re as _re
        plugin_slashes = set(_re.findall(
            r'slash:\s*\{\s*name:\s*"([a-z0-9_-]+)"', plugin_src))
        if doom_path.exists():
            doom_src = doom_path.read_text()
            # `/sysFOO` (alphanumeric, no hyphens — opencode rejects them)
            doom_refs = set(_re.findall(r'/(sys[a-z0-9]+)\b', doom_src))
            # Slashes mentioned in doom but NOT registered in plugin.
            stale = sorted(doom_refs - plugin_slashes)
            if stale:
                _add("doom", "[yellow]⚠[/yellow]",
                      f"doom references slashes the plugin doesn't "
                      f"register: {', '.join('/' + s for s in stale)}  "
                      f"(edit doom/org-llm.el or update plugin)")
            else:
                _add("doom", "[green]✓[/green]",
                      f"all {len(doom_refs)} doom slash references "
                      f"are in the plugin registry")
        else:
            _add("doom", "[dim]-[/dim]",
                  f"{doom_path.relative_to(repo_root)} not present")
    except Exception as e:
        _add("doom", "[yellow]⚠[/yellow]", f"could not check: {e}")

    # ── doom path drift (path knobs vs Emacs's org-* vars) ──
    # Phase 16.5: read the running Emacs's view of org-directory,
    # org-roam-dailies-directory, etc. and flag drift between Doom
    # and org-llm. Read-only — doesn't write. The user reconciles
    # via `org-llm doom-sync`.
    try:
        from .doom_introspect import (
            gather_doom_config as _gdoom,
            _emacsclient_available as _ec_avail,
        )
        if not _ec_avail():
            _add("doom-cfg", "[dim]-[/dim]",
                  "emacsclient not on PATH — skipped")
        else:
            info = _gdoom()
            doom_vals = info["values"]
            def _rp(v: str) -> str:
                if not v or "," in v:
                    return (v or "").strip()
                return os.path.realpath(os.path.expanduser(
                    os.path.expandvars(v)))
            drifted = []
            for k in ("org_dir", "daily_dir", "inbox_path", "agenda_files"):
                dv = doom_vals.get(k, "")
                cv = (cfg_rows.get(k) or "").strip()
                if dv and _rp(dv) != _rp(cv):
                    drifted.append(k)
            if not doom_vals:
                _add("doom-cfg", "[dim]-[/dim]",
                      "no Emacs server reachable")
            elif drifted:
                _add("doom-cfg", "[yellow]⚠[/yellow]",
                      f"drift in {len(drifted)} key(s): "
                      f"{', '.join(drifted)}  "
                      f"(reconcile: org-llm doom-sync)")
            else:
                _add("doom-cfg", "[green]✓[/green]",
                      f"{len(doom_vals)} path(s) in lockstep with Doom")
    except Exception as e:
        _add("doom-cfg", "[yellow]⚠[/yellow]", f"probe skipped: {e}")

    # ── env-var coverage ──────────────────────────────────────
    # Every config key has an ORG_LLM_<KEY>= env-var override per
    # literate_config.env_var_for. Verify each currently-set env
    # var matches a known key (typo guard).
    try:
        from .literate_config import (
            KEY_DESCRIPTIONS as _DESCS,
            env_var_for as _envname,
        )
        from .db import MODEL_DEFAULTS as _DEF
        valid_keys = set(_DEF) | set(_DESCS) | set(cfg_rows)
        valid_envs = {_envname(k) for k in valid_keys} | {
            "ORG_LLM_ORG_DIR", "ORG_LLM_OLLAMA_URL", "ORG_LLM_DB_PATH",
        }
        unknown = sorted(
            v for v in os.environ
            if v.startswith("ORG_LLM_") and v not in valid_envs
        )
        if unknown:
            _add("env", "[yellow]⚠[/yellow]",
                  f"ORG_LLM_* env vars not mapped to any config key: "
                  f"{', '.join(unknown[:6])}"
                  + (f" (+{len(unknown)-6} more)" if len(unknown) > 6 else ""))
        else:
            _add("env", "[green]✓[/green]",
                  f"all ORG_LLM_* env vars match known config keys")
    except Exception as e:
        _add("env", "[dim]-[/dim]", f"env coverage check skipped: {e}")

    # ── hardware fitness for the current chat_model ──────────
    try:
        from .cloud import local_ram_gb, model_needs_vram
        chat_mdl = (cfg_rows.get("chat_model") or "").strip()
        ram = local_ram_gb()
        need = model_needs_vram(chat_mdl) if chat_mdl else None
        cloud_first = (cfg_rows.get("proxy_cloud_first")
                        or "false").strip().lower() == "true"
        if need is None or not chat_mdl:
            _add("hardware", "[dim]-[/dim]",
                  f"chat_model footprint unknown for {chat_mdl!r}")
        elif ram < need * 1.2:
            if cloud_first:
                _add("hardware", "[green]✓[/green]",
                      f"free RAM {ram:.1f} GB < 1.2× chat_model "
                      f"({need:.1f} GB) — cloud_first ON, mitigated")
            else:
                _add("hardware", "[yellow]⚠[/yellow]",
                      f"free RAM {ram:.1f} GB < 1.2× chat_model "
                      f"({need:.1f} GB). Enable cloud_first: "
                      f"`org-llm config proxy_cloud_first true`")
        else:
            _add("hardware", "[green]✓[/green]",
                  f"free RAM {ram:.1f} GB ≥ 1.2× chat_model "
                  f"({need:.1f} GB)")
    except Exception as e:
        _add("hardware", "[dim]-[/dim]", f"probe skipped: {e}")

    # ── Render ─────────────────────────────────────────────────
    tbl = _Tbl(box=None, pad_edge=False, show_header=True)
    tbl.add_column("Check",   style="lcars2", no_wrap=True, width=10)
    tbl.add_column("Status",  width=4, no_wrap=True)
    tbl.add_column("Detail",  style="dim")
    for n, st, dt in rows:
        tbl.add_row(n, st, dt)
    console.print()
    console.print(_Pn(tbl,
                       title="[lcars1]config check[/lcars1]",
                       border_style="lcars2",
                       padding=(1, 1)))
    n_err = sum(1 for _, st, _ in rows if "✗" in st)
    n_warn = sum(1 for _, st, _ in rows if "⚠" in st)
    summary = f"{len(rows)} checks · "
    if n_err:
        summary += f"[red]{n_err} error(s)[/red]"
    if n_warn:
        summary += (f"  [yellow]{n_warn} warning(s)[/yellow]"
                     if n_err else f"[yellow]{n_warn} warning(s)[/yellow]")
    if not (n_err or n_warn):
        summary += "[green]all green[/green]"
    on_screen(summary)
    if n_err:
        raise typer.Exit(1)


def _json_load_safe(b: bytes) -> dict:
    """Best-effort JSON load — returns {} on any failure. Used
    by _config_check_run where we don't want a malformed ollama
    response to crash the whole check pass."""
    import json as _j
    try:
        out = _j.loads(b.decode("utf-8", "replace"))
        return out if isinstance(out, dict) else {}
    except Exception:
        return {}


@app.command(name="baselines", rich_help_panel="Maintenance")
def baselines(
    name:    Annotated[str,  typer.Argument(help="Baseline name to "
             "show/edit/toggle (omit to list all)")] = "",
    show:    Annotated[bool, typer.Option("--show",
             help="Print the full body of NAME")] = False,
    enable:  Annotated[bool, typer.Option("--enable",
             help="Enable baseline NAME")] = False,
    disable: Annotated[bool, typer.Option("--disable",
             help="Disable baseline NAME (skipped at injection)")] = False,
):
    """Inspect and manage the agent_baseline table — the prompt
    fragments every agent inherits (time awareness, vault-first,
    parallel tool calls, no-hallucination, fast crew review).

    Without arguments: list all baselines with name, scope,
    enabled flag, sort order, body length.

    `org-llm baselines time_awareness --show` prints the full
    body. `--disable`/`--enable` toggle injection without removing
    the row (so you can flip behaviours without losing the body)."""
    from rich.table import Table as _Tbl
    from rich.panel import Panel as _Pn
    from .db import AgentBaseline as _AB
    engine = _engine()
    with get_session(engine) as s:
        if name and (enable or disable):
            row = s.query(_AB).filter(_AB.name == name).first()
            if not row:
                red_alert(f"no such baseline: {name}")
                raise typer.Exit(1)
            row.enabled = 0 if disable else 1
            s.commit()
            on_screen(f"[green]✓[/green] {name} → "
                      f"{'enabled' if row.enabled else 'disabled'}")
            raise typer.Exit(0)
        if name and show:
            row = s.query(_AB).filter(_AB.name == name).first()
            if not row:
                red_alert(f"no such baseline: {name}")
                raise typer.Exit(1)
            on_screen(f"[lcars1]baseline · {row.name}[/lcars1]")
            on_screen(f"  scope:    {row.applies_to}")
            on_screen(f"  enabled:  {bool(row.enabled)}")
            on_screen(f"  order:    {row.sort_order}")
            on_screen(f"  body ({len(row.body)} chars):")
            on_screen(f"\n{row.body}\n")
            raise typer.Exit(0)
        rows = (s.query(_AB).order_by(_AB.sort_order).all())
        if not rows:
            on_screen("[dim]no baselines registered (run launch to "
                      "seed defaults)[/dim]")
            raise typer.Exit(0)
        tbl = _Tbl(box=None, pad_edge=False, show_header=True)
        tbl.add_column("Name",     style="lcars2", no_wrap=True, width=22)
        tbl.add_column("Scope",    style="dim",   width=18, overflow="fold")
        tbl.add_column("Order",    style="dim",   width=5)
        tbl.add_column("Status",   width=8)
        tbl.add_column("Body chars", style="dim", width=10)
        for r in rows:
            status = ("[green]on[/green]" if r.enabled
                      else "[dim]off[/dim]")
            tbl.add_row(r.name, r.applies_to, str(r.sort_order),
                         status, str(len(r.body or "")))
        console.print()
        console.print(_Pn(tbl,
                           title=f"[lcars1]agent baselines · "
                                 f"{len(rows)}[/lcars1]",
                           border_style="lcars2",
                           padding=(1, 1)))
        on_screen("[dim]inspect: org-llm baselines <name> --show"
                  "    toggle: --enable / --disable[/dim]")


@app.command(name="crew-log", rich_help_panel="Maintenance")
def crew_log(
    last: Annotated[int, typer.Option("--last", "-n",
            help="Show the last N entries (default 20)")] = 20,
    session: Annotated[str, typer.Option("--session", "-s",
            help="Filter by session_id substring")] = "",
    outcome: Annotated[str, typer.Option("--outcome",
            help="Filter by outcome (ok / empty / timeout / error / "
                 "rejected)")] = "",
):
    """Inspect the manager's audit trail — every delegate(),
    proactive_doctor() consult, sanity-check, and retry the crew
    has performed, with timestamps, models, and durations.

    Useful for answering "what did the manager actually do during
    that turn?" — the export only shows user-facing chat; this
    surfaces the orchestration that happened underneath."""
    from rich.table import Table as _Tbl
    from rich.panel import Panel as _Pn
    from .db import CrewLog as _CL
    engine = _engine()
    with get_session(engine) as session_db:
        q = session_db.query(_CL).order_by(_CL.id.desc())
        if session:
            q = q.filter(_CL.session_id.contains(session))
        if outcome:
            q = q.filter(_CL.outcome == outcome)
        rows = q.limit(last).all()
    if not rows:
        on_screen("[dim]no crew_log entries match[/dim]")
        raise typer.Exit(0)
    tbl = _Tbl(box=None, pad_edge=False, show_header=True)
    tbl.add_column("Time",     style="dim",   no_wrap=True, width=10)
    tbl.add_column("Action",   style="lcars2", width=8)
    tbl.add_column("Agent",    width=12)
    tbl.add_column("Model",    style="dim",   width=22, overflow="fold")
    tbl.add_column("ms",       style="dim",   width=6, no_wrap=True)
    tbl.add_column("Outcome",  width=8)
    tbl.add_column("Prompt",   style="dim",   overflow="fold")
    for r in reversed(rows):  # oldest at top — natural reading order
        ts = (r.timestamp or "")[-9:-1]   # HH:MM:SSZ → HH:MM:SS
        outcome_color = {
            "ok":       "[green]ok[/green]",
            "empty":    "[yellow]empty[/yellow]",
            "timeout":  "[red]timeout[/red]",
            "error":    "[red]error[/red]",
            "rejected": "[yellow]rejected[/yellow]",
        }.get(r.outcome, r.outcome or "?")
        tbl.add_row(
            ts,
            r.action,
            r.agent_to or r.agent_from,
            r.model or "",
            str(r.duration_ms or 0),
            outcome_color,
            (r.prompt_excerpt or "")[:80],
        )
    console.print()
    console.print(_Pn(tbl,
                       title=f"[lcars1]crew-log · last {len(rows)}[/lcars1]",
                       border_style="lcars2",
                       padding=(1, 1)))


@app.command(name="validate", rich_help_panel="Maintenance")
def validate_cmd(
    feature: Annotated[str, typer.Argument(
        help="Registered feature name. Use --list to see all.")] = "",
    list_features: Annotated[bool, typer.Option("--list", "-l",
        help="List registered validation configs and exit.")] = False,
    trials: Annotated[int, typer.Option("--trials", "-t",
        help="Trials per (prompt × arm × model). Default 3.")] = 3,
    harness_only: Annotated[bool, typer.Option("--harness-only",
        help="Run the A/B harness only; skip the judge.")] = False,
    judge_only: Annotated[bool, typer.Option("--judge-only",
        help="Skip the harness; just judge the existing results "
             "JSONL.")] = False,
):
    """Run A/B + blinded-judge validation for an LLM-mediated feature.

    The framework lives in =org_llm/validation.py=; registered configs
    in =org_llm/validation_configs/=. Each config defines two arms,
    a prompt set, optional ground-truth file, and bars.

    Run =org-llm validate --list= to see what's registered.
    Run =org-llm validate <name>= to run the full pipeline.

    Output lands under =~/.local/share/org-llm/validation/<name>/=
    (results.jsonl, judgments.jsonl, summary.md).

    Heavyweight — each run costs cloud calls. Not for every commit;
    run periodically as a regression check or after touching a
    feature's implementation."""
    from . import validation as _val
    # Trigger config registrations at first call.
    from . import validation_configs as _vcfg  # noqa: F401

    if list_features:
        names = _val.list_registered()
        if not names:
            on_screen("[dim]No validation configs registered.[/dim]")
            return
        from rich.table import Table as _Tbl
        from rich.panel import Panel as _Pn
        tbl = _Tbl(show_header=True, header_style="bold cyan",
                    box=None, padding=(0, 2))
        tbl.add_column("name", style="bold")
        tbl.add_column("kind")
        tbl.add_column("description")
        tbl.add_column("scope", justify="right")
        for n in names:
            cfg = _val.get(n)
            if cfg.kind == "deterministic":
                scope = f"{len(cfg.checks)} checks"
            else:
                anchor = sum(1 for _, b, _ in cfg.prompts if b == "anchor")
                scope = f"{len(cfg.prompts)} prompts ({anchor} anchor)"
            tbl.add_row(n, cfg.kind, cfg.description[:60], scope)
        console.print()
        console.print(_Pn(tbl,
                          title="[lcars1]validate · registered configs[/lcars1]",
                          border_style="lcars2",
                          padding=(1, 1)))
        on_screen("[dim]Run [bold]org-llm validate <name>[/bold] to validate.[/dim]")
        return

    if not feature:
        on_screen("[lcars2]Specify a feature or pass --list. "
                  "Example: [bold]org-llm validate recipes[/bold][/lcars2]")
        raise typer.Exit(code=2)

    cfg = _val.get(feature)
    if cfg is None:
        on_screen(f"[lcars2]No validation config registered for "
                  f"[bold]{feature}[/bold].[/lcars2]")
        avail = ', '.join(_val.list_registered()) or '(none)'
        on_screen(f"[dim]Available: {avail}[/dim]")
        raise typer.Exit(code=2)

    paths = _val.output_paths(feature)
    on_screen(f"[lcars1]validate · {feature}[/lcars1]")
    on_screen(f"  {cfg.description}")
    on_screen(f"  kind:     {cfg.kind}")
    if cfg.kind == "deterministic":
        on_screen(f"  checks:   {len(cfg.checks)}")
    else:
        on_screen(f"  prompts:  {len(cfg.prompts)}")
        on_screen(f"  trials:   {trials}")
    on_screen(f"  output:   {paths['results'].parent}")

    # Deterministic configs run a different pipeline — no A/B, no judge.
    if cfg.kind == "deterministic":
        if harness_only or judge_only:
            on_screen("[lcars2]--harness-only / --judge-only ignored "
                      "for deterministic configs.[/lcars2]")
        try:
            summary = _val.run_deterministic(
                cfg, progress=lambda s: on_screen(f"  · {s}"))
        except Exception as e:
            on_screen(f"[red]Deterministic run failed: "
                      f"{type(e).__name__}: {e}[/red]")
            raise typer.Exit(code=1) from e
        on_screen("")
        passed = summary["summary"]["passed"]
        total  = summary["summary"]["total"]
        verdict_color = "green" if summary["verdict"] == "PASS" else "red"
        on_screen(f"[{verdict_color}]{summary['verdict']}[/{verdict_color}]"
                  f"  {passed}/{total} checks passed")
        on_screen(f"[dim]Summary: {paths['summary']}[/dim]")
        # Surface failing checks inline so the user doesn't need to open
        # the file to see what's broken.
        if summary["verdict"] == "FAIL":
            on_screen("")
            on_screen("[lcars2]Failures:[/lcars2]")
            for group, entries in summary["groups"].items():
                for e in entries:
                    if not e["passed"]:
                        msg = e["message"] or e["error"] or "(no message)"
                        on_screen(f"  [red]✗[/red] {group} · {e['check']}: {msg}")
        # Exit code: 0 on PASS, 1 on FAIL — useful for cron / CI.
        if summary["verdict"] != "PASS":
            raise typer.Exit(code=1)
        return

    if not judge_only:
        on_screen("[lcars2]Running A/B harness — this calls cloud per "
                  "trial × arm × prompt.[/lcars2]")
        # NOTE: cloud_endpoint + api_key sourcing is feature-specific
        # in the current shape; the recipe arms read them via the
        # scripts/recipe_ab_harness module's own env probes. Future
        # configs that want framework-managed cloud creds can grow a
        # ValidationConfig.cloud_provider hint.
        try:
            results_path = _val.run_validation(
                cfg, trials=trials,
                progress=lambda s: on_screen(f"  · {s}"))
            on_screen(f"[lcars1]✓ Harness wrote {results_path}[/lcars1]")
        except Exception as e:
            on_screen(f"[red]Harness failed: {type(e).__name__}: {e}[/red]")
            raise typer.Exit(code=1) from e

    if harness_only:
        return

    try:
        summary_path = _val.run_judge(cfg)
        on_screen(f"[lcars1]✓ Judge summary: {summary_path}[/lcars1]")
    except NotImplementedError as e:
        on_screen(f"[lcars2]Judge: {e}[/lcars2]")
    except Exception as e:
        on_screen(f"[red]Judge failed: {type(e).__name__}: {e}[/red]")
        raise typer.Exit(code=1) from e


@app.command(name="doom-sync", rich_help_panel="Maintenance")
def doom_sync(
    yes:     Annotated[bool, typer.Option("--yes", "-y",
             help="Apply detected changes without prompting")] = False,
    dry_run: Annotated[bool, typer.Option("--dry-run", "-n",
             help="Show the diff and exit without writing")] = False,
    doom_dir: Annotated[str,  typer.Option("--doom-dir",
             help="Override Doom config directory "
                  "(default: ~/.config/doom)")] = "",
):
    """Read Doom Emacs config and reconcile org-llm's path knobs.

    Probes the running Emacs via `emacsclient --eval` for
    `org-directory`, `org-roam-dailies-directory`,
    `org-default-notes-file`, and `org-agenda-files`. Falls back to
    a static parse of `~/.config/doom/{config,init}.el` when no
    Emacs server is reachable.

    Prints a diff table — *setting · doom value · current value ·
    action* — and applies confirmed changes. `--yes` skips the
    prompt; `--dry-run` exits 0 after printing.

    Doom is the source of truth for paths the user already edits in
    Emacs; org-llm-only knobs (chat_model, proxy_*) are never
    touched by this command.
    """
    from rich.table import Table as _Tbl
    from rich.panel import Panel as _Pn
    from .doom_introspect import (
        gather_doom_config as _gather,
        _emacsclient_available as _ec_avail,
    )
    from .db import Config as _Cfg

    dpath = Path(doom_dir).expanduser() if doom_dir else None
    info = _gather(dpath)
    values, source = info["values"], info["source"]

    engine = _engine()
    with get_session(engine) as session:
        cur_rows = {r.key: r.value for r in session.query(_Cfg).all()}

    def _norm(v: str) -> str:
        v = (v or "").strip()
        if not v or "," in v:    # agenda_files is comma-joined
            return v
        return os.path.realpath(os.path.expanduser(os.path.expandvars(v)))

    rows: list[tuple[str, str, str, str, str]] = []  # (key, doom, cur, src, action)
    for ckey in ("org_dir", "daily_dir", "inbox_path", "agenda_files"):
        doom_val = values.get(ckey, "")
        cur_val  = (cur_rows.get(ckey) or "").strip()
        src      = source.get(ckey, "missing")
        if not doom_val:
            action = "[dim]skip[/dim]"
        elif _norm(cur_val) == _norm(doom_val):
            action = "[green]match[/green]"
        elif not cur_val:
            action = "[yellow]set[/yellow]"
        else:
            action = "[yellow]update[/yellow]"
        rows.append((ckey, doom_val, cur_val, src, action))

    tbl = _Tbl(box=None, pad_edge=False, show_header=True)
    tbl.add_column("Key",           style="lcars2", no_wrap=True, width=14)
    tbl.add_column("Doom value",    style="dim",    overflow="fold")
    tbl.add_column("Current value", style="dim",    overflow="fold")
    tbl.add_column("Source",        width=8)
    tbl.add_column("Action",        width=8, no_wrap=True)
    for r in rows:
        tbl.add_row(*r)
    console.print()
    title = ("[lcars1]doom-sync[/lcars1]"
             + ("" if _ec_avail()
                else "  [yellow](no emacsclient — static parse only)[/yellow]"))
    console.print(_Pn(tbl, title=title, border_style="lcars2",
                       padding=(1, 1)))

    pending = [(k, dv) for k, dv, cv, _s, _a in rows
               if dv and _norm(dv) != _norm(cv)]
    if not pending:
        on_screen("[green]all keys already match Doom — nothing to do[/green]")
        raise typer.Exit(0)

    if dry_run:
        on_screen(f"[dim]dry-run · {len(pending)} change(s) not "
                  f"applied[/dim]")
        raise typer.Exit(0)

    if not yes:
        on_screen(f"\nApply {len(pending)} change(s)? "
                  "[y/N] ", end="")
        try:
            ans = input().strip().lower()
        except EOFError:
            ans = ""
        if ans not in ("y", "yes"):
            on_screen("[dim]aborted — no changes written[/dim]")
            raise typer.Exit(0)

    with get_session(engine) as session:
        for ckey, dv in pending:
            row = session.query(_Cfg).filter(_Cfg.key == ckey).first()
            if row:
                row.value = dv
            else:
                session.add(_Cfg(key=ckey, value=dv))
        session.commit()
    on_screen(f"[green]✓[/green] applied {len(pending)} change(s) "
              f"from Doom")


@app.command(rich_help_panel="Maintenance")
def config(
    key:   Annotated[str, typer.Argument(help="Config key")] = "",
    value: Annotated[str, typer.Argument(help="Value to set")] = "",
    tangle: Annotated[bool, typer.Option("--tangle", "-T",
            help="Write ~/org/org-llm-config.org from the current DB state")] = False,
    apply_from_org: Annotated[bool, typer.Option("--apply-from-org", "-A",
            help="Read ~/org/org-llm-config.org and apply changes to DB")] = False,
    diff_org: Annotated[bool, typer.Option("--diff-org", "-D",
            help="Show what would change if we applied the org file (read-only)")] = False,
    dry_run: Annotated[bool, typer.Option("--dry-run", "-n",
            help="With --apply-from-org, preview without writing")] = False,
    keys: Annotated[str, typer.Option("--keys", "-K",
            help="With --tangle: comma-sep keys (or 'doctor_*' prefix-glob) "
                 "to include. Omits everything else. Default: all keys.")] = "",
    to_path: Annotated[str, typer.Option("--to", "-O",
            help="With --tangle: write to PATH instead of "
                 "~/org/org-llm-config.org. Useful for focused side-files.")] = "",
    no_knobs: Annotated[bool, typer.Option("--no-knobs",
            help="With --tangle: skip the Theme knobs section.")] = False,
    search:  Annotated[str, typer.Option("--search", "-S",
            help="Fuzzy-search config keys: matches on key name AND "
                 "description. Returns each hit with its current value.")] = "",
    check:   Annotated[bool, typer.Option("--check", "-C",
            help="Run a general configuration sanity check (models pulled, "
                 "cloud creds present, ollama reachable, doom keybinds in "
                 "sync with /sys* slashes, .opencode/ structure intact)")] = False,
):
    """Get or set a config value. No args = show all.

    Literate-config mode (org-file mirror):
      --tangle [--keys K1,K2 --to PATH --no-knobs]
                          write a literate org file from DB. Selective
                          via --keys (e.g. 'chat_model,doctor_*'); custom
                          path via --to (good for focused side-files).
      --apply-from-org    read it back, write changes to DB
      --diff-org          show the would-apply diff without writing

    Round-trips every user-tweakable key + every user-defined theme
    knob (one heading per knob, one src block per message). Excludes
    runtime state (cloud_usage, db_version).
    """
    if sum(1 for f in (tangle, apply_from_org, diff_org, bool(search), check) if f) > 1:
        red_alert("--tangle / --apply-from-org / --diff-org / --search / --check are mutually exclusive.")
        raise typer.Exit(1)
    if check:
        _config_check_run()
        return
    if search:
        from .literate_config import (
            KEY_DESCRIPTIONS as _DESCS,
            env_var_for as _envname,
        )
        from .db import Config as _Cfg, MODEL_DEFAULTS as _DEF
        engine = _engine()
        with get_session(engine) as session:
            db_rows = {r.key: r.value or "" for r in session.query(_Cfg).all()}
        all_keys = sorted(set(db_rows) | set(_DEF) | set(_DESCS))
        ql = search.lower()
        hits: list[tuple[str, str, str, str, str]] = []
        # Match on key name, description, AND env-var name so
        # `--search ORG_LLM_LOG` finds log_* keys via their env taps too.
        for k in all_keys:
            desc = _DESCS.get(k, "")
            env_name = _envname(k)
            if (ql in k.lower() or ql in desc.lower()
                    or ql in env_name.lower()):
                env_val = os.environ.get(env_name)
                if env_val is not None:
                    cur, src = env_val, "env"
                elif k in db_rows and db_rows[k]:
                    cur, src = db_rows[k], "config"
                else:
                    cur, src = _DEF.get(k, ""), "default"
                hits.append((k, cur, src, desc, env_name))
        if not hits:
            on_screen(f"[dim]No config keys match {search!r}.[/dim]")
            return
        from rich.panel import Panel as _Panel
        tbl = Table(box=None, pad_edge=False)
        tbl.add_column("Key",         style="lcars1", no_wrap=True)
        tbl.add_column("Value",       style="lcars2")
        tbl.add_column("Source",      width=8, no_wrap=True)
        tbl.add_column("Env override", style="dim",   no_wrap=True)
        tbl.add_column("Description", style="dim")
        src_style = {
            "env":     "[yellow]env[/yellow]",
            "config":  "[lcars3]config[/lcars3]",
            "default": "[dim]default[/dim]",
        }
        for k, v, src, d, env_name in hits:
            tbl.add_row(k, (v or "")[:40], src_style[src], env_name, d)
        console.print()
        console.print(_Panel(tbl,
                              title=f"[lcars1]config search: {search!r}[/lcars1]  "
                                    f"[dim]({len(hits)} hit{'s' if len(hits) != 1 else ''})[/dim]",
                              border_style="lcars2", padding=(1, 1)))
        on_screen("[dim]Set:[/dim] "
                  "[bold]org-llm config <key> <value>[/bold]  "
                  "[dim](or:[/dim] [bold]ORG_LLM_<KEY>=value org-llm …[/bold]"
                  "[dim] for one-shot env override)[/dim]")
        on_screen("[dim]Edit literately:[/dim] "
                  "[bold]org-llm config --tangle --keys '<key>'[/bold]")
        return
    if tangle:
        from . import literate_config as _lc
        keys_list = [k.strip() for k in keys.split(",")] if keys else None
        target = Path(to_path).expanduser() if to_path else None
        p = _lc.tangle_db_to_org(keys=keys_list,
                                    include_knobs=not no_knobs,
                                    to_path=target)
        scope = "all keys" if not keys_list else f"{len(keys_list)} key spec(s)"
        hail(f"Wrote literate config ({scope}): {p}")
        on_screen(f"[dim]Edit it; then:[/dim] "
                  "[bold]org-llm config --apply-from-org[/bold]")
        return
    if diff_org:
        from . import literate_config as _lc
        diffs = _lc.diff_db_vs_org()
        if not diffs:
            on_screen("[lcars3]✓ DB and literate config are in sync.[/lcars3]")
            return
        from rich.panel import Panel as _Panel
        tbl = Table(box=None, pad_edge=False)
        tbl.add_column("Key",       style="lcars1")
        tbl.add_column("Direction", width=10)
        tbl.add_column("DB value",  style="dim")
        tbl.add_column("Org value", style="lcars2")
        for k, db_v, org_v, direction in diffs:
            tbl.add_row(k, direction, db_v[:60], org_v[:60])
        console.print()
        console.print(_Panel(tbl, title="[lcars1]config diff (DB ↔ org)[/lcars1]",
                              border_style="lcars2", padding=(1, 1)))
        on_screen("[dim]Apply with:[/dim] [bold]org-llm config --apply-from-org[/bold]")
        return
    if apply_from_org:
        from . import literate_config as _lc
        n, changes = _lc.apply_org_to_db(dry_run=dry_run)
        if not changes:
            on_screen("[dim]No changes — DB already matches org file.[/dim]")
            return
        for k, old, new in changes:
            arrow = "→" if not dry_run else "(would →)"
            on_screen(f"  [lcars1]{k}[/lcars1]: {old!r} {arrow} {new!r}")
        if dry_run:
            on_screen(f"[dim]{n} change(s) — re-run without --dry-run to apply.[/dim]")
        else:
            hail(f"Applied {n} change(s) from {_lc.literate_path()}")
        return
    import difflib as _dl
    from .db import Config as Cfg
    engine = _engine()
    with get_session(engine) as session:
        if not key:
            from .literate_config import env_var_for as _envname
            table = Table(box=None, pad_edge=False)
            table.add_column("Key",          style="lcars1", no_wrap=True)
            table.add_column("Value",        style="lcars2")
            table.add_column("Source",       width=8, no_wrap=True)
            table.add_column("Env override", style="dim",   no_wrap=True)
            # Union of DB rows + MODEL_DEFAULTS so unset-but-known
            # keys still show up with their default + ENV name.
            known_keys = sorted(
                {r.key for r in session.query(Cfg).all()} | set(MODEL_DEFAULTS.keys())
            )
            for k in known_keys:
                env_name = _envname(k)
                env_val  = os.environ.get(env_name)
                row      = session.get(Cfg, k)
                if env_val is not None:
                    val, src = env_val, "[yellow]env[/yellow]"
                elif row and row.value:
                    val, src = row.value, "[lcars3]config[/lcars3]"
                else:
                    val, src = MODEL_DEFAULTS.get(k, ""), "[dim]default[/dim]"
                # Show the env name regardless — discoverability win.
                table.add_row(k, (val or "")[:60], src, env_name)
            console.print(table)
            on_screen("[dim]Tip:[/dim] every key has an "
                      "[bold]ORG_LLM_<KEY>[/bold] env override; set it for "
                      "this shell to test a value without writing config.")
        elif not value:
            from .literate_config import env_var_for as _envname, KEY_DESCRIPTIONS
            env_name = _envname(key)
            env_val  = os.environ.get(env_name)
            row = session.get(Cfg, key)
            if env_val is not None:
                console.print(env_val)
                on_screen(f"[dim]Source:[/dim] [yellow]env override[/yellow]  "
                          f"[dim]({env_name}={env_val!r})[/dim]")
            elif row:
                console.print(row.value)
                on_screen(f"[dim]Source:[/dim] [lcars3]config table[/lcars3]  "
                          f"[dim]·[/dim] env: [bold]{env_name}[/bold] (unset)")
            else:
                # Unknown / unset — fuzzy-match against actual rows + defaults.
                known = {r.key for r in session.query(Cfg).all()} | set(MODEL_DEFAULTS.keys())
                guess = _dl.get_close_matches(key, sorted(known), n=3, cutoff=0.55)
                if key in MODEL_DEFAULTS:
                    console.print(MODEL_DEFAULTS[key])
                    on_screen(f"[dim]Source:[/dim] [dim]default[/dim]  "
                              f"[dim]·[/dim] env: [bold]{env_name}[/bold] (unset)")
                else:
                    console.print("[error]not set[/error]")
                    on_screen(f"[dim]Env tap:[/dim] [bold]{env_name}[/bold]")
                if guess:
                    on_screen(f"[dim]Did you mean: {', '.join(guess)}?[/dim]")
            desc = KEY_DESCRIPTIONS.get(key)
            if desc:
                on_screen(f"[dim]{desc}[/dim]")
        else:
            err = _validate_config(key, value)
            if err:
                red_alert(err)
                # Suggest a likely correct key on validation failure too.
                known = {r.key for r in session.query(Cfg).all()} | set(MODEL_DEFAULTS.keys())
                guess = _dl.get_close_matches(key, sorted(known), n=3, cutoff=0.55)
                if guess:
                    on_screen(f"[dim]Did you mean: {', '.join(guess)}?[/dim]")
                raise typer.Exit(1)

            # Value-side fuzzy match for *_model keys: when the user types
            # `org-llm config chat_model qwn`, surface plausible real model
            # tags (pulled + catalog) before silently writing nonsense.
            if key.endswith("_model") and value:
                url = _ollama_url(session)
                cand = _suggest_model_tag(value, url)
                if cand and cand != value:
                    on_screen(f"[yellow]Model tag {value!r} not pulled and "
                              f"not in catalog.[/yellow]")
                    on_screen(f"[dim]Closest:[/dim] [bold]{cand}[/bold]")
                    if typer.confirm(f"Use {cand!r} instead?", default=True):
                        value = cand

            row = session.get(Cfg, key)
            if row:
                row.value = value
            else:
                # Brand-new key — warn if it doesn't fuzzy-match any known key.
                # We allow unknown keys (extension knobs use them) but the user
                # should know if they're typing something nobody else reads.
                known = {r.key for r in session.query(Cfg).all()} | set(MODEL_DEFAULTS.keys())
                if key not in known:
                    guess = _dl.get_close_matches(key, sorted(known), n=2, cutoff=0.7)
                    if guess:
                        on_screen(f"[yellow]New key {key!r} — "
                                  f"did you mean {' / '.join(guess)}?[/yellow]")
                session.add(Cfg(key=key, value=value))
            session.commit()
            hail(f"{key} = {value}")
            # Best-effort literate-config autosync — silent if disabled.
            try:
                from . import literate_config as _lc
                _lc.maybe_autosync()
            except Exception:
                pass
            # Auto-regen the theme cache when a knob level (or the
            # `theme_knobs` registry itself) changes. Fires in a daemon
            # thread so the CLI returns immediately; survives Python
            # exit because it's a fire-and-forget.
            #
            # Match knob names from the registry (so unrelated keys
            # like `log_level` / `doctor_*` don't trigger regen) plus
            # `theme_knobs` (the registry itself).
            if _is_knob_level_key(key) or key == "theme_knobs":
                _spawn_theme_regen_in_background(key, value)
            make_it_so()


def _captains_log_reflect(rows: list, model: str, base_url: str) -> str:
    """LLM reflection on a window of Captain's Log entries.

    Reads up to ~50 recent events, hands them to the configured chat
    model with a tight "what patterns + suggestions" prompt. Returns
    the model's reply or "" on any failure (caller decides how to surface).
    """
    if not rows:
        return ""
    # Compact representation — one line per event, low-token.
    lines = []
    for r in rows:
        ts = (r.timestamp or "")[:19]
        kind = (r.kind or "?")[:8]
        cmd = (r.command or "?")[:30]
        outc = (r.outcome or "ok")[:14]
        dur = f"{r.duration_ms or 0}ms"
        mdl = (r.model or "")[:18]
        args = (r.args or "")[:60].replace("\n", " ")
        lines.append(f"{ts} {kind:8} {cmd:30} {outc:14} {dur:>7} {mdl:18} {args}")
    blob = "\n".join(lines)
    sys_msg = (
        "You read an event log from a CLI tool called org-llm and "
        "surface ACTIONABLE observations the user would benefit from. "
        "Output STRICTLY in this format (no preamble, no markdown):\n\n"
        "  PATTERNS:\n"
        "    - <observation 1, 1 sentence>\n"
        "    - <observation 2>\n"
        "    - <observation 3>\n"
        "  SUGGESTIONS:\n"
        "    - <one concrete shell command or config change>\n"
        "    - <another>\n"
        "  HEADLINE: <one-line summary, < 80 chars>\n\n"
        "Examples of patterns worth surfacing: repeated failures of a "
        "specific verb, slow LLM model that has a fitting alternative, "
        "config keys flipped back and forth, expensive cloud calls in "
        "a tight loop, an indexing op never completed. Skip patterns "
        "that are just normal usage. Be honest if there's nothing notable."
    )
    user_msg = (
        f"Last {len(rows)} events from Captain's Log:\n\n{blob}\n\n"
        f"Reflect: what should the user know?"
    )
    # Bubble the actual error to the caller via an exception
    # (rather than the previous catch-all-return-"" pattern, which
    # gave the user a generic 'model unreachable?' red alert with
    # no diagnostic — Phase 11 Day 7).
    from .llm import chat as _chat
    return _chat(user_msg, model=model, base_url=base_url,
                   system=sys_msg, timeout=60.0)


@app.command(name="man", rich_help_panel="Maintenance")
def man(
    install: Annotated[bool, typer.Option("--install", "-i",
              help="Write the man page to ~/.local/share/man/man1/ "
                   "and print MANPATH setup hint if needed")] = False,
    show:    Annotated[bool, typer.Option("--show", "-s",
              help="Render the man page to stdout (pipe to `man -l -` "
                   "to view, or to `groff -man -Tutf8` to format)")] = False,
    output:  Annotated[str,  typer.Option("--output", "-o",
              help="Write to a custom path instead of the default")] = "",
):
    """Generate the org-llm man page.

    The man page is derived live from the registered Typer commands +
    their docstrings — same source `--help` reads from — so it stays
    in parity with the rest of the docs without a build step.

    Default (no flags): prints the install path + opens the man page
    via `man org-llm` if it's already installed, else writes-and-opens.

    [bold]--install[/bold] writes to $XDG_DATA_HOME/man/man1/org-llm.1
    (default ~/.local/share/man/man1/org-llm.1) and prints the right
    shell rc snippet if MANPATH doesn't already cover that location.
    """
    from . import manpage as _mp
    if show:
        print(_mp.render_manpage())
        return
    if output:
        target = Path(output).expanduser()
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(_mp.render_manpage())
        hail(f"Wrote man page: {target}")
        on_screen(f"[dim]View:[/dim]  [bold]man -l {target}[/bold]")
        return
    if install:
        target, on_path = _mp.install_manpage()
        hail(f"Installed: {target}")
        if on_path:
            on_screen("[lcars3]MANPATH already covers this location.[/lcars3]")
            on_screen(f"[dim]Try:[/dim] [bold]man org-llm[/bold]")
        else:
            on_screen("[yellow]MANPATH does NOT include the install dir.[/yellow]")
            for line in _mp.manpath_setup_hint(target.parent.parent.parent).splitlines():
                on_screen(f"  {line}")
            on_screen(f"[dim]Or open the file directly:[/dim] "
                      f"[bold]man -l {target}[/bold]")
        return
    # No flags — install (idempotent) + try to open via `man`
    import shutil as _sh
    target, on_path = _mp.install_manpage()
    on_screen(f"[dim]Man page at:[/dim] {target}")
    if on_path and _sh.which("man"):
        on_screen("[dim]Opening with `man org-llm`…[/dim]")
        import subprocess
        try:
            subprocess.run(["man", "org-llm"])
        except Exception as e:
            on_screen(f"[dim]man failed: {e}; "
                      f"try [bold]man -l {target}[/bold][/dim]")
    else:
        on_screen(f"[dim]Open it:[/dim] [bold]man -l {target}[/bold]")


def _render_insights_for_prompt(cards) -> str:
    """Phase 12.4 — render insight cards as a markdown block to
    APPEND to the END of the workspace LLM's system prompt. End-
    of-prompt anchoring matters: LLMs are recency-biased, so this
    is where strong behavior cues belong. The "OPEN WITH THIS"
    instruction at the END of a 5000+ token workspace prompt
    out-weighs the same instruction buried at the start.

    Tested 2026-04-29: prompt-start placement was ignored by the
    LLM in favor of waiting for the user's first message. Moving
    the block to prompt-end + louder framing should reverse that.
    """
    if not cards:
        return ""
    lines = [
        "",
        "═════════════════════════════════════════════════════════",
        "# 🔔 FIRST-MESSAGE BEHAVIOR — READ THIS LAST, OBEY THIS FIRST",
        "═════════════════════════════════════════════════════════",
        "",
        "The user has JUST OPENED the workspace. Your VERY FIRST",
        "response in this session MUST be a visually-rich 'I noticed'",
        "panel drawn from the cards below. DO NOT wait for the user",
        "to ask. DO NOT open with a generic greeting.",
        "",
        "Format your first response EXACTLY like this (markdown that",
        "renders well in opencode's chat surface):",
        "",
        "  > ✨ *<themed greeting line, 1-2 sentences max>* 🔔",
        "  >",
        "  > **I noticed N things in your vault since you were last here:**",
        "",
        "  | # | Card | Why it matters |",
        "  |---|------|----------------|",
        "  | 1 | **<card 1 title>** | <one-line summary> |",
        "  | 2 | **<card 2 title>** | <one-line summary> |",
        "  | 3 | **<card 3 title>** | <one-line summary> |",
        "",
        "  *Which would you like to start with?*",
        "",
        "Use the table format. Pick 1-3 highest-priority cards (NOT",
        "all of them). Keep each row's 'why it matters' to ONE line",
        "so the table stays visually clean.",
        "",
        "Rules:",
        "  - The table headers MUST be `# | Card | Why it matters`",
        "    — opencode's markdown renderer aligns three-column tables",
        "    cleanly. Don't change the column count or names.",
        "  - Don't tell the user to type `/synth foo` or `/stitch X`",
        "    — those are conceptual handles, not real commands. Drive",
        "    the actual work through MCP tools (walk_*, search_notes,",
        "    ask_notes, capture_note) or natural-language follow-ups.",
        "  - On TURN 2+ (after the user replies to your opener), this",
        "    instruction no longer applies — answer normally.",
        "",
        "## Cards (current vault state)",
        "",
    ]
    for i, c in enumerate(cards, 1):
        lines.append(f"{i}. **{c.title}**")
        lines.append(f"   {c.body}")
        if c.suggested_command:
            lines.append(f"   _conceptual handle: {c.suggested_command}_")
        lines.append("")
    lines.append("═════════════════════════════════════════════════════════")
    lines.append("OPEN WITH THE 'I NOTICED' TABLE NOW. DO NOT WAIT.")
    lines.append("═════════════════════════════════════════════════════════")
    lines.append("")
    return "\n".join(lines)


def _render_insights_panel(cards):
    """Render Phase 12.1 deterministic insight cards as a Rich panel
    that prints during `org-llm launch`. The actual workspace-side
    welcome-message injection (Phase 12.4) is separate; this is the
    user-facing CLI preview of what the LLM will open with.
    """
    from rich.panel import Panel as _P
    from rich.table import Table as _T
    from rich.text  import Text  as _Text
    if not cards:
        return _P(_Text("(no attention-worthy insights right now)",
                          style="dim"),
                    title="[lcars1]Things I noticed[/lcars1]",
                    border_style="lcars2", padding=(1, 2))
    body = _T.grid(padding=(0, 1))
    body.add_column(width=3, style="lcars1", no_wrap=True)
    body.add_column(overflow="fold")
    for i, c in enumerate(cards, 1):
        title_line = _Text()
        title_line.append(c.title, style="bold lcars2")
        if c.suggested_command:
            title_line.append(f"   → {c.suggested_command}",
                                style="dim lcars3")
        body.add_row(f"{i}.", title_line)
        # body sits one row below the numbered title for readability
        body.add_row("", _Text(c.body, style="dim"))
        body.add_row("", _Text(""))
    return _P(body,
                title=f"[lcars1]Things I noticed[/lcars1]  "
                        f"[dim]({len(cards)} card"
                        f"{'s' if len(cards) != 1 else ''})[/dim]",
                border_style="lcars2", padding=(1, 2))


def _vitals_panel(readings, overall: str):
    """Shared renderer used by `life-support` AND `doctor` (Dr. Crusher)
    so both surfaces show vitals identically. Lives at module scope so
    callers don't have to redefine it.
    """
    from rich.panel import Panel as _P
    from rich.table import Table as _T
    t = _T(box=None, pad_edge=False, show_header=True)
    t.add_column("✓", width=2)
    t.add_column("System",  style="lcars1", no_wrap=True, width=14)
    t.add_column("Reading", style="lcars3", no_wrap=True, width=24)
    t.add_column("Status",  style="lcars2", no_wrap=True, width=10)
    t.add_column("Message", style="dim",    overflow="fold")
    glyph = {"nominal": "[green]✓[/green]",
              "watch":   "[yellow]•[/yellow]",
              "alert":   "[orange1]⚠[/orange1]",
              "critical":"[red]✗[/red]"}
    for r in readings:
        t.add_row(glyph.get(r.status, "?"),
                   r.name, r.label, r.status, r.message)
    title_color = {"nominal": "lcars3", "watch": "lcars2",
                    "alert":   "warn",   "critical":"error"}.get(overall, "lcars1")
    return _P(t,
               title=f"[{title_color}]life-support  · {overall}[/{title_color}]",
               border_style="lcars2", padding=(1, 2))


@app.command(name="life-support", rich_help_panel="Self-care")
def life_support(
    interval: Annotated[int, typer.Option("--interval", "-n",
              help="Poll every N seconds with a live-redrawing panel. "
                   "0 = single shot (default).")] = 0,
    once:     Annotated[bool, typer.Option("--once", "-o",
              help="Single-shot probe + exit (same as default; "
                   "explicit for scripts).")] = False,
    no_log:   Annotated[bool, typer.Option("--no-log",
              help="Don't write the readings to the sensor_log table. "
                   "Useful for read-only checks.")] = False,
    analyze:  Annotated[bool, typer.Option("--analyze", "-a",
              help="After the probe, ask the LLM for concrete model + "
                   "config optimisations based on the recent sensor_log "
                   "trend. Subject to a sample-size floor — when there "
                   "isn't enough history yet, falls back to a "
                   "deterministic listing.")] = False,
    window:   Annotated[int, typer.Option("--window", "-w",
              help="With --analyze: minutes of sensor_log history to "
                   "feed the model. Defaults to 60.")] = 60,
    json_:    Annotated[bool, typer.Option("--json",
              help="Emit a JSON snapshot instead of the rendered panel "
                   "(for scripted consumers / dashboards).")] = False,
):
    """Trek-themed host-system status — battery, CPU, RAM, disk,
    thermals, network, Ollama daemon, auto-embedder.

    Self-hosted means the laptop is the substrate. When battery
    drops, RAM tightens, thermals spike, or Ollama wedges, those are
    the failure modes that turn this tool from helpful to frustrating.
    Life-support shows the vital systems at a glance.

    Single-shot by default. Pass [bold]--interval N[/bold] for a live
    polling panel that redraws every N seconds (Ctrl-C to exit). Pass
    [bold]--analyze[/bold] to also call the chat model for concrete
    optimisation suggestions grounded in your recent timeseries.

    Every reading writes one row to the [bold]sensor_log[/bold]
    timeseries table (unless [bold]--no-log[/bold]). dbt analytics +
    the LLM advice path read from there.
    """
    from . import life_support as _ls
    if json_:
        import json as _json
        readings = _ls.probe_all()
        if not no_log:
            _ls.record_readings(readings)
        out = {
            "ts":      int(time.time()),
            "overall": _ls.overall_status(readings),
            "probes":  [{
                "name":       r.name,
                "value":      r.value,
                "normalized": r.normalized,
                "label":      r.label,
                "status":     r.status,
                "message":    r.message,
            } for r in readings],
        }
        print(_json.dumps(out, indent=2))
        return

    from rich.live import Live
    from rich.panel import Panel as _P
    from rich.table import Table as _T

    def _render(readings, overall):
        return _vitals_panel(readings, overall)

    if interval > 0:
        try:
            with Live(_render(_ls.probe_all(), "nominal"),
                       console=console, refresh_per_second=2,
                       transient=False) as live:
                while True:
                    readings = _ls.probe_all()
                    overall  = _ls.overall_status(readings)
                    if not no_log:
                        _ls.record_readings(readings)
                    live.update(_render(readings, overall))
                    time.sleep(max(1, interval))
        except KeyboardInterrupt:
            console.print()
            on_screen("[dim]life-support polling halted by user.[/dim]")
            return

    # single-shot
    readings = _ls.probe_all()
    overall  = _ls.overall_status(readings)
    if not no_log:
        n = _ls.record_readings(readings)
        if n:
            on_screen(f"[dim]Logged {n} reading(s) to sensor_log.[/dim]")
    console.print()
    console.print(_render(readings, overall))

    if analyze:
        on_screen("")
        with thinking("Analysing trend"):
            advice = _ls.llm_optimization_advice(window_secs=window * 60)
        if advice:
            console.print(_P(
                advice,
                title=f"[lcars1]Optimization advice  · last {window} min[/lcars1]",
                border_style="lcars2", padding=(1, 2),
            ))
        else:
            on_screen("[dim]Nothing to advise on yet — keep "
                       "[bold]life-support --interval 30[/bold] running "
                       "for a few minutes to build a trend.[/dim]")


@app.command(name="sensors", rich_help_panel="Self-care")
def sensors_dashboard(
    interval: Annotated[int, typer.Option("--interval", "-n",
              help="Refresh seconds (default 3)")] = 3,
    drill:    Annotated[str, typer.Option("--drill", "-d",
              help="Open the dashboard zoomed into ONE probe (battery / "
                   "cpu / memory / disk / thermal / network / ollama / "
                   "auto_embedder). Default: overview screen.")] = "",
    window:   Annotated[int, typer.Option("--window", "-w",
              help="Minutes of sensor_log history to chart in drill-down "
                   "view")] = 30,
    no_log:   Annotated[bool, typer.Option("--no-log",
              help="Read-only — don't append fresh readings to sensor_log")] = False,
):
    """Live LCARS resource-monitor + log dashboard. TUI with drill-in.

    Two views:

    [bold]Overview[/bold] — every probe's current reading + a sparkline
    of the last `--window` minutes from sensor_log. Use [1]–[8] number
    keys (or pass [bold]--drill <probe>[/bold]) to zoom into a single
    probe with its full timeseries, status distribution, and the
    activity correlations recorded for it.

    [bold]Drill-in[/bold] — full timeseries chart, min/max/mean,
    status histogram, and the user-activity context recorded at each
    alert/critical reading. Press [esc] / [q] / Ctrl-C to return to
    overview (or just exit if invoked with --drill).

    Every refresh writes one new sensor_log row per probe so the
    timeseries grows while you watch. Pass [bold]--no-log[/bold] for
    a read-only inspection.
    """
    from . import life_support as _ls
    from rich.live import Live
    from rich.panel import Panel as _P
    from rich.table import Table as _T
    from rich.layout import Layout as _Layout
    from rich.text import Text as _Text

    # Build a tiny inline sparkline from a series of normalized values.
    # Eight glyphs from low to high; flat input renders as a row of
    # mid-height blocks so the user sees "stable" not "missing".
    _SPARK = "▁▂▃▄▅▆▇█"

    def _sparkline(values: list[float], width: int = 24) -> str:
        if not values:
            return "[dim]" + "·" * width + "[/dim]"
        sub = values[-width:] if len(values) > width else values
        # Pad short series on the LEFT so the freshest reading is on
        # the right edge.
        pad = max(0, width - len(sub))
        out = " " * pad
        for v in sub:
            try:
                f = max(0.0, min(1.0, float(v)))
            except Exception:
                f = 0.5
            idx = int(f * (len(_SPARK) - 1))
            out += _SPARK[idx]
        return out

    def _status_color(status: str) -> str:
        return {"nominal": "lcars3", "watch": "lcars2",
                 "alert": "warn", "critical": "error"}.get(status, "lcars1")

    def _overview_panel():
        readings = _ls.probe_all()
        if not no_log:
            _ls.record_readings(readings)
        recent = _ls.recent_readings(since_secs=window * 60, limit=2000)
        by_probe: dict[str, list[float]] = {}
        for v in recent:
            try:
                by_probe.setdefault(v["probe"], []).insert(
                    0, float(v["normalized"] or 0))
            except Exception:
                pass
        t = _T(box=None, pad_edge=False, show_header=True)
        t.add_column("✓",       width=2)
        t.add_column("System",  style="lcars1", no_wrap=True, width=14)
        t.add_column("Reading", style="lcars3", no_wrap=True, width=22)
        t.add_column("Status",  style="lcars2", no_wrap=True, width=10)
        t.add_column(f"Trend · {window}min", style="lcars3",
                       no_wrap=True, width=26)
        t.add_column("Message", style="dim",    overflow="fold")
        glyph = {"nominal": "[green]✓[/green]",
                  "watch":   "[yellow]•[/yellow]",
                  "alert":   "[orange1]⚠[/orange1]",
                  "critical":"[red]✗[/red]"}
        for r in readings:
            spark = _sparkline(by_probe.get(r.name, []))
            t.add_row(glyph.get(r.status, "?"), r.name, r.label,
                        f"[{_status_color(r.status)}]{r.status}"
                        f"[/{_status_color(r.status)}]",
                        spark, r.message)
        overall = _ls.overall_status(readings)
        return _P(
            t,
            title=(f"[{_status_color(overall)}]sensors  · {overall}  · "
                    f"refresh every {interval}s · drill: --drill <name>"
                    f"[/{_status_color(overall)}]"),
            subtitle="[dim]Ctrl-C to exit · pass --drill battery / cpu / mem / disk / thermal / network / ollama / auto_embedder[/dim]",
            border_style="lcars2", padding=(1, 2),
        )

    def _drill_panel(probe: str):
        # Validate name; tolerate "mem"/"memory" ambiguity.
        canon = {"battery", "cpu", "memory", "disk", "thermal",
                  "network", "ollama", "auto_embedder"}
        alias = {"mem": "memory", "ram": "memory",
                  "net": "network", "embed": "auto_embedder",
                  "watcher": "auto_embedder", "temp": "thermal"}
        name = alias.get(probe.lower(), probe.lower())
        if name not in canon:
            return _P(
                _Text(f"unknown probe: {probe!r}\nvalid: {', '.join(sorted(canon))}",
                      style="error"),
                title="[error]sensors --drill[/error]",
                border_style="error", padding=(1, 2),
            )

        # Fresh probe + record so this view drives logging too.
        readings = _ls.probe_all()
        if not no_log:
            _ls.record_readings(readings)
        live_for = next((r for r in readings if r.name == name), None)
        recent = _ls.recent_readings(probe=name, since_secs=window * 60,
                                        limit=2000)
        norms: list[float] = []
        statuses: dict[str, int] = {}
        for v in reversed(recent):    # oldest → newest for chart
            try:
                norms.append(float(v["normalized"] or 0))
            except Exception:
                pass
            statuses[v["status"]] = statuses.get(v["status"], 0) + 1

        # Top section: live reading + summary stats
        head = _T.grid(padding=(0, 2))
        head.add_column(); head.add_column()
        if live_for:
            head.add_row("[lcars1]Now[/lcars1]",
                          f"{live_for.label}  [{live_for.status}]  {live_for.message}")
        if norms:
            head.add_row("[lcars1]Window[/lcars1]",
                          f"min {min(norms):.2f}  mean {sum(norms)/len(norms):.2f}  "
                          f"max {max(norms):.2f}  · {len(norms)} sample(s) "
                          f"over last {window}min")
        if statuses:
            ds = " ".join(f"[{_status_color(k)}]{k}[/{_status_color(k)}]={v}"
                            for k, v in statuses.items())
            head.add_row("[lcars1]Status[/lcars1]", ds)

        # Sparkline at full width (~60 chars)
        spark = _sparkline(norms, width=60)
        chart_box = _P(_Text(spark, style="lcars3"),
                         title="[lcars1]trend (oldest left → newest right)[/lcars1]",
                         border_style="lcars2", padding=(0, 2))

        # Activity correlations table — alert/critical rows + their context
        corr = _T(box=None, pad_edge=False, show_header=True)
        corr.add_column("When",    style="dim", no_wrap=True, width=19)
        corr.add_column("Status",  style="lcars2", no_wrap=True, width=10)
        corr.add_column("Reading", style="lcars3", no_wrap=True, width=20)
        corr.add_column("Activity context", style="lcars1", overflow="fold")
        from datetime import datetime as _dt
        for v in recent:
            if v.get("status") not in ("alert", "critical"):
                continue
            ts = _dt.fromtimestamp(v["ts"]).strftime("%Y-%m-%d %H:%M:%S")
            ctx = (v.get("context") or "").strip() or "[dim](no activity recorded)[/dim]"
            corr.add_row(ts,
                          f"[{_status_color(v['status'])}]{v['status']}"
                          f"[/{_status_color(v['status'])}]",
                          v.get("label") or "?", ctx)
            if corr.row_count >= 12:
                break
        corr_box = _P(corr if corr.row_count else
                        _Text("No alert/critical readings in this window — "
                              "everything's been fine.", style="lcars3"),
                        title="[lcars1]activity correlations  · what the user was doing during alerts[/lcars1]",
                        border_style="lcars2", padding=(1, 2))

        # Drill renders three stacked panels — NOT a Layout (which
        # would stretch the last panel to full terminal height) and
        # NOT a Live loop (drill is a one-shot deep dive; the
        # overview is the live view).
        return [
            _P(head, title=f"[lcars1]sensors  · drill: {name}[/lcars1]",
                 border_style="lcars1", padding=(1, 2)),
            chart_box,
            corr_box,
        ]

    # Drill = one-shot stacked panels. Overview = live-refreshing dashboard.
    if drill:
        result = _drill_panel(drill)
        if isinstance(result, list):
            for panel in result:
                console.print(panel)
        else:                       # error panel from invalid name
            console.print(result)
        return
    try:
        with Live(_overview_panel(), console=console,
                    refresh_per_second=2, transient=False) as live:
            while True:
                time.sleep(max(1, interval))
                live.update(_overview_panel())
    except KeyboardInterrupt:
        console.print()
        on_screen("[dim]sensors dashboard exited.[/dim]")


@app.command(name="log", rich_help_panel="Maintenance")
def log_show(
    kind:    Annotated[str, typer.Option("--kind", "-k",
              help="Filter by event kind: cli|llm|mcp|config|doctor|dbt")] = "",
    grep:    Annotated[str, typer.Option("--grep", "-g",
              help="Substring filter on command/args/response")] = "",
    limit:   Annotated[int, typer.Option("--limit", "-n",
              help="Max rows to display")] = 50,
    tangle:  Annotated[bool, typer.Option("--tangle", "-t",
              help="Tangle Captain's Log to plaintext mirrors and exit")] = False,
    path:    Annotated[bool, typer.Option("--path", "-p",
              help="Print Captain's Log path and exit")] = False,
    reflect: Annotated[bool, typer.Option("--reflect", "-R",
              help="LLM reflects on recent log: surfaces patterns + suggestions")] = False,
    export:  Annotated[str, typer.Option("--export", "-e",
              help="Append matching rows to this org file (any path; respects --kind/--grep/--limit)")] = "",
):
    """Captain's Log — CLI invocations, LLM calls, MCP tools, config changes.

    Every notable event is written to BOTH the SQLite `history` table AND
    ~/org/captains-log.org so dbt analytics + the user's vault have
    parity. Stardate optional.

    [bold]--reflect[/bold] hands the recent window to the chat model
    for pattern-spotting + concrete suggestions (e.g. "you've called
    `embed` 5 times this hour with errors — Ollama may be down").
    """
    from . import logbook as _lb
    from .db import History
    from rich.panel import Panel
    from rich.table import Table

    p = _lb.org_log_path()
    if path:
        on_screen(str(p))
        return
    if tangle:
        # `org-babel-tangle` via emacsclient produces the per-kind .log
        # mirrors. We don't shell out to emacs ourselves; surface the
        # canonical command + path so the user can wire it to a script.
        on_screen(f"[lcars1]Captain's Log:[/lcars1]    {p}")
        on_screen(f"[lcars1]Tangle target:[/lcars1]    {_lb.tangle_dir()}/<kind>.log")
        on_screen("[dim]From emacs:[/dim]  "
                  f"[bold]C-c C-v t[/bold] in {p.name}")
        on_screen("[dim]Shell:[/dim]       "
                  f"[bold]emacsclient -e \"(progn (find-file \\\"{p}\\\") "
                  "(org-babel-tangle))\"[/bold]")
        return

    # Validate --kind upfront. Otherwise a typo silently returns
    # "no entries matching that filter" — looks like the log is empty
    # when really the kind is wrong.
    valid_kinds = {"cli", "llm", "mcp", "config", "doctor", "dbt", "embed"}
    if kind and kind not in valid_kinds:
        red_alert(f"Unknown log kind '{kind}'. Valid: "
                   f"{', '.join(sorted(valid_kinds))}.")
        raise typer.Exit(1)
    # Negative limit silently returned every row (SQLAlchemy ignored
    # it); zero returned nothing. Both surprise the user — guard them.
    if limit <= 0:
        red_alert(f"--limit must be positive (got {limit}).")
        raise typer.Exit(1)

    engine = _engine()
    with get_session(engine) as session:
        q = session.query(History).order_by(History.id.desc())
        if kind:
            q = q.filter(History.kind == kind)
        rows = q.limit(limit * 4 if grep else limit).all()  # over-fetch for grep
    if grep:
        gl = grep.lower()
        rows = [r for r in rows
                if gl in (r.command or "").lower()
                or gl in (r.query   or "").lower()
                or gl in (r.response or "").lower()][:limit]

    if export:
        from . import logbook as _lb
        dest = Path(export).expanduser()
        filt_parts = []
        if kind:  filt_parts.append(f"kind={kind}")
        if grep:  filt_parts.append(f"grep={grep}")
        filt_parts.append(f"limit={limit}")
        n = _lb.export_rows_to_org(rows, dest,
                                     source_filter=", ".join(filt_parts))
        if n == 0:
            red_alert(f"Nothing exported. (rows matched: {len(rows)}; "
                      f"target: {dest})")
            raise typer.Exit(1)
        on_screen(f"[lcars3]✓[/lcars3] Exported [bold]{n}[/bold] event(s) "
                  f"→ [bold]{dest}[/bold]")
        if filt_parts and (kind or grep):
            on_screen(f"  [dim]Filter:[/dim] {', '.join(filt_parts)}")
        # Log the export itself so it appears in future Captain's Log
        # queries — symmetric with --reflect.
        _lb.write_event("cli", "log-export",
                          args=f"dest={dest} {' '.join(filt_parts)}",
                          response=f"exported {n} rows", outcome="ok")
        return

    if reflect:
        from rich.panel import Panel
        with get_session(engine) as session:
            url = _ollama_url(session)
            mdl = (_cfg(session, "chat_model")
                   or _cfg(session, "fast_model") or "llama3.2")
        if not rows:
            on_screen("[dim]Nothing to reflect on yet.[/dim]")
            return
        # Below this many events the LLM doesn't have enough signal to
        # detect real patterns and confabulates ("repeated failure of
        # X" when X happened once, etc.). Fall back to a clean
        # deterministic listing instead. Same lesson as
        # cloud --refresh-catalog: small models on sparse input invent
        # narrative.
        _MIN_REFLECT_EVENTS = 8
        if len(rows) < _MIN_REFLECT_EVENTS:
            from rich.table import Table as _T
            t = _T(box=None, pad_edge=False)
            t.add_column("When",     style="dim", no_wrap=True)
            t.add_column("Kind",     style="lcars3")
            t.add_column("Command",  style="lcars2")
            t.add_column("Outcome",  style="dim")
            t.add_column("Duration", style="lcars1", justify="right")
            for r in rows:
                t.add_row(
                    (r.timestamp or "")[:19],
                    (r.kind or "?")[:8],
                    (r.command or "?")[:30],
                    (r.outcome or "ok")[:14],
                    f"{r.duration_ms or 0}ms",
                )
            console.print()
            console.print(Panel(t,
                                  title=f"[lcars1]Captain's Log — recent {len(rows)} "
                                          f"event(s)[/lcars1]  [dim](too few "
                                          f"to reflect — listing instead)[/dim]",
                                  border_style="lcars2", padding=(1, 2)))
            on_screen("[dim]Need[/dim] "
                       f"[bold]≥{_MIN_REFLECT_EVENTS}[/bold] [dim]events for "
                       "LLM reflection. Use [/dim][bold]--limit[/bold]"
                       "[dim] to widen the window or wait for activity to "
                       "accumulate.[/dim]")
            return
        # Auto-fallback: log --reflect is a structured-format task
        # that doesn't need the full chat model, so on CPU-only
        # hardware where chat_model can't fit the 60s timeout, drop
        # to fast_model on first ReadTimeout. Phase 11 Day 7
        # surfaced this — user had llama3.2 (3B) as chat_model and
        # llama3.2:1b as fast_model; chat_model always timed out.
        with get_session(engine) as session:
            fast_mdl = _cfg(session, "fast_model") or ""
        try:
            with warp(f"LLM reflecting on {len(rows)} event(s) with {mdl}…"):
                reflection = _captains_log_reflect(rows, mdl, url)
        except Exception as e:
            err_class = type(e).__name__
            timeoutish = ("Timeout" in err_class
                            or "timed out" in str(e).lower())
            if timeoutish and fast_mdl and fast_mdl != mdl:
                on_screen(f"[dim]chat_model[/dim] [bold]{mdl}[/bold] "
                           f"[dim]timed out — retrying with[/dim] "
                           f"[bold]{fast_mdl}[/bold]")
                try:
                    with warp(f"LLM reflecting (fallback) "
                                 f"with {fast_mdl}…"):
                        reflection = _captains_log_reflect(
                            rows, fast_mdl, url)
                    mdl = fast_mdl                       # for logging below
                except Exception as e2:
                    red_alert(f"LLM reflection failed (after fallback): "
                               f"{type(e2).__name__}: {e2}")
                    on_screen(f"[dim]Tried[/dim] [bold]{mdl}[/bold] "
                               f"[dim]then[/dim] [bold]{fast_mdl}[/bold]")
                    raise typer.Exit(1)
            else:
                red_alert(f"LLM reflection failed: {err_class}: {e}")
                on_screen(f"[dim]Model:[/dim] [bold]{mdl}[/bold]  "
                           f"[dim]Endpoint:[/dim] {url}")
                on_screen(f"[dim]Try:[/dim] "
                           f"[bold]ollama pull {mdl}[/bold]  "
                           f"[dim]or[/dim] "
                           f"[bold]org-llm config chat_model llama3.2:1b[/bold]")
                raise typer.Exit(1)
        if not reflection:
            red_alert(f"LLM reflection returned empty response from "
                       f"[bold]{mdl}[/bold].")
            on_screen("[dim]Try a different chat_model:[/dim] "
                       "[bold]org-llm config chat_model llama3.2:1b[/bold]")
            raise typer.Exit(1)
        console.print()
        console.print(Panel(reflection,
                              title="[lcars1]Captain's Log — reflection[/lcars1]  "
                                    f"[dim](window: {len(rows)} events)[/dim]",
                              border_style="lcars2", padding=(1, 2)))
        # Log the reflection itself so dbt sees it as a doctor event.
        from . import logbook as _lb
        _lb.write_event("doctor", "log-reflect",
                          args=f"window={len(rows)}",
                          model=mdl, response=reflection, outcome="ok")
        return

    if not rows:
        on_screen("[dim]Captain's Log shows no entries matching that filter.[/dim]")
        on_screen(f"[dim]Org file:[/dim] {p}  "
                  f"[dim](may not exist yet — run any command to seed it)[/dim]")
        return

    tbl = Table(box=None, pad_edge=False)
    tbl.add_column("When",     style="lcars1", no_wrap=True, width=19)
    tbl.add_column("Kind",     style="lcars3", width=8)
    tbl.add_column("Command",  style="lcars2")
    tbl.add_column("Outcome",  width=8)
    tbl.add_column("Duration", style="dim", width=8, justify="right")
    for r in rows:
        oc = r.outcome or ""
        oc_style = "[green]" if oc == "ok" else (
            "[red]" if oc.startswith("error") or oc.startswith("crash")
            else "[yellow]")
        dur = f"{r.duration_ms}ms" if r.duration_ms is not None else ""
        tbl.add_row(r.timestamp[:19] if r.timestamp else "?",
                     r.kind or "?",
                     r.command or "?",
                     f"{oc_style}{oc}[/{oc_style[1:-1]}]" if oc else "",
                     dur)
    console.print()
    console.print(Panel(tbl,
                          title=f"[lcars1]Captain's Log[/lcars1]  "
                                f"[dim]({len(rows)} of last {limit})[/dim]",
                          border_style="lcars2", padding=(1, 1)))
    console.print()
    on_screen(f"[dim]Org file:[/dim] {p}  "
              f"[dim]·[/dim] [bold]org-llm log -t[/bold] for tangle instructions"
              f"  [dim]·[/dim] [bold]org-llm dbt build[/bold] for analytics views")


@app.command(name="db", rich_help_panel="Maintenance")
def db_info(
    schema: Annotated[bool, typer.Option("--schema", "-s", help="Show CREATE TABLE statements")] = False,
    dict_:  Annotated[bool, typer.Option("--dict",   "-d", help="Print full data dictionary")] = False,
    query:  Annotated[str,  typer.Option("--query", "-q", help="Run a raw SQL SELECT")] = "",
    vacuum: Annotated[bool, typer.Option("--vacuum", "-V",
              help="Compact the SQLite DB on disk (reclaims space "
                   "after large deletes / re-indexes)")] = False,
):
    """Inspect the SQLite database: row counts, schema, data dictionary, raw SQL, or vacuum."""
    from rich.panel  import Panel
    from rich.syntax import Syntax
    from sqlalchemy  import inspect, text

    engine = _engine()

    # ── vacuum: reclaim disk space ──────────────────────────────────────────
    if vacuum:
        path = Path(os.environ.get("ORG_LLM_DB") or str(DB_PATH))
        before = path.stat().st_size if path.exists() else 0
        with engine.begin() as conn:
            # SQLite VACUUM rebuilds the file from scratch — reclaims any
            # pages freed by deletes / drops / re-indexes. Locks the DB for
            # the duration; tolerate the brief blocking on a single-user box.
            conn.execute(text("VACUUM"))
        after = path.stat().st_size if path.exists() else 0
        delta = before - after
        hail(f"Vacuumed: {before/1024/1024:.1f} MB → "
             f"{after/1024/1024:.1f} MB "
             f"({'-' if delta >= 0 else '+'}"
             f"{abs(delta)/1024/1024:.1f} MB)")
        make_it_so()
        return

    # ── tutor data dictionary ─────────────────────────────────────────────────
    if dict_:
        from .ui import trans_stripe
        console.rule("[lcars1]org-llm Data Dictionary[/lcars1]")
        console.print()
        console.print(trans_stripe(52))
        # Re-use the db tutor step body
        match = next(((n, b) for n, b in _TUTOR_STEPS if n == "db"), None)
        if match:
            from rich.panel import Panel as P
            console.print(P(match[1], title="[lcars1]db[/lcars1]", border_style="lcars2",
                            padding=(1, 2)))
        return

    # ── raw SQL query ─────────────────────────────────────────────────────────
    if query:
        head = query.lstrip().upper()
        if not head:
            red_alert("Empty query.")
            raise typer.Exit(1)
        # Read-only allow-list: SELECT, WITH (CTEs), EXPLAIN, PRAGMA TABLE_*
        allowed = ("SELECT", "WITH ", "EXPLAIN ", "PRAGMA TABLE_INFO", "PRAGMA TABLE_LIST")
        if not any(head.startswith(prefix) for prefix in allowed):
            red_alert("Only read-only queries are allowed (SELECT / WITH / EXPLAIN / PRAGMA TABLE_INFO).")
            raise typer.Exit(1)
        with engine.connect() as conn:
            try:
                rows = list(conn.execute(text(query)))
                if not rows:
                    on_screen("(no rows)")
                    return
                tbl = Table(box=None, pad_edge=False)
                for col in rows[0]._fields:
                    tbl.add_column(col, style="lcars2")
                for row in rows[:200]:
                    tbl.add_row(*[str(v) for v in row])
                console.print(tbl)
                if len(rows) > 200:
                    on_screen(f"(showing 200 of {len(rows)} rows)")
            except Exception as exc:
                red_alert(f"Query failed: {exc}")
                raise typer.Exit(1)
        return

    # ── CREATE TABLE schema ───────────────────────────────────────────────────
    if schema:
        console.rule("[lcars1]Schema[/lcars1]")
        with engine.connect() as conn:
            for row in conn.execute(text(
                "SELECT name, sql FROM sqlite_master "
                "WHERE type='table' AND sql IS NOT NULL ORDER BY name"
            )):
                console.print(f"\n[lcars1]{row.name}[/lcars1]")
                console.print(Syntax(row.sql, "sql", theme="monokai"))
        return

    # ── default: row counts + sample ─────────────────────────────────────────
    db_path = Path(os.environ.get("ORG_LLM_DB") or str(DB_PATH))
    console.rule("[lcars1]Database Overview[/lcars1]")
    hail(f"File: {db_path}")
    console.print()

    tables_meta = [
        ("files",   "One row per indexed .org file"),
        ("nodes",   "One row per org-mode heading (+ optional embedding)"),
        ("history", "LLM interaction log"),
        ("config",  "Key/value settings"),
    ]
    stats_tbl = Table(box=None, pad_edge=False)
    stats_tbl.add_column("Table",       style="lcars1")
    stats_tbl.add_column("Rows",        style="lcars2", justify="right")
    stats_tbl.add_column("Description", style="dim")

    with engine.connect() as conn:
        for tname, desc in tables_meta:
            try:
                count = conn.execute(text(f"SELECT COUNT(*) FROM {tname}")).scalar()
            except Exception:
                count = "?"
            stats_tbl.add_row(tname, str(count), desc)
        # also show dbt views if present
        views = [r[0] for r in conn.execute(text(
            "SELECT name FROM sqlite_master WHERE type='view' ORDER BY name"
        ))]
        if views:
            stats_tbl.add_row("", "", "")
            for v in views:
                try:
                    count = conn.execute(text(f"SELECT COUNT(*) FROM {v}")).scalar()
                except Exception:
                    count = "?"
                stats_tbl.add_row(f"[dim]{v}[/dim]", str(count), "[dim]dbt view[/dim]")

    console.print(stats_tbl)
    console.print()
    on_screen("[dim]Tip:[/dim]  --schema  │  --dict  │  --query 'SELECT ...'")
    on_screen("         org-llm tutor db  — full data dictionary")


def _opencode_bin() -> Path | None:
    """Return path to opencode binary if it exists anywhere on PATH or known locations."""
    import shutil
    found = shutil.which("opencode")
    if found:
        return Path(found)
    for candidate in [
        Path("~/.opencode/bin/opencode").expanduser(),
        Path("~/.local/bin/opencode").expanduser(),
    ]:
        if candidate.exists():
            return candidate
    return None


def _opencode_log_dir() -> Path:
    """Where opencode writes per-launch log files (one per session)."""
    return Path("~/.local/share/opencode/log").expanduser()


def _latest_opencode_log(log_dir: Path) -> Path | None:
    """Newest *.log under log_dir, or None if the dir is empty/missing."""
    if not log_dir.is_dir():
        return None
    logs = [p for p in log_dir.glob("*.log") if p.is_file()]
    if not logs:
        return None
    return max(logs, key=lambda p: p.stat().st_mtime)


def _ollama_alive(url: str, timeout: float = 3.0) -> tuple[bool, str]:
    """Quick health check against Ollama. Returns (alive, reason).

    "Alive" requires both reachable AND at least one model listed —
    a running server with no models can't service generate requests.
    """
    import urllib.request, urllib.error, json
    try:
        with urllib.request.urlopen(
            f"{url.rstrip('/')}/api/tags", timeout=timeout,
        ) as r:
            data = json.loads(r.read())
        n = len(data.get("models") or [])
        if n == 0:
            return False, f"Ollama is reachable at {url} but reports no models"
        return True, f"Ollama OK ({n} model{'s' if n != 1 else ''} registered)"
    except urllib.error.URLError as e:
        reason = getattr(e, "reason", e)
        return False, f"Ollama unreachable at {url}: {reason}"
    except Exception as e:
        return False, f"Ollama health probe failed: {type(e).__name__}: {e}"


def _watch_opencode_for_stalls(
    log_dir: Path,
    ollama_url: str,
    stall_secs: float,
    stop_event,
    sentinel_path: Path,
    poll_secs: float = 5.0,
    startup_grace: float = 30.0,
) -> None:
    """Daemon-thread loop: watch opencode's log file mtime and flag a stall
    only when BOTH the log has been quiet ≥stall_secs AND Ollama is sick.

    Why both gates: a quiet log alone could just mean the user is reading
    the screen — TUIs don't redraw the on-disk log every keystroke. We
    only want to fire when there's an actual external cause (Ollama
    unreachable / no models) the user can act on.

    Writes a JSON one-shot diagnosis to sentinel_path on first detection,
    then keeps watching but won't double-notify until the log moves.
    """
    import time, json
    last_seen_mtime: float | None = None
    last_change_at = time.monotonic()
    notified = False
    log_file: Path | None = None

    deadline = time.monotonic() + startup_grace
    while not stop_event.is_set() and time.monotonic() < deadline:
        log_file = _latest_opencode_log(log_dir)
        if log_file:
            try:
                last_seen_mtime = log_file.stat().st_mtime
            except OSError:
                log_file = None
            else:
                last_change_at = time.monotonic()
                break
        if stop_event.wait(poll_secs):
            return
    if not log_file:
        return  # No log appeared during the grace window — give up silently.

    while not stop_event.is_set():
        if stop_event.wait(poll_secs):
            return
        # opencode may rotate logs across runs; keep our pointer fresh.
        latest = _latest_opencode_log(log_dir)
        if latest and latest != log_file:
            log_file = latest
            try:
                last_seen_mtime = log_file.stat().st_mtime
            except OSError:
                continue
            last_change_at = time.monotonic()
            notified = False
            continue
        try:
            cur_mtime = log_file.stat().st_mtime
        except OSError:
            continue
        if last_seen_mtime is None or cur_mtime > last_seen_mtime:
            last_seen_mtime = cur_mtime
            last_change_at = time.monotonic()
            notified = False
            continue
        idle = time.monotonic() - last_change_at
        if idle < stall_secs or notified:
            continue
        alive, reason = _ollama_alive(ollama_url)
        if alive:
            continue  # Quiet log + healthy Ollama = probably just reading.
        try:
            sentinel_path.parent.mkdir(parents=True, exist_ok=True)
            sentinel_path.write_text(json.dumps({
                "detected_at": time.time(),
                "idle_secs":   round(idle, 1),
                "log_file":    str(log_file),
                "ollama_url":  ollama_url,
                "ollama_alive": alive,
                "reason":      reason,
            }, indent=2))
            notified = True
        except OSError:
            # Sentinel write failed (full disk, permissions) — keep
            # watching; the user will at least see Ollama errors live.
            return


def _install_opencode_bin(bin_dir: Path) -> Path | None:
    """Download and install opencode using its official installer. Returns path or None."""
    import subprocess
    import os
    # The opencode installer always installs to ~/.opencode/bin regardless of env vars
    default_install = Path("~/.opencode/bin/opencode").expanduser()
    install_sh = bin_dir / "_opencode_install.sh"
    try:
        dl = subprocess.run(
            ["curl", "-fsSL", "-o", str(install_sh), "https://opencode.ai/install"],
            capture_output=True, text=True, timeout=30,
        )
        if dl.returncode != 0:
            red_alert(f"opencode download failed: {dl.stderr.strip()[:120]}")
            return None
        install_sh.chmod(0o755)
        run = subprocess.run(
            ["sh", str(install_sh)],
            capture_output=True, text=True,
            env={**os.environ},
        )
        install_sh.unlink(missing_ok=True)
        result = _opencode_bin()
        if result:
            hail(f"opencode installed at {result}")
            return result
        red_alert(f"opencode install failed: {run.stderr.strip()[:200]}")
        return None
    except Exception as exc:
        install_sh.unlink(missing_ok=True)
        red_alert(f"opencode install error: {exc}")
        return None


def _gh_bin() -> str | None:
    """Return path to gh CLI, or None if not available."""
    import shutil
    return shutil.which("gh") or (
        str(Path("~/.local/bin/gh").expanduser())
        if Path("~/.local/bin/gh").expanduser().exists() else None
    )


def _claude_bin() -> Path | None:
    """Return path to claude CLI if installed anywhere."""
    import shutil
    found = shutil.which("claude")
    if found:
        return Path(found)
    for candidate in [
        Path("~/.claude/bin/claude").expanduser(),
        Path("~/.local/bin/claude").expanduser(),
        Path("~/.npm-global/bin/claude").expanduser(),
        Path("~/.local/share/npm/bin/claude").expanduser(),
        Path("/usr/local/bin/claude"),
    ]:
        if candidate.exists():
            return candidate
    return None


def _install_claude_bin() -> Path | None:
    """Install claude CLI via npm. Returns path or None."""
    import subprocess, shutil
    npm = shutil.which("npm")
    if not npm:
        red_alert("npm not found — install Node.js to get Claude Code  (nodejs.org)")
        return None
    hail("Installing @anthropic-ai/claude-code via npm…")
    result = subprocess.run(
        [npm, "install", "-g", "@anthropic-ai/claude-code"],
        timeout=120,
    )
    if result.returncode != 0:
        red_alert("claude install failed — check npm output above")
        return None
    return _claude_bin()


def _install_gh(bin_dir: Path) -> Path | None:
    """Download and install gh CLI to bin_dir. Returns path or None on failure."""
    import platform
    import urllib.request
    import json

    arch = platform.machine().lower()
    arch_slug = "amd64" if arch in ("x86_64", "amd64") else "arm64"
    try:
        # Route through cloud._urlopen so distro-specific SSL CA
        # bundle paths apply (Guix lives under
        # ~/.guix-home/profile/etc/ssl/...). Bare urllib here used to
        # fail with CERTIFICATE_VERIFY_FAILED on Guix during install.
        from .cloud import _urlopen
        req = urllib.request.Request(
            "https://api.github.com/repos/cli/cli/releases/latest",
            headers={"User-Agent": "org-llm/install-tools"},
        )
        with _urlopen(req, timeout=10) as r:
            release = json.loads(r.read())
        version = release["tag_name"].lstrip("v")
        url = (
            f"https://github.com/cli/cli/releases/download/v{version}/"
            f"gh_{version}_linux_{arch_slug}.tar.gz"
        )
        tmp = Path("/tmp/gh.tar.gz")
        with warp("Downloading gh CLI"):
            # urlretrieve also uses bare urllib; route the GET via
            # _urlopen + write to disk ourselves so the SSL ctx applies.
            req2 = urllib.request.Request(
                url, headers={"User-Agent": "org-llm/install-tools"})
            with _urlopen(req2, timeout=60) as r:
                tmp.write_bytes(r.read())
        import subprocess, tarfile
        with tarfile.open(tmp) as tf:
            for member in tf.getmembers():
                if member.name.endswith("/bin/gh"):
                    member.name = "gh"
                    tf.extract(member, path=bin_dir)
                    break
        gh = bin_dir / "gh"
        gh.chmod(0o755)
        tmp.unlink(missing_ok=True)
        hail(f"gh CLI v{version} installed at {gh}")
        return gh
    except Exception as exc:
        red_alert(f"gh install failed: {exc}")
        return None


@app.command(name="install-tools", rich_help_panel="Onboarding")
def install_tools(
    skip_ollama:   Annotated[bool, typer.Option("--skip-ollama",   "-O")] = False,
    skip_models:   Annotated[bool, typer.Option("--skip-models",   "-M")] = False,
    skip_fonts:    Annotated[bool, typer.Option("--skip-fonts",    "-F")] = False,
    skip_opencode: Annotated[bool, typer.Option("--skip-opencode", "-P")] = False,
    skip_gh:       Annotated[bool, typer.Option("--skip-gh",       "-G")] = False,
    skip_claude:   Annotated[bool, typer.Option("--skip-claude",   "-K")] = False,
    skip_pass:     Annotated[bool, typer.Option("--skip-pass",     "-A")] = False,
):
    """Install Ollama, models, Nerd Fonts, opencode, gh CLI, Claude Code, and pass."""
    import platform
    import shutil
    import subprocess
    import urllib.request
    from .ui import solidarity, trans_stripe

    solidarity()
    console.print()

    bin_dir   = Path("~/.local/bin").expanduser()
    font_dir  = Path("~/.local/share/fonts/NerdFonts").expanduser()
    bin_dir.mkdir(parents=True, exist_ok=True)
    font_dir.mkdir(parents=True, exist_ok=True)

    ollama_bin = bin_dir / "ollama"

    # ── Ollama ────────────────────────────────────────────────────────────────
    if not skip_ollama:
        if shutil.which("ollama") or ollama_bin.exists():
            hail("Ollama already installed — skipping binary download.")
        else:
            arch = platform.machine().lower()
            arch_slug = "amd64" if arch in ("x86_64", "amd64") else "arm64"
            url = (
                f"https://github.com/ollama/ollama/releases/latest/download/"
                f"ollama-linux-{arch_slug}"
            )
            hail(f"Downloading Ollama ({arch_slug}) → {ollama_bin}")
            with warp("Beaming Ollama aboard"):
                # Route through cloud._urlopen so distro-specific
                # SSL CA paths apply (Guix puts the bundle under
                # ~/.guix-home/profile/etc/ssl/, certifi-only
                # platforms route via certifi.where()). Bare
                # urlretrieve here used to fail with
                # CERTIFICATE_VERIFY_FAILED on Guix during install
                # — straggler from the test-session backlog.
                from .cloud import _urlopen
                req = urllib.request.Request(
                    url, headers={"User-Agent": "org-llm/install-tools"})
                with _urlopen(req, timeout=120) as r:
                    ollama_bin.write_bytes(r.read())
            ollama_bin.chmod(0o755)
            hail(f"Ollama installed at {ollama_bin}")

        # Start ollama serve in background if not already running
        try:
            import ollama as _ol
            _ol.Client(host="http://localhost:11434").list()
            hail("Ollama is already running.")
        except Exception:
            hail("Starting ollama serve in background…")
            subprocess.Popen(
                [str(ollama_bin if ollama_bin.exists() else shutil.which("ollama")),
                 "serve"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            import time; time.sleep(2)

    # ── Models ────────────────────────────────────────────────────────────────
    if not skip_models:
        engine = _engine()
        with get_session(engine) as session:
            url = _ollama_url(session)
            model_keys = [
                "embed_model", "chat_model", "code_model",
                "reason_model", "fast_model", "instruct_model", "text_model",
            ]
            models_to_pull = list({_cfg(session, k) for k in model_keys
                                   if _cfg(session, k)})

        hail(f"Pulling {len(models_to_pull)} models via Ollama…")
        ollama_exe = shutil.which("ollama") or str(ollama_bin)
        with impulse("Pulling models", total=len(models_to_pull)) as (prog, task):
            for model in models_to_pull:
                on_screen(f"  ollama pull {model}")
                result = subprocess.run(
                    [ollama_exe, "pull", model],
                    capture_output=True, text=True,
                )
                if result.returncode != 0:
                    red_alert(f"Failed to pull {model}: {result.stderr.strip()}")
                prog.advance(task)

    # ── Nerd Fonts ────────────────────────────────────────────────────────────
    if not skip_fonts:
        font_name = "NotoMono"
        font_zip  = font_dir / f"{font_name}.tar.xz"
        font_url  = (
            f"https://github.com/ryanoasis/nerd-fonts/releases/latest/download/"
            f"{font_name}.tar.xz"
        )
        existing = list(font_dir.glob("*.ttf")) + list(font_dir.glob("*.otf"))
        if existing:
            hail(f"Nerd Fonts already present in {font_dir} — skipping.")
        else:
            hail(f"Downloading {font_name} Nerd Font…")
            with warp("Transporting font data"):
                # Same SSL-context routing as the Ollama download
                # above — bare urlretrieve fails on Guix without
                # certifi.
                from .cloud import _urlopen
                req = urllib.request.Request(
                    font_url,
                    headers={"User-Agent": "org-llm/install-tools"})
                with _urlopen(req, timeout=120) as r:
                    font_zip.write_bytes(r.read())
            subprocess.run(
                ["tar", "-xf", str(font_zip), "-C", str(font_dir)],
                check=True,
            )
            font_zip.unlink(missing_ok=True)
            subprocess.run(["fc-cache", "-fv"], capture_output=True)
            hail(f"NotoMono Nerd Font installed in {font_dir}")

    # ── opencode ──────────────────────────────────────────────────────────────
    if not skip_opencode:
        existing = _opencode_bin()
        if existing:
            hail(f"opencode already installed — skipping. ({existing})")
        else:
            hail("Installing opencode (AI coding agent)…")
            _install_opencode_bin(bin_dir)

    # ── gh CLI ────────────────────────────────────────────────────────────────
    if not skip_gh:
        if _gh_bin():
            hail(f"gh CLI already installed — skipping. ({_gh_bin()})")
        else:
            hail("Installing gh CLI (GitHub CLI)…")
            _install_gh(bin_dir)

    # ── Claude Code CLI ───────────────────────────────────────────────────────
    if not skip_claude:
        existing = _claude_bin()
        if existing:
            hail(f"Claude Code already installed — skipping. ({existing})")
        else:
            hail("Installing Claude Code CLI…")
            _install_claude_bin()

    # ── pass (credential manager) ─────────────────────────────────────────────
    if not skip_pass:
        from . import creds as creds_mod
        if creds_mod.is_installed():
            hail(f"pass already installed at {shutil.which('pass')}")
        else:
            hail("Installing pass (Unix password manager)…")
            if creds_mod.install():
                hail("pass installed successfully")
            else:
                console.print()
                console.print(creds_mod.install_help())
        if creds_mod.is_installed() and not creds_mod.is_initialized():
            console.print()
            console.print(creds_mod.install_help())

    console.print()
    console.print(trans_stripe(52))
    make_it_so()


@app.command(rich_help_panel="Maintenance")
def report(
    section: Annotated[str, typer.Argument(
        help="Section: overview | tags | recent | orphans | daily | all"
    )] = "all",
    days: Annotated[int, typer.Option("--days", "-d", help="Days back for recent")] = 14,
):
    """Render rich text reports on your org-roam library."""
    from .report import (
        report_daily, report_orphans, report_overview,
        report_recent, report_top_tags, NF, REPORT_HEADER,
    )
    engine = _engine()
    with get_session(engine) as session:
        console.rule(REPORT_HEADER)
        match section:
            case "overview": report_overview(session)
            case "tags":     report_top_tags(session)
            case "recent":   report_recent(session, days=days)
            case "orphans":  report_orphans(session)
            case "daily":    report_daily(session)
            case "all":
                report_overview(session)
                report_top_tags(session)
                console.print()
                report_recent(session, days=days)
                console.print()
                report_daily(session)
                console.print()
                report_orphans(session)
            case _:
                red_alert(f"Unknown section: {section!r}. "
                          "Use: overview | tags | recent | orphans | daily | all")
                raise typer.Exit(1)
        console.rule("[dim]end of report[/dim]")


