@app.command(rich_help_panel="Themes")
def theme(
    mode: Annotated[str, typer.Argument(help="dark | light | toggle | show")] = "show",
):
    """Set the UI color mode. Default is dark; light mode darkens every color
    so it's legible on a white terminal background. Override per-command via
    `ORG_LLM_THEME=light org-llm …` instead.
    """
    from .db import Config as Cfg
    from . import ui as ui_mod
    valid = {"dark", "light", "toggle", "show"}
    if mode not in valid:
        red_alert(f"Unknown mode {mode!r}. Use: {', '.join(sorted(valid))}")
        raise typer.Exit(1)

    engine = _engine()
    with get_session(engine) as session:
        current_row = session.get(Cfg, "theme")
        current = (current_row.value if current_row else "dark").strip().lower()

        if mode == "show":
            env = os.environ.get("ORG_LLM_THEME", "")
            valid_modes = ("dark", "light")
            on_screen(f"Stored theme: [bold]{current}[/bold]"
                      + ("" if current in valid_modes
                         else f"  [yellow](invalid value — falls back to dark)[/yellow]"))
            if env:
                env_norm = env.strip().lower()
                if env_norm in ("dark", "night"):
                    on_screen(f"ORG_LLM_THEME env override: [bold]dark[/bold] (this session)")
                elif env_norm in ("light", "day"):
                    on_screen(f"ORG_LLM_THEME env override: [bold]light[/bold] (this session)")
                else:
                    on_screen(f"ORG_LLM_THEME env: [bold]{env}[/bold] [yellow](unrecognised — ignored)[/yellow]")
            on_screen(f"Active right now: [bold]{ui_mod.THEME_MODE}[/bold]"
                      + (" (next command will pick up changes)" if current != ui_mod.THEME_MODE else ""))
            return

        new = mode if mode != "toggle" else ("light" if current == "dark" else "dark")
        if current_row:
            current_row.value = new
        else:
            session.add(Cfg(key="theme", value=new))
        session.commit()

    hail(f"Theme set to [bold]{new}[/bold]. Restart the command (or unset ORG_LLM_THEME) to see it apply.")
    if os.environ.get("ORG_LLM_THEME"):
        on_screen("Note: ORG_LLM_THEME env var is set and overrides this config for the current shell.")
    make_it_so()


@app.command(rich_help_panel="Themes")
def palette(
    name: Annotated[str, typer.Argument(
        help="LCARS palette name (classic | red | green | gold | violet) "
             "OR 'show' / 'reset'. Bare = list every named palette + the "
             "current selection.")] = "",
    primary:   Annotated[str, typer.Option("--primary",
                help="Override the primary LCARS channel with a hex color "
                     "(e.g. #FF9900). Empty = clear the override.")] = None,
    secondary: Annotated[str, typer.Option("--secondary",
                help="Override the secondary LCARS channel with a hex color")] = None,
    tertiary:  Annotated[str, typer.Option("--tertiary",
                help="Override the tertiary LCARS channel with a hex color")] = None,
):
    """Pick or preview an LCARS color palette.

    Five named palettes ship: classic (TNG default orange/purple/blue),
    red (red-alert), green (Voyager astrometrics), gold (engineering),
    violet (sciences). Per-channel hex overrides via --primary /
    --secondary / --tertiary stack on top of the named palette.

    Bare invocation lists every palette with a text-based color slider
    so you can see the swatches without leaving the terminal.
    """
    from . import palettes as _pal
    from .db   import Config as _Cfg
    from rich.table import Table
    from rich.panel import Panel

    if name == "reset":
        engine = _engine()
        with get_session(engine) as session:
            for k in ("lcars_palette",
                       "lcars_color_primary",
                       "lcars_color_secondary",
                       "lcars_color_tertiary"):
                row = session.get(_Cfg, k)
                if row:
                    session.delete(row)
            session.commit()
        hail("LCARS palette reset to classic (no overrides).")
        make_it_so()
        return

    # No arg OR explicit "show" → list all palettes + the active one
    if not name or name == "show":
        active = _pal.active_palette_name()
        overrides = _pal.palette_overrides()
        # Render each palette as a text-based "slider": name + a
        # row of three colored block segments showing the swatches.
        tbl = Table(box=None, pad_edge=False, show_header=True,
                     header_style="lcars1")
        tbl.add_column("",          width=2)
        tbl.add_column("Name",      style="lcars2", no_wrap=True, width=10)
        tbl.add_column("Swatch",    no_wrap=True, width=24)
        tbl.add_column("Description", style="dim")
        for pname, bundle in _pal.list_palettes():
            marker = "◉" if pname == active else "◯"
            # Swatch: three contiguous "█████" blocks each in the
            # palette's primary/secondary/tertiary color
            swatch_bits = []
            for k, prefix in (("lcars1", "[#"),
                               ("lcars2", "[#"),
                               ("lcars3", "[#")):
                hex_val = bundle.get(k, "#888888").lstrip("#")
                swatch_bits.append(f"[{bundle[k]}]████████[/{bundle[k]}]")
            swatch = "".join(swatch_bits)
            tbl.add_row(marker, pname, swatch,
                          bundle.get("description", ""))
        console.print()
        console.print(Panel(tbl,
                              title="[lcars1]LCARS palettes[/lcars1]  "
                                    f"[dim]active: {active}[/dim]",
                              border_style="lcars2", padding=(1, 1)))
        # Per-channel overrides if any
        if overrides:
            console.print()
            on_screen("[lcars1]Active per-channel overrides:[/lcars1]")
            for k, v in overrides.items():
                on_screen(f"  [lcars2]{k:<8}[/lcars2] [{v}]████████[/{v}]  {v}")
        console.print()
        on_screen("[dim]Pick:[/dim]   [bold]org-llm palette <name>[/bold]")
        on_screen("[dim]Tweak:[/dim]  [bold]org-llm palette <name> "
                  "--primary '#RRGGBB'[/bold]")
        on_screen("[dim]Reset:[/dim]  [bold]org-llm palette reset[/bold]")
        return

    # Validate the chosen palette name
    if name not in _pal.PALETTES:
        red_alert(f"Unknown palette {name!r}. "
                  f"Choices: {', '.join(p[0] for p in _pal.list_palettes())}.")
        raise typer.Exit(1)

    # Validate hex overrides up-front so we don't half-apply
    overrides_to_set: list[tuple[str, str | None]] = []
    for opt_val, cfg_key in ((primary,   "lcars_color_primary"),
                               (secondary, "lcars_color_secondary"),
                               (tertiary,  "lcars_color_tertiary")):
        if opt_val is None:
            continue
        if opt_val == "":
            overrides_to_set.append((cfg_key, None))   # delete row
            continue
        if not _pal._is_hex_color(opt_val):
            red_alert(f"{cfg_key} value {opt_val!r} is not a hex color "
                      "(expected #RRGGBB).")
            raise typer.Exit(1)
        overrides_to_set.append((cfg_key, _pal._normalise_hex(opt_val)))

    # Persist
    engine = _engine()
    with get_session(engine) as session:
        row = session.get(_Cfg, "lcars_palette")
        if row:
            row.value = name
        else:
            session.add(_Cfg(key="lcars_palette", value=name))
        for cfg_key, val in overrides_to_set:
            existing = session.get(_Cfg, cfg_key)
            if val is None:
                if existing:
                    session.delete(existing)
            else:
                if existing:
                    existing.value = val
                else:
                    session.add(_Cfg(key=cfg_key, value=val))
        session.commit()

    bundle = _pal.PALETTES[name]
    swatch = "".join(f"[{bundle[k]}]████████[/{bundle[k]}]"
                       for k in ("lcars1", "lcars2", "lcars3"))
    console.print()
    on_screen(f"[lcars1]Active LCARS palette:[/lcars1] [bold]{name}[/bold]  {swatch}")
    on_screen(f"[dim]{bundle.get('description', '')}[/dim]")
    on_screen("[dim]Run any command (e.g. [bold]org-llm[/bold]) to see it apply.[/dim]")
    make_it_so()


@app.command(rich_help_panel="Maintenance")
def completion(
    shell:   Annotated[str,  typer.Argument(help="Shell: fish | bash | zsh | powershell | pwsh")] = "fish",
    install: Annotated[bool, typer.Option("--install", "-i",
             help="Write the completion to the standard location for that shell")] = False,
):
    """Print or install shell completions. Always works regardless of $SHELL.

    Default locations on --install:
      fish        ~/.config/fish/completions/org-llm.fish
      bash        ~/.local/share/bash-completion/completions/org-llm
      zsh         ~/.zfunc/_org-llm  (add ~/.zfunc to fpath in .zshrc)
      powershell  $PROFILE  (appended)
    """
    from typer.completion import get_completion_script

    valid = {"fish", "bash", "zsh", "powershell", "pwsh"}
    if shell not in valid:
        red_alert(f"Unknown shell {shell!r}. Use one of: {', '.join(sorted(valid))}")
        raise typer.Exit(1)

    script = get_completion_script(
        prog_name="org-llm",
        complete_var="_ORG_LLM_COMPLETE",
        shell=shell,
    )

    if not install:
        print(script)
        return

    targets = {
        "fish":       Path("~/.config/fish/completions/org-llm.fish").expanduser(),
        "bash":       Path("~/.local/share/bash-completion/completions/org-llm").expanduser(),
        "zsh":        Path("~/.zfunc/_org-llm").expanduser(),
        "powershell": Path("~/.config/powershell/Microsoft.PowerShell_profile.ps1").expanduser(),
        "pwsh":       Path("~/.config/powershell/Microsoft.PowerShell_profile.ps1").expanduser(),
    }
    target = targets[shell]
    target.parent.mkdir(parents=True, exist_ok=True)

    if shell in ("powershell", "pwsh"):
        # Append rather than overwrite the profile
        existing = target.read_text() if target.exists() else ""
        if "_ORG_LLM_COMPLETE" not in existing:
            with open(target, "a") as f:
                f.write("\n\n# org-llm completion\n" + script + "\n")
            hail(f"Appended completion to {target}")
        else:
            hail(f"Completion already present in {target}")
    else:
        target.write_text(script)
        hail(f"Wrote {shell} completion → {target}")
        if shell == "zsh":
            on_screen("Add to ~/.zshrc:  fpath+=~/.zfunc; autoload -Uz compinit && compinit")
        elif shell == "fish":
            on_screen("Reload:  source ~/.config/fish/completions/org-llm.fish")
    make_it_so()


# Register skill commands at import time so they appear in --help
from . import cli_skills as _cs
_cs.register(app)


_SINGLE_QUERY_VERBS = {
    "ask", "code", "search", "tutor", "source",
}


# Verbs whose intent the LLM may reconstruct from a mangled argv. Distinct
# from _LLM_FIXABLE_VERBS (which is for SRE-style infrastructure repairs and
# specifically excludes user-facing verbs to avoid burning tokens). This list
# is what the LLM is allowed to ARGUE its way back into when shell quoting
# breaks the original invocation.
_INTENT_RECOVERABLE_VERBS = {
    "ask", "code", "capture", "search", "tutor", "source",
    "models", "doctor", "report", "discover", "personalize",
    "code-index", "review-emacs", "tag", "config", "knob",
    "context", "stale",
}


def _llm_intent_repair(broken_argv: list[str], error: str) -> list[str] | None:
    """Ask the LLM to reconstruct the user's intent from a mangled argv.

    Used as the last-resort recovery for Typer parse errors (typically shell
    quoting issues). Different from _llm_assisted_fix: that one is for SRE
    fixes (config, models, doctor); this one re-creates a user-facing
    invocation in the same verb the user typed.

    Returns the proposed argv (without leading "org-llm") on success, or
    None if no safe recovery was found.
    """
    if not broken_argv:
        return None
    verb = next((a for a in broken_argv if not a.startswith("-")), "")
    if verb not in _INTENT_RECOVERABLE_VERBS:
        return None

    try:
        engine = _engine()
        with get_session(engine) as session:
            cloud_provider = _cfg(session, "cloud_provider")
            cloud_endpoint = _cfg(session, "cloud_endpoint_url")
            cloud_model    = (_cfg(session, "fixer_model")
                              or _cfg(session, "cloud_model")
                              or "openai/gpt-oss-20b:free")
            db_api_key     = _cfg(session, "cloud_api_key") or _cfg(session, "runpod_api_key")
    except Exception:
        return None
    if not cloud_endpoint:
        return None

    from . import creds as _creds
    api_key = (_creds.read_secret(_creds.cloud_slug(cloud_provider))
               if cloud_provider else None) or db_api_key

    sys_prompt = (
        "You repair shell-quoting errors for a CLI tool called `org-llm`.\n"
        "The user typed a command. The shell mangled it (typically because "
        "of nested quotes), so Typer rejected the argv with 'Got unexpected "
        "extra arguments'. Your job is to reconstruct what the user meant.\n\n"
        "Reply with STRICT JSON only. No prose, no markdown:\n"
        '  {"argv": ["ask", "connect Literate Programming Approach to anything else in my vault"], "reason": "shell unquoted the inner double quotes"}\n'
        'OR {"argv": null, "reason": "cannot reconstruct intent"}\n\n'
        f"argv[0] MUST be one of: {', '.join(sorted(_INTENT_RECOVERABLE_VERBS))}.\n"
        "Glue all stray positional tokens back into the single string the\n"
        "user clearly intended. Preserve any --flag and its value as separate\n"
        "argv entries. Do NOT add new flags. Do NOT change the verb."
    )
    user_prompt = (
        f"Verb: {verb}\n"
        f"Broken argv: {broken_argv}\n"
        f"Typer error: {error[:600]}\n\n"
        "Reconstruct the intended argv."
    )

    try:
        from .cloud import cloud_chat
        reply = cloud_chat(user_prompt, model=cloud_model,
                           endpoint_url=cloud_endpoint,
                           api_key=api_key, system=sys_prompt)
    except Exception:
        return None

    cleaned = _strip_code_fences(reply, "json").strip()
    import json as _json
    try:
        plan = _json.loads(cleaned)
    except Exception:
        return None
    proposed = plan.get("argv")
    if not isinstance(proposed, list) or not proposed:
        return None
    if str(proposed[0]) != verb:
        # Don't let the LLM silently change verbs.
        return None
    if any(not isinstance(x, str) for x in proposed):
        return None
    if plan.get("reason"):
        on_screen(f"  [dim]LLM intent: {plan['reason']}[/dim]")
    return proposed


def _llm_recovery_advice(failure_summary: str, *,
                          context: str = "",
                          max_bullets: int = 3) -> str:
    """Generate concrete recovery bullets for any failure.

    Used as the *final* layer after deterministic fallbacks exhaust.
    Returns an empty string when the LLM is unreachable or refuses —
    the caller's existing red_alert + Exit still happens; this just
    *adds* hopefully-useful next-steps before it.

    The prompt is general-purpose: pass any failure summary + any
    context. Output is bullet-formatted "• <action>".
    """
    sys_msg = (
        "You give terse, concrete recovery advice for a CLI tool "
        f"(`org-llm`) failure. Output ≤ {max_bullets} short bullets "
        "(≤ 22 words each) naming SPECIFIC next-step commands the "
        "user can run themselves. Reference real org-llm subcommands, "
        "actual flags, real package names. Be specific. No preamble, "
        "no markdown headers, no quotes around commands. One bullet "
        "per line, prefixed with `• `."
    )
    user_msg = (
        f"Failure:\n{failure_summary[:1200]}\n\n"
        + (f"Context:\n{context[:600]}\n\n" if context else "")
        + f"Give {max_bullets} concrete recovery bullets."
    )
    try:
        engine = _engine()
        with get_session(engine) as session:
            url = _ollama_url(session)
            mdl = (_cfg(session, "fast_model")
                   or _cfg(session, "chat_model")
                   or "llama3.2")
        from .llm import chat as _chat
        # 15s timeout — this should be quick or we skip it.
        import threading
        result: dict = {"resp": ""}
        def _r():
            try:
                result["resp"] = _chat(user_msg, model=mdl,
                                         base_url=url, system=sys_msg) or ""
            except Exception:
                pass
        try:
            from .ui import thinking
            with thinking("Asking the LLM for recovery advice", model=mdl):
                t = threading.Thread(target=_r, daemon=True)
                t.start(); t.join(timeout=15.0)
        except Exception:
            t = threading.Thread(target=_r, daemon=True)
            t.start(); t.join(timeout=15.0)
        if t.is_alive():
            return ""
        out = (result["resp"] or "").strip()
        # Keep only bullet-shaped lines
        good = []
        for line in out.splitlines():
            ln = line.strip(" -•\"'`").strip()
            if 8 <= len(ln) <= 200:
                good.append(f"• {ln}")
            if len(good) >= max_bullets:
                break
        return "\n".join(good)
    except Exception:
        return ""


def _run_with_stall_watch(argv: list[str], *,
                            stall_secs: float = 120.0,
                            label: str = "") -> int:
    """Run a subprocess streaming its output line-by-line; detect stalls.

    A "stall" is `stall_secs` of no new stdout/stderr bytes from the
    child. When detected, captures the last 1500 chars of output and
    asks the LLM to judge whether it's actually stuck and what the
    user should do. The user is offered three options:

      - kill the subprocess and apply LLM's suggested fix command
      - keep waiting (resets the stall timer)
      - exit setup early and run the subprocess manually later

    Returns the subprocess exit code (130 if user killed it).

    This is the more-proactive layer the user asked for: instead of
    blindly waiting for `ollama pull` or `apt-get install` to finish,
    the app actively monitors and offers help when nothing's moving.
    """
    import subprocess, threading, time, queue, sys
    if label:
        on_screen(f"[dim]→ {label} — watching for stalls (>{stall_secs:.0f}s)…[/dim]")

    try:
        proc = subprocess.Popen(
            argv,
            stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
            text=True, bufsize=1,
        )
    except Exception as e:
        red_alert(f"Could not spawn {argv!r}: {e}")
        return 127

    last_byte_at = [time.monotonic()]
    output_tail: list[str] = []
    output_q: queue.Queue = queue.Queue()

    def _reader():
        try:
            assert proc.stdout is not None
            for line in proc.stdout:
                output_q.put(line)
        finally:
            output_q.put(None)   # sentinel

    t = threading.Thread(target=_reader, daemon=True)
    t.start()

    stalled_already = False
    while True:
        try:
            line = output_q.get(timeout=2.0)
        except queue.Empty:
            line = ""
        if line is None:
            break    # subprocess closed stdout
        if line:
            sys.stdout.write(line)
            sys.stdout.flush()
            output_tail.append(line)
            if len(output_tail) > 80:
                output_tail = output_tail[-80:]
            last_byte_at[0] = time.monotonic()
            stalled_already = False

        elapsed = time.monotonic() - last_byte_at[0]
        if elapsed > stall_secs and not stalled_already and proc.poll() is None:
            stalled_already = True
            console.print()
            on_screen(f"[yellow]No output for {elapsed:.0f}s — "
                      f"checking with the LLM…[/yellow]")
            tail_blob = "".join(output_tail)[-1500:]
            sys_msg = (
                "You are diagnosing a possibly-stalled subprocess for a "
                "CLI tool. Reply in 2-4 short sentences: (1) is this "
                "actually stuck or just slow, (2) what should the user "
                "do — keep waiting, kill and try a specific alternate "
                "command, or check something. Be concrete; cite specific "
                "lines from the tail."
            )
            user_msg = (
                f"Command: {' '.join(argv)}\n"
                f"Last output (tail):\n{tail_blob or '(no output yet)'}\n\n"
                f"Idle for {elapsed:.0f}s. Diagnosis?"
            )
            advice = _llm_one_liner(user_msg, system=sys_msg,
                                      timeout=20.0, fallback="")
            if advice:
                on_screen(f"[lcars3]LLM:[/lcars3] {advice}")
            choice = ""
            try:
                choice = typer.prompt(
                    "[k]ill / [w]ait / [s]kip the rest of setup",
                    default="w", show_default=True).strip().lower()[:1]
            except Exception:
                choice = "w"
            if choice == "k":
                proc.terminate()
                try:
                    proc.wait(timeout=5)
                except Exception:
                    proc.kill()
                on_screen("[yellow]Subprocess killed.[/yellow]")
                return 130
            if choice == "s":
                proc.terminate()
                raise typer.Exit(0)
            # 'w' or anything else → reset timer + keep going
            last_byte_at[0] = time.monotonic()
            stalled_already = False
            on_screen(f"[dim]Resuming watch ({stall_secs:.0f}s window).[/dim]")

        if proc.poll() is not None and output_q.empty():
            break

    proc.wait()
    return proc.returncode


def _shell_quote_repair(argv: list[str]) -> list[str] | None:
    """If argv looks like a single-string command got split by bad shell
    quoting, glue everything from arg index 1 onward back into one string.

    Example: `ask connect "Foo Bar" lately` becomes `ask 'connect Foo Bar lately'`
    when the user originally meant a single quoted query but the shell
    eat/recombined the quotes.

    Only applies to commands in _SINGLE_QUERY_VERBS — those take exactly
    one positional string argument. Returns the repaired argv or None when
    the heuristic doesn't apply.
    """
    if len(argv) < 3:
        return None
    # Strip leading global options (none today, but guard for future flags).
    cmd_idx = 0
    while cmd_idx < len(argv) and argv[cmd_idx].startswith("-"):
        cmd_idx += 1
    if cmd_idx >= len(argv):
        return None
    verb = argv[cmd_idx]
    if verb not in _SINGLE_QUERY_VERBS:
        return None
    # Repaired tail: re-join any non-flag positional tokens. Keep flags as-is.
    head = argv[: cmd_idx + 1]
    tail = argv[cmd_idx + 1:]
    flags: list[str] = []
    words: list[str] = []
    i = 0
    while i < len(tail):
        tok = tail[i]
        if tok.startswith("-"):
            flags.append(tok)
            # Pull the next token as flag's value if it doesn't itself look like a flag
            if i + 1 < len(tail) and not tail[i + 1].startswith("-"):
                # Conservative: only treat as a value if it's short (avoid
                # eating real query words). Real --model values are model tags
                # like "qwen2.5:3b" — short and contain digits/colons.
                nxt = tail[i + 1]
                if len(nxt) <= 32 and any(c in nxt for c in ":/_") or nxt.isdigit():
                    flags.append(nxt); i += 1
            i += 1
            continue
        words.append(tok)
        i += 1
    if len(words) <= 1:
        return None
    glued = " ".join(words)
    return head + flags + [glued]


def _deterministic_refresh_summary(summary: dict, engine) -> None:
    """Print a clean, factual summary of a small catalog refresh.

    Used when the LLM-driven analysis would just confabulate — gemma3
    et al. happily produce narrative ("DALL-E Mini generated $25.17
    more per unit") when given <3 real diffs to summarise. With sparse
    input the deterministic path is strictly better: faster, no
    hallucination risk, and the user sees the actual facts.
    """
    from rich.panel import Panel
    bullets: list[str] = []

    cur_model = ""
    try:
        with get_session(engine) as session:
            cur_model = _cfg(session, "cloud_model") or ""
    except Exception:
        pass

    added         = summary.get("added") or []
    changed       = summary.get("changed") or []
    price_changes = summary.get("price_changes") or []
    dead          = summary.get("dead_providers") or []
    new_provs     = summary.get("new_providers") or []
    retired_provs = summary.get("retired_providers") or []

    if added:
        sample = ", ".join(added[:5])
        more = f" (+{len(added)-5} more)" if len(added) > 5 else ""
        bullets.append(f"{len(added)} new model(s): {sample}{more}")
    if price_changes:
        bullets.append(f"{len(price_changes)} model(s) repriced.")
        for c in price_changes[:5]:
            mark = "[YOU] " if c["slug"] == cur_model else ""
            bullets.append(
                f"{mark}{c['slug']}: "
                f"${c['old_cost_out']}/Mtok out → "
                f"${c['new_cost_out']}/Mtok"
            )
    if dead:
        bullets.append(f"Provider URL HEAD-probe failed: "
                        f"{', '.join(dead)} (might be temporary; could "
                        f"also indicate a discontinued service).")
    if new_provs:
        bullets.append(f"New provider(s) in canonical roster: "
                        f"{', '.join(new_provs)}")
    if retired_provs:
        bullets.append(f"Retired provider(s) in canonical roster: "
                        f"{', '.join(retired_provs)}")
    if cur_model and not any(c["slug"] == cur_model for c in price_changes):
        if cur_model in added:
            bullets.insert(0, f"[YOU] Your cloud_model {cur_model} is "
                            f"freshly added to the catalog.")

    if not bullets:
        bullets.append("No newsworthy changes.")

    body = "\n".join(f"• {b}" for b in bullets)
    console.print(Panel(body,
                          title="[lcars1]Catalog refresh — alerts[/lcars1]",
                          border_style="lcars2", padding=(1, 2)))
    on_screen("[dim]Re-run[/dim] [bold]org-llm cloud --tune[/bold] "
               "[dim]to see how this catalog refresh shifts your "
               "recommendations.[/dim]")


def _llm_analyze_catalog_diff(summary: dict, engine) -> None:
    """After a successful catalog refresh, run an LLM analysis pass to
    surface user-facing alerts about meaningful changes.

    Cheap (one chat call to a small model). Falls back to a
    deterministic summary panel if the LLM is unreachable. The output
    is purely informational — config writes still require the user
    going through `cloud --tune --apply` or equivalent.
    """
    from rich.panel import Panel
    added         = summary.get("added", [])
    changed       = summary.get("changed", [])
    price_changes = summary.get("price_changes", [])

    # Read the user's currently-configured cloud_model so the LLM can
    # tell them whether the diff affects them personally.
    try:
        with get_session(engine) as session:
            cur_model    = _cfg(session, "cloud_model")
            cur_provider = _cfg(session, "cloud_provider")
    except Exception:
        cur_model = cur_provider = ""

    sys_msg = (
        "You write short, concrete alerts after a cloud-model catalog "
        "refresh. Output STRICTLY 3-6 non-empty bullet lines starting "
        "with `• `, no preamble, no markdown headers, no blank bullets. "
        "Each bullet is one observation the user might act on. Mention "
        "model slugs LITERALLY — copy them character-for-character from "
        "the data given to you. NEVER invent slugs, even if a similar "
        "name 'sounds right'. If you don't see a slug in the data, "
        "don't write it. If their current model is affected (price "
        "change, dropped, or a cheaper-better alternative emerged), "
        "put that bullet first and prefix it with `[YOU]`. Be honest "
        "if nothing is news — say so in one bullet."
    )
    # Include a short literal slug list so the LLM has explicit grounding.
    # We supply ONLY the slugs that actually changed or got added (the
    # full 378-row list would be too much noise).
    grounded_slugs: list[str] = []
    grounded_slugs.extend(added[:40])
    grounded_slugs.extend(c["slug"] for c in price_changes[:40])
    grounded_slugs = sorted(set(grounded_slugs))
    user_msg = (
        f"User's current cloud config:\n"
        f"  cloud_provider = {cur_provider or '(unset)'}\n"
        f"  cloud_model    = {cur_model or '(unset)'}\n\n"
        f"AUTHORITATIVE slug list (the ONLY slugs you may reference "
        f"in your output — anything else is a hallucination):\n"
    )
    for s in grounded_slugs[:80]:
        user_msg += f"  - {s}\n"
    user_msg += (
        f"\nCatalog refresh summary:\n"
        f"  {len(added)} slugs newly added\n"
        f"  Price changes ({len(price_changes)}):\n"
    )
    for c in price_changes[:20]:
        user_msg += (
            f"    {c['slug']}: ${c['old_cost_out']}/Mtok out → "
            f"${c['new_cost_out']}/Mtok\n"
        )

    advice = ""
    rescue_err = ""
    try:
        from .llm import chat as _chat
        from .ui  import thinking as _thinking
        with get_session(engine) as session:
            url = _ollama_url(session)
            mdl = (_cfg(session, "fast_model")
                    or _cfg(session, "chat_model")
                    or "llama3.2")
        with _thinking("Analyzing catalog diff", model=mdl):
            advice = _chat(user_msg, model=mdl, base_url=url,
                            system=sys_msg, timeout=45.0) or ""
    except Exception as e:
        rescue_err = f"{type(e).__name__}: {e}"

    if advice:
        # Drop empty bullets ("• " with nothing after) — the LLM
        # routinely emits these as separators and they pollute the
        # panel.
        import re as _re
        cleaned = _re.sub(r"^\s*•\s*$\n?", "", advice, flags=_re.M)
        # Strip leading blank lines from the panel body.
        cleaned = cleaned.lstrip("\n").rstrip()

        # Anti-hallucination: extract every slug-shaped token from the
        # LLM output and check it exists in the freshly-merged catalog.
        # Real example from this session: gemma3 invented
        # `openai/gpt-125b:free`, `antares/rasputin-latest`,
        # `deepseek-v4-pro`, etc. — none of which exist. A user could
        # have followed that advice and tried to switch their config to
        # a fictional model. The whitelisted shell-pattern sanitizer
        # doesn't catch this because the strings ARE valid slugs in
        # SHAPE; they just aren't in the catalog.
        from . import cloud as _cloud
        known_slugs = {m.slug.lower() for m in _cloud.CLOUD_MODELS}
        # Slugs look like `provider/model[:tag]` — at least one slash,
        # word/dot/colon/dash chars, no whitespace. Conservative regex.
        _SLUG_RX = _re.compile(r"\b([a-z0-9-]+/[a-z0-9._:-]+)\b",
                                flags=_re.I)
        mentioned = set()
        for m in _SLUG_RX.finditer(cleaned):
            mentioned.add(m.group(1).lower())
        invented = sorted(s for s in mentioned if s not in known_slugs)

        # The shell-injection sanitizer still applies (the LLM could
        # in theory emit `pip install ...` even here). Keep that layer
        # too.
        try:
            from .rescue import sanitize_llm_advice as _san
            checked = _san(cleaned)
        except Exception:
            checked = None
        title = "[lcars1]Catalog refresh — alerts[/lcars1]"
        suspect = ((checked is not None and not checked.safe)
                    or bool(invented))
        if suspect:
            flag_lines: list[str] = []
            if invented:
                flag_lines.append(
                    f"LLM mentioned {len(invented)} slug(s) not in the "
                    f"refreshed catalog — likely hallucinations:")
                for s in invented[:6]:
                    flag_lines.append(f"  · {s}")
                if len(invented) > 6:
                    flag_lines.append(f"  · …and {len(invented)-6} more")
            if checked is not None:
                for f in checked.flagged:
                    flag_lines.append(f"  · {f}")
            warn = "\n".join(flag_lines)
            console.print(Panel(
                f"[yellow]Advice flagged — verify before acting:[/yellow]\n"
                f"{warn}\n\n{cleaned}",
                title=title, border_style="warn", padding=(1, 2),
            ))
            on_screen("[dim]The flagged slugs are not in the catalog. "
                       "Cross-check with[/dim] [bold]org-llm cloud "
                       "--tune[/bold] [dim]which only suggests real "
                       "models from the merged data.[/dim]")
        else:
            console.print(Panel(cleaned, title=title,
                                  border_style="lcars2", padding=(1, 2)))
    else:
        # Fallback: deterministic summary so the user always sees
        # SOMETHING after a refresh.
        body = (f"• {len(added)} new model(s) added to the catalog.\n"
                f"• {len(price_changes)} model(s) with price changes.")
        if cur_model and any(c["slug"] == cur_model for c in price_changes):
            body += f"\n• [YOU] Your current cloud_model {cur_model} "
            body += "had a price change."
        if rescue_err:
            body += f"\n\n[dim](LLM analysis unavailable: {rescue_err})[/dim]"
        console.print(Panel(body,
                              title="[lcars1]Catalog refresh — alerts[/lcars1]",
                              border_style="lcars2", padding=(1, 2)))

    on_screen("[dim]Re-run[/dim] [bold]org-llm cloud --tune[/bold] "
               "[dim]to see how this catalog refresh shifts your "
               "recommendations.[/dim]")


def _maybe_publish_self_rewrite(target: Path, snap, exc: BaseException,
                                  argv: list[str]) -> None:
    """After a verified self-rewrite, optionally commit + push the
    change to a fresh git branch so the trail is on GitHub for review.

    Strict gates:
      - The package directory must be a git checkout.
      - Must be on an interactive TTY (no surprises in CI / piped runs).
      - User must explicitly opt in.
      - We push to a NEW branch (`self-rewrite/<ts>-<ExcType>`), never
        to main. The user PRs and merges.

    The Captain's Log already records the self-rewrite event via
    track_event; this just gets the bits off the laptop.
    """
    import subprocess
    from datetime import datetime as _dt
    from .ui import on_screen as _on
    pkg_root = Path(__file__).resolve().parent.parent
    if not (pkg_root / ".git").exists():
        # Installed via `pip install` / not a checkout — nothing to commit.
        return
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        return
    try:
        ans = input("\nCommit + push this self-rewrite to a feature branch "
                     "for review? [y/N] ").strip().lower()
    except (KeyboardInterrupt, EOFError):
        console.print()
        return
    if ans not in {"y", "yes", "yeah", "yep", "sure", "ok"}:
        _on("[dim]Skipped publish — change is local only.[/dim]")
        return

    err_type = type(exc).__name__
    ts = _dt.now().strftime("%Y%m%d-%H%M%S")
    branch = f"self-rewrite/{ts}-{err_type}"
    cmd_str = "org-llm " + " ".join(argv)
    title = f"self-rewrite: fix {err_type} in {target.name}"
    body = (f"Auto-generated by org-llm's self-rewrite path after a "
            f"verified runtime fix.\n\n"
            f"FAILING COMMAND: `{cmd_str}`\n\n"
            f"EXCEPTION: {err_type}: {exc}\n\n"
            f"SNAPSHOT: `{snap.id}` "
            f"(rollback with `org-llm self rollback {snap.id}`)\n\n"
            f"VERIFIED: re-running the failing command exits cleanly "
            f"after this patch.\n\n"
            f"Review the diff carefully — this commit was authored by "
            f"an LLM and applied automatically after the user approved "
            f"a single-shot patch in their terminal. The verification "
            f"only checks that the original failure no longer fires; "
            f"it does NOT prove correctness for related code paths.")

    def _git(*args: str, check: bool = True) -> subprocess.CompletedProcess:
        return subprocess.run(["git", "-C", str(pkg_root), *args],
                                capture_output=True, text=True, check=check)
    try:
        # Capture current branch so we can return after pushing
        cur = _git("symbolic-ref", "--short", "HEAD",
                    check=False).stdout.strip() or "HEAD"
        _git("checkout", "-b", branch)
        _git("add", str(target.resolve().relative_to(pkg_root)))
        # Use a HEREDOC-style multi-line commit message
        msg = f"{title}\n\n{body}"
        _git("commit", "-m", msg)
        # Try to push. If no remote / not authenticated, fall back to
        # leaving the branch local + telling the user the next step.
        push = _git("push", "-u", "origin", branch, check=False)
        # Always return to the original branch so subsequent calls don't
        # leave the user mid-checkout.
        _git("checkout", cur, check=False)
        if push.returncode == 0:
            _on(f"[lcars3]✓ Pushed to branch [bold]{branch}[/bold] — "
                f"open a PR on GitHub to review.[/lcars3]")
        else:
            _on(f"[lcars3]✓ Committed locally to branch "
                f"[bold]{branch}[/bold].[/lcars3]")
            _on(f"[dim]Push failed (no remote / auth?): "
                f"{push.stderr.strip()[:200]}[/dim]")
            _on(f"[dim]Push manually:[/dim] [bold]git push -u origin "
                f"{branch}[/bold]")
    except Exception as e:
        _on(f"[red]Publish failed: {type(e).__name__}: {e}[/red]")
        _on(f"[dim]The patch is still applied locally; snapshot "
            f"{snap.id} is intact.[/dim]")


def _our_module_in_traceback(exc: BaseException) -> Path | None:
    """Find the deepest frame inside org_llm/ in an exception's traceback.

    Used by the LLM-rescue layer to decide whether the crash is in code
    we can repair (returns the file path) or in third-party code where
    self-rewrite isn't relevant (returns None).
    """
    import traceback as _tb
    pkg_root = Path(__file__).resolve().parent  # org_llm/
    deepest = None
    for frame in _tb.extract_tb(exc.__traceback__):
        try:
            fp = Path(frame.filename).resolve()
        except Exception:
            continue
        try:
            fp.relative_to(pkg_root)
        except ValueError:
            continue
        deepest = fp
    return deepest


def _llm_diagnose_uncaught(exc: BaseException, argv: list[str]) -> None:
    """LLM rescue for uncaught runtime exceptions.

    Anything that bubbles past command bodies — a sqlite OperationalError,
    a network ConnectionError, a None.attribute crash — gets a tight
    diagnosis and concrete recovery suggestion instead of a raw Python
    traceback. If the offending frame is inside org-llm itself, also
    offers an opt-in LLM self-rewrite (snapshots first; applies on user
    confirmation only). Best-effort: if the LLM is unreachable, we
    print the exception's last traceback line and exit cleanly.
    """
    import traceback as _tb
    from .ui import on_screen as _on
    err_type = type(exc).__name__
    err_msg  = str(exc)
    tb_tail  = "".join(_tb.format_exception(type(exc), exc,
                                              exc.__traceback__))[-1500:]
    _on(f"[red]✗ {err_type}: {err_msg}[/red]")

    # 1a. Try the structured rescue registry FIRST. Deterministic +
    # fast — most exceptions a user actually hits in this CLI fit a
    # known pattern (Ollama not pulled, model OOM, DB locked, etc).
    # The registry was added because the LLM rescue hallucinated a
    # "pip install shutil" command for a NameError caused by a missing
    # local import inside org-llm itself; the registry catches that
    # class deterministically now.
    try:
        from .rescue import match_structured as _ms
        hint = _ms(exc, tb_tail)
    except Exception:
        hint = None
    crash_in_our_code = _our_module_in_traceback(exc) is not None
    skip_llm_diagnosis = False
    skip_self_rewrite  = False
    if hint is not None:
        from rich.panel import Panel as _Panel
        body = (f"[bold]WHY:[/bold] {hint.why}\n"
                f"[bold]FIX:[/bold] {hint.fix}")
        title = (f"[lcars1]Recovery hint  · confidence: {hint.confidence}"
                 f"[/lcars1]")
        console.print()
        console.print(_Panel(body, title=title,
                              border_style="lcars2", padding=(1, 2)))

        # User-caused exception (PermissionError, FileNotFoundError on
        # a user-supplied path): the registry hint is the answer.
        # There's nothing for the LLM to add and NOTHING to self-
        # rewrite — patching our source can't fix what the user typed.
        # Earlier this triggered both a redundant LLM "Run sudo …"
        # panel AND a self-rewrite offer for `askbook.py` after a
        # PermissionError on /root/cant-write.org — clean noise.
        if getattr(hint, "user_caused", False):
            return
        # High-confidence pattern + crash NOT in our code: the user has
        # a precise next step (e.g. `ollama serve`); skip both the LLM
        # diagnosis AND the self-rewrite — there's nothing in our
        # source to fix.
        if hint.confidence == "high" and not crash_in_our_code:
            return
        # High-confidence + crash IS in our code (NameError, ImportError
        # in our module, etc): skip the LLM diagnosis (the registry
        # already nailed it) BUT fall through to the self-rewrite
        # offer below — that's the "fix the app itself" path the user
        # asked us to preserve.
        if hint.confidence == "high" and crash_in_our_code:
            skip_llm_diagnosis = True
        # Medium-confidence: keep both LLM diagnosis + self-rewrite for
        # a second opinion.

    # 1b. Diagnosis — what + why + manual fix (LLM fallback)
    sys_msg = (
        "You diagnose Python exceptions from a CLI tool called org-llm. "
        "Output STRICTLY in this format (no preamble, no markdown):\n"
        "  WHY: <one sentence — the likely root cause>\n"
        "  FIX: <one concrete shell command the user should run, or "
        "       'manual:' followed by a 1-line manual step>\n"
        "  WHY-IT-WORKS: <one sentence justifying the fix>\n"
        "Be honest if the fix is uncertain. Never invent flags or "
        "subcommands that don't exist. Stick to shell-safe commands."
    )
    user_msg = (
        f"User ran: org-llm {' '.join(argv)}\n\n"
        f"Exception type: {err_type}\n"
        f"Exception message: {err_msg}\n\n"
        f"Traceback tail:\n{tb_tail}"
    )
    advice = ""
    rescue_err = ""
    # When the structured registry already produced a high-confidence
    # hint, skip the (slow, less-grounded) LLM diagnosis — but keep
    # falling through to the self-rewrite offer below for crashes in
    # our code.
    if skip_llm_diagnosis:
        rescue_err = ""  # explicit: nothing failed, we just skipped
    else:
      try:
        from .llm import chat as _chat
        from .ui  import thinking as _thinking
        engine_now = _engine()
        with get_session(engine_now) as session:
            url = _ollama_url(session)
            # Prefer the smallest pulled model for rescue — the user is
            # already mid-crash and a 30s phi3.5 wait makes things worse.
            # Match the personalize pattern: try a known-small list first,
            # fall back to fast_model / chat_model only if none pulled.
            mdl = ""
            try:
                from .models import similar_pulled_model as _spm
                # similar_pulled_model returns a real pulled tag for any
                # query; using "llama3.2:1b" as the wishlist and falling
                # through to whatever's actually local.
                for cand in ("llama3.2:1b", "llama3.2:3b", "phi3.5"):
                    hit = _spm(cand, url)
                    if hit:
                        mdl = hit
                        break
            except Exception:
                pass
            if not mdl:
                mdl = (_cfg(session, "fast_model")
                       or _cfg(session, "chat_model")
                       or MODEL_DEFAULTS["chat_model"])
        import threading as _thr
        result: dict = {"text": "", "err": ""}
        def _run():
            try:
                result["text"] = _chat(user_msg, model=mdl, base_url=url,
                                         system=sys_msg, timeout=30.0) or ""
            except Exception as e:
                result["err"] = f"{type(e).__name__}: {e}"
        with _thinking("LLM rescue", model=mdl):
            t = _thr.Thread(target=_run, daemon=True)
            t.start(); t.join(timeout=30.0)
        if t.is_alive():
            rescue_err = "rescue LLM call timed out (>30s)"
        elif result["err"]:
            rescue_err = result["err"]
        else:
            # Models occasionally emit ```bash …``` fences inside the
            # FIX line despite the system prompt saying no markdown.
            # Strip them so the Panel renders clean shell snippets,
            # not literal backticks.
            import re as _re
            advice = (result["text"] or "").strip()
            advice = _re.sub(r"```[a-z]*\n?", "", advice)
            advice = _re.sub(r"\n?```", "", advice).strip()
      except Exception as e:
        rescue_err = f"{type(e).__name__}: {e}"
    if advice:
        # Sanitize before presenting — the LLM has hallucinated bogus
        # `pip install` commands in this codebase before. We don't
        # rewrite the text (the user can always read what the model
        # said), but we DO add a yellow "verify before running" frame
        # when the advice contains banned shell patterns or commands
        # outside our small whitelist.
        from rich.panel import Panel
        try:
            from .rescue import sanitize_llm_advice as _san
            checked = _san(advice)
        except Exception:
            checked = None
        console.print()
        if checked is not None and not checked.safe:
            warn = "\n".join(f"  • {f}" for f in checked.flagged)
            console.print(Panel(
                f"[yellow]LLM advice flagged — verify before running:"
                f"[/yellow]\n{warn}\n\n{advice}",
                title="[warn]LLM rescue (suspect)[/warn]",
                border_style="warn", padding=(1, 2),
            ))
        else:
            console.print(Panel(advice, title="[lcars1]LLM rescue[/lcars1]",
                                  border_style="lcars2", padding=(1, 2)))
    else:
        # Honest about what failed — was a generic
        # "(LLM unreachable for diagnosis)" with no clue whether the
        # model timed out / hit OOM / refused / wasn't pulled.
        if rescue_err:
            _on(f"[dim](LLM rescue failed: {rescue_err})[/dim]")
        else:
            # _llm_one_liner returned its empty fallback — model returned
            # an empty / malformed response, didn't raise.
            _on("[dim](LLM rescue produced no diagnosis — model may have "
                "returned empty / refused; see traceback below.)[/dim]")
        _on(tb_tail.splitlines()[-1] if tb_tail.splitlines() else "")

    # 2. Optional self-rewrite — only when crash is in OUR code AND only
    #    after explicit user opt-in. Snapshots first via the existing
    #    self_mod machinery, so a bad patch is one `org-llm self rollback`
    #    away. We never auto-apply; the user reviews the patch summary.
    target = _our_module_in_traceback(exc)
    if not target:
        return
    if not sys.stdin.isatty() or not sys.stdout.isatty():
        # Non-interactive (CI, piped) — don't prompt for self-rewrite.
        return
    try:
        console.print()
        console.print(f"[lcars3]Crash frame is inside org-llm itself "
                       f"({target.name}).[/lcars3]")
        ans = input("Try LLM self-rewrite of this module to fix the bug? "
                     "[y/N] ").strip().lower()
    except (KeyboardInterrupt, EOFError):
        console.print()
        return
    if ans not in {"y", "yes", "yeah", "yep", "sure", "ok"}:
        return

    # Snapshot before any mutation (matches `org-llm self llm-revise`)
    try:
        from . import self_mod as _sm
    except Exception as e:
        _on(f"[dim]self-mod module unavailable: {e}[/dim]")
        return
    try:
        snap = _sm.create_snapshot(
            label=f"pre-llm-rescue-{err_type}")
        _on(f"[dim]Snapshot saved: {snap.id}[/dim]")
    except Exception as e:
        _on(f"[red]Refusing self-rewrite: snapshot failed ({e}).[/red]")
        return

    # Ask the LLM for a JSON patch via the existing self-mod flow.
    try:
        engine_now = _engine()
        with get_session(engine_now) as session:
            url   = _ollama_url(session)
            model = (_cfg(session, "code_model")
                     or _cfg(session, "chat_model")
                     or "llama3.2")
        intent = (
            f"Runtime exception during `org-llm {' '.join(argv)}`:\n"
            f"  {err_type}: {err_msg}\n"
            f"Traceback tail:\n{tb_tail}\n\n"
            f"Patch this file to fix the root cause. Keep the diff minimal."
        )
        with warp(f"LLM proposing patch for {target.name}…"):
            plan = _sm.llm_revise(target, intent,
                                   model=model, base_url=url)
    except Exception as e:
        _on(f"[red]LLM rewrite failed to propose a patch: {e}[/red]")
        _on(f"[dim]Roll back the safety snapshot if needed: "
            f"[bold]org-llm self rollback {snap.id}[/bold][/dim]")
        return
    if not plan or not plan.get("ops"):
        _on("[dim]LLM didn't propose any changes.[/dim]")
        return

    # Show the plan summary, NOT the raw JSON — keep the user in the loop.
    summary = plan.get("summary") or "(no summary)"
    risk    = plan.get("risk")    or "(unknown risk)"
    test_h  = plan.get("test_hint") or "(no test hint)"
    n_ops   = len(plan.get("ops") or [])
    _on(f"[lcars2]Proposed patch ({n_ops} op{'s' if n_ops != 1 else ''}):[/lcars2]")
    _on(f"  [lcars1]summary:[/lcars1]   {summary}")
    _on(f"  [lcars1]risk:[/lcars1]      {risk}")
    _on(f"  [lcars1]test hint:[/lcars1] {test_h}")
    try:
        confirm = input("Apply this patch? [y/N] ").strip().lower()
    except (KeyboardInterrupt, EOFError):
        return
    if confirm not in {"y", "yes", "yeah", "yep", "sure", "ok"}:
        return
    ok, msg = _sm.apply_plan(target, plan)
    if not ok:
        _on(f"[red]Patch refused: {msg}[/red]")
        return
    _on(f"[lcars3]Patch applied to {target.name}.[/lcars3]")

    # Auto-verify by re-running the failing command. If the patch made
    # things worse (still raises, or now raises something else), roll back
    # automatically so the user is always returned to a known-good state.
    try:
        verify = input("Test the patch now by re-running your command? "
                        "[Y/n] ").strip().lower()
    except (KeyboardInterrupt, EOFError):
        verify = ""
    if verify in {"n", "no", "nope", "skip"}:
        _on(f"[dim]Skipped verification. To roll back: "
            f"[bold]org-llm self rollback {snap.id}[/bold][/dim]")
        return
    import subprocess as _sp
    _on(f"[dim]→ org-llm {' '.join(argv)}[/dim]")
    try:
        proc = _sp.run(["org-llm", *argv], timeout=300)
    except FileNotFoundError:
        _on("[red]org-llm binary not on PATH for verification.[/red]")
        _on(f"[dim]Roll back manually if needed: "
            f"[bold]org-llm self rollback {snap.id}[/bold][/dim]")
        return
    except Exception as e:
        _on(f"[red]Verification subprocess failed to spawn: {e}[/red]")
        return
    if proc.returncode == 0:
        _on(f"[lcars3]✓ Patch verified — your command now exits cleanly.[/lcars3]")
        _on(f"[dim]Snapshot kept just in case: {snap.id} "
            f"(see [bold]org-llm self snapshots[/bold])[/dim]")
        # Optional: commit the verified patch to git + push to a
        # feature branch. Documents the self-rewrite trail and gets
        # the change OFF the user's machine so it's reviewable from
        # GitHub. Strict gates: only when (a) the install lives in a
        # git checkout, (b) we're on an interactive TTY, and (c) the
        # user explicitly opts in. We never push to main directly —
        # always a `self-rewrite/<ts>-<exc>` branch the user can PR.
        _maybe_publish_self_rewrite(target, snap, exc, argv)
        return
    # Patch didn't help → automatic rollback (this is the "of course
    # full rollback if re-written" guarantee).
    _on(f"[red]✗ Re-run still failed (exit {proc.returncode}). "
        f"Rolling back automatically…[/red]")
    try:
        # rollback() takes a Snapshot object — we still have the one we
        # created above. also_db=False because the patch only touched
        # source code, not the DB; restoring the DB would lose any
        # writes from between snapshot and now (e.g. fresh embeddings).
        summary = _sm.rollback(snap, also_db=False)
        n_restored = summary.get("restored_files", 0) if isinstance(
            summary, dict) else "?"
        _on(f"[lcars3]Rolled back to snapshot {snap.id} "
            f"({n_restored} files restored). "
            f"Your code is back to its pre-patch state.[/lcars3]")
    except Exception as e:
        _on(f"[red]Auto-rollback raised: {e}. Manual fallback: "
            f"[bold]bash ~/.local/share/org-llm/snapshots/"
            f"{snap.id}/rollback.sh[/bold][/red]")


def main():
    """Top-level entry.

    Recovery chain for ARGV PARSE errors (UsageError):
      0. Fuzzy-match an unknown subcommand to a close one.
      1. Deterministic shell-quote repair.
      2. LLM intent reconstruction → execute.
      3. SRE-style LLM-assisted infra fix.

    Recovery for RUNTIME errors (anything else uncaught):
      • LLM diagnosis with concrete fix suggestion via
        `_llm_diagnose_uncaught`. Never auto-retries — the failing
        command may have been state-mutating.

    Be proactive on the parse side; be cautious on the runtime side.
    """
    import sys
    from click.exceptions import UsageError as _ClickUsageError
    from .logbook import write_event as _log_event
    invocation_started = time.monotonic()

    def _invoke(argv: list[str] | None = None):
        """Invoke the Typer app with standalone_mode=False so UsageErrors
        propagate up here instead of being caught + printed by Click."""
        click_cmd = typer.main.get_command(app)
        return click_cmd.main(args=argv, prog_name="org-llm",
                                standalone_mode=False)

    def _log_invocation(outcome: str, response: str = "") -> None:
        """Best-effort: record this CLI invocation to the logbook so dbt
        analytics + the user's vault have a primary-source record. Never
        raises into the caller (logbook swallows internally)."""
        argv_str = " ".join(sys.argv[1:]) or "(no args)"
        verb = (sys.argv[1] if len(sys.argv) > 1 and not sys.argv[1].startswith("-")
                 else "")
        _log_event("cli", verb or "(root)",
                    args=argv_str, outcome=outcome,
                    response=response[:1500] if response else "",
                    duration_ms=int((time.monotonic() - invocation_started) * 1000))
        # Auto-reflect cadence: every Nth successful CLI invocation,
        # run a quick Captain's Log reflection and surface ONE line of
        # findings. Skip when the verb is itself `log` (avoid recursion)
        # or `setup` (interrupts the wizard) or when N=0 (disabled).
        if outcome != "ok" or verb in ("log", "setup", "init", "doctor"):
            return
        try:
            from .db import History, Config
            from sqlalchemy.orm import Session
            from .db import DB_PATH, make_engine
            from pathlib import Path as _P
            db = _P(os.environ.get("ORG_LLM_DB") or str(DB_PATH))
            if not db.exists():
                return
            engine = make_engine(db)
            with Session(engine) as s:
                cfg = s.get(Config, "log_auto_reflect_every")
                try:
                    cadence = int(cfg.value) if cfg and cfg.value else 0
                except ValueError:
                    cadence = 0
                if cadence <= 0:
                    return
                n_cli = s.query(History).filter(
                    History.kind == "cli", History.outcome == "ok").count()
                if n_cli % cadence != 0 or n_cli == 0:
                    return
                # Pull the last `cadence` events for the LLM's window
                rows = (s.query(History).order_by(History.id.desc())
                            .limit(cadence).all())
                url   = (s.get(Config, "ollama_url").value
                          if s.get(Config, "ollama_url")
                          else "http://localhost:11434")
                model = ((s.get(Config, "fast_model") or
                           s.get(Config, "chat_model")) or None)
                model = model.value if model else "llama3.2"
            reflection = _captains_log_reflect(rows, model, url)
            if not reflection:
                return
            # Surface only the HEADLINE line so we don't take over the
            # user's terminal. Full reflection is logged to the org file.
            from .ui import on_screen as _on_r
            for line in reflection.splitlines():
                if line.strip().lower().startswith("headline"):
                    headline = line.split(":", 1)[-1].strip()
                    if headline:
                        _on_r(f"[lcars3]Captain's Log:[/lcars3] {headline}  "
                              f"[dim](full: org-llm log --reflect)[/dim]")
                    break
            _log_event("doctor", "log-auto-reflect",
                        args=f"window={cadence} cadence={cadence}",
                        model=model, response=reflection, outcome="ok")
        except Exception:
            pass

    def _abort_on_ctrl_c():
        """Print a clean one-liner and exit 130 (128 + SIGINT)."""
        try:
            from .ui import on_screen as _on_int
            console.print()
            _on_int("[yellow]Interrupted (Ctrl-C). "
                    "Partial work is preserved — re-run when ready.[/yellow]")
        except Exception:
            print("\nInterrupted (Ctrl-C).", file=sys.stderr)
        sys.exit(130)

    def _surface_auto_embed_status() -> None:
        """If the background watcher reported recent activity, mention
        it in a one-line dim footer so the user has UI surfacing without
        any explicit query. Skips when the watcher is silent."""
        try:
            from . import auto_embedder as _ae
            if not _ae.status_is_fresh():
                return
            summary = _ae.status_summary()
            if not summary:
                return
            # Skip during `org-llm watch` — would echo the watcher's
            # own output back at it.
            if len(sys.argv) > 1 and sys.argv[1] == "watch":
                return
            from .ui import on_screen as _on_ae
            _on_ae(f"[dim]· {summary}[/dim]")
        except Exception:
            pass

    try:
        _invoke()
        _log_invocation("ok")
        _surface_auto_embed_status()
        return
    except KeyboardInterrupt:
        _log_invocation("interrupted")
        _abort_on_ctrl_c()
    except _ClickUsageError as exc:
        original_error = str(exc)
        # Don't log here — falls through to recovery layers; we'll log
        # the FINAL outcome at the bottom of main().
    except SystemExit as se:
        # Clean exit (typer.Exit(0) / sys.exit(0)) — pass through unchanged
        # but log the exit code first so the org log shows "ok" vs nonzero.
        try:
            code = int(se.code) if se.code is not None else 0
        except (TypeError, ValueError):
            code = 1
        _log_invocation("ok" if code == 0 else f"exit:{code}")
        raise
    except Exception as runtime_exc:
        # User pressed N at a typer.confirm() / Ctrl-D'd a typer.prompt() —
        # click raises Abort. That's not a crash, it's a normal user
        # cancel. Don't run the LLM-rescue (which is expensive AND
        # makes "exited cleanly" feel like a failure).
        from click.exceptions import Abort as _ClickAbort
        if isinstance(runtime_exc, _ClickAbort):
            _log_invocation("aborted")
            on_screen("[dim]Aborted.[/dim]")
            sys.exit(130)
        # Anything else uncaught — LLM rescue. We deliberately don't catch
        # this earlier (each command can still raise typer.Exit cleanly);
        # this is the "Python crashed in a command body" path.
        _log_invocation("crash", response=f"{type(runtime_exc).__name__}: {runtime_exc}")
        _llm_diagnose_uncaught(runtime_exc, list(sys.argv[1:]))
        sys.exit(1)
        # Be proactive: try recovery for ALL parse errors, not just "extra
        # arguments". Bad subcommand, bad flag, missing required arg —
        # the LLM can guess intent for any of them.

    argv = list(sys.argv[1:])
    from .ui import on_screen as _on

    # ── Layer 0: deterministic fuzzy-match for unknown subcommand ─────────
    if "no such command" in original_error.lower() and argv:
        import difflib as _dl
        first = argv[0]
        try:
            known = sorted(typer.main.get_command(app).commands.keys())
        except Exception:
            known = []
        # Skip layer-0 when argv[0] is already a valid top-level verb —
        # the unknown subcommand is at argv[1+] and difflib would just
        # match argv[0] to itself, producing a confusing
        # "did you mean knob? Retrying" self-loop.
        if first in known:
            guess = []
        else:
            guess = _dl.get_close_matches(first, known, n=1, cutoff=0.6)
        if guess:
            _on(f"[yellow]Unknown command [bold]{first!r}[/bold] — "
                f"did you mean [bold]{guess[0]}[/bold]? Retrying.[/yellow]")
            argv = [guess[0]] + argv[1:]
            try:
                _invoke(argv)
                return
            except KeyboardInterrupt:
                _abort_on_ctrl_c()
            except _ClickUsageError as exc:
                original_error = str(exc)

    # ── Layer 1: deterministic shell-quote repair ─────────────────────────
    repaired = _shell_quote_repair(argv)
    if repaired and repaired != argv:
        _on(f"[yellow]Auto-repairing shell quoting and retrying:[/yellow]")
        _on(f"  [dim]→[/dim] [bold]org-llm {' '.join(repaired)}[/bold]")
        try:
            _invoke(repaired)
            return
        except KeyboardInterrupt:
            _abort_on_ctrl_c()
        except _ClickUsageError as exc:
            original_error = str(exc)
            argv = repaired

    # ── Layer 2: LLM intent reconstruction → execute proactively ──────────
    intent_argv = _llm_intent_repair(argv, original_error)
    if intent_argv:
        _on(f"[yellow]LLM reconstructed intent — executing:[/yellow]")
        _on(f"  [dim]→[/dim] [bold]org-llm {' '.join(intent_argv)}[/bold]")
        try:
            _invoke(intent_argv)
            return
        except KeyboardInterrupt:
            _abort_on_ctrl_c()
        except _ClickUsageError:
            pass

    # ── Layer 3: SRE-style fix (config / doctor / models repairs) ─────────
    try:
        attempted = "org-llm " + " ".join(argv)
        if _llm_assisted_fix(
            error=f"Typer parse error: {' '.join(argv)!r} — {original_error}",
            attempted_command=attempted,
            context=("Shell quoting likely broke a single-string argument "
                     "into multiple positional tokens, OR the user typed an "
                     "unknown subcommand or flag. Pick the closest safe fix."),
        ):
            try:
                _invoke(argv)
                return
            except KeyboardInterrupt:
                _abort_on_ctrl_c()
            except _ClickUsageError:
                pass
    except KeyboardInterrupt:
        _abort_on_ctrl_c()
    except Exception:
        pass

    # All layers exhausted — print the original Typer error and a
    # context-aware hint. Branch on the parse-error shape so we don't
    # tell a user with `--versionx` to wrap their query in quotes.
    _on(f"[red]Could not auto-recover: {original_error}[/red]")
    err_lower = original_error.lower()
    if "no such option" in err_lower:
        # Try to fish the bad option out of the message and find a
        # close match against registered top-level options.
        import re as _re
        import difflib as _dl
        m = _re.search(r"no such option:?\s*['\"]?(-{1,2}[\w-]+)", err_lower)
        bad = m.group(1) if m else ""
        known: list[str] = []
        try:
            click_cmd = typer.main.get_command(app)
            for p in click_cmd.params:
                known.extend(p.opts)   # collects '--version', '-V', etc.
        except Exception:
            pass
        guess = _dl.get_close_matches(bad, known, n=1, cutoff=0.6) if bad else []
        if guess:
            _on(f"[dim]Did you mean[/dim] [bold]{guess[0]}[/bold]?  "
                f"[dim]See[/dim] [bold]org-llm --help[/bold] [dim]for all flags.[/dim]")
        else:
            _on("[dim]Run[/dim] [bold]org-llm --help[/bold] "
                "[dim]to see valid flags, or[/dim] "
                "[bold]org-llm <verb> --help[/bold] [dim]for one verb.[/dim]")
    elif "no such command" in err_lower:
        # If argv[0] is a known top-level verb but argv[1] is the
        # unknown one, the user typed a bad SUBcommand — point them at
        # the verb's own help, not the global help. Otherwise fall
        # back to the global hint.
        verb = (sys.argv[1] if len(sys.argv) > 1
                  and not sys.argv[1].startswith("-") else "")
        try:
            known_top = set(typer.main.get_command(app).commands.keys())
        except Exception:
            known_top = set()
        if verb in known_top and len(sys.argv) > 2:
            _on(f"[dim]Run[/dim] [bold]org-llm {verb} --help[/bold] "
                f"[dim]to see[/dim] [lcars2]{verb}[/lcars2] "
                f"[dim]subcommands.[/dim]")
        else:
            _on("[dim]Run[/dim] [bold]org-llm --help[/bold] "
                "[dim]to see all subcommands, or[/dim] "
                "[bold]org-llm splash[/bold] [dim]for a quick menu.[/dim]")
    elif ("missing argument" in err_lower
            or "missing option" in err_lower
            or "missing parameter" in err_lower):
        # `org-llm self show` produces "Missing parameter: module" —
        # the third synonym Click/Typer use. Without it, the catch-all
        # printed the irrelevant ask shell-quoting tip.
        verb = (sys.argv[1] if len(sys.argv) > 1
                  and not sys.argv[1].startswith("-") else "")
        if verb:
            _on(f"[dim]Add the missing argument or run[/dim] "
                f"[bold]org-llm {verb} --help[/bold] "
                f"[dim]to see what's required.[/dim]")
        else:
            _on("[dim]Add the missing argument or run[/dim] "
                "[bold]org-llm <verb> --help[/bold] [dim]to see what's "
                "required.[/dim]")
    elif "missing command" in err_lower:
        # Typer raises this when a verb group (e.g. `org-llm knob`,
        # `org-llm config` without subverb) was invoked without a
        # required subcommand. The generic shell-quote tip is wrong
        # here — point at the subcommand list instead.
        verb = (sys.argv[1] if len(sys.argv) > 1
                  and not sys.argv[1].startswith("-") else "")
        if verb:
            _on(f"[dim]Run[/dim] [bold]org-llm {verb} --help[/bold] "
                f"[dim]to see[/dim] [lcars2]{verb}[/lcars2] "
                f"[dim]subcommands.[/dim]")
        else:
            _on("[dim]Run[/dim] [bold]org-llm --help[/bold] "
                "[dim]to see all verbs.[/dim]")
    elif "ambiguous prefix" in err_lower:
        # PrefixGroup already lists the matching verbs in the error
        # body; don't tack on the shell-quote tip — the user just
        # needs to add more characters or type the full verb.
        _on("[dim]Type more of the verb name to disambiguate, or "
            "use[/dim] [bold]org-llm --help[/bold] [dim]to see all "
            "verbs.[/dim]")
    elif "got unexpected extra argument" in err_lower:
        # The user passed too many positional args (or a flag-only
        # command got bare text). Pull the actual verb from argv so
        # the hint points at THAT command's --help, not generic ask.
        verb = (sys.argv[1] if len(sys.argv) > 1
                  and not sys.argv[1].startswith("-") else "")
        if verb:
            _on(f"[dim]Run[/dim] [bold]org-llm {verb} --help[/bold] "
                f"[dim]to see what arguments[/dim] [lcars2]{verb}[/lcars2] "
                f"[dim]actually accepts (it may use --flag-style options).[/dim]")
        else:
            _on("[dim]Run[/dim] [bold]org-llm <verb> --help[/bold] "
                "[dim]for the verb you tried.[/dim]")
    else:
        # Generic catch-all — the shell-quoting hint applies to ask /
        # search where unquoted multi-word input is the most common
        # failure shape.
        _on("[dim]Tip: wrap the query in single quotes — "
            "[bold]org-llm ask 'your full question here'[/bold][/dim]")
    _log_invocation("unrecovered_parse_error", response=original_error)
    sys.exit(2)
# cli.py:1 ends here
